insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ هَذَا الْأَمْرُ فِي قُرَيْشٍ مَا بَقِيَ مِنَ النَّاسِ اثْنَانِ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളിൽനിന്ന് രണ്ടുപേർ മാത്രം ശേഷിക്കുന്ന കാലം വരേയും ഇക്കാര്യം (ഭരണാധികാരം) ഖുറൈശീ ഗോത്രത്തിലായിരിക്കും." (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "النَّاسُ تَبَعٌ لِقُرَيْشٍ فِي هَذَا الشَّأْنِ، مُسْلِمُهُمْ تَبَعٌ لِمُسْلِمِهِمْ، وَكَافِرُهُمْ تَبَعٌ لِكَافِرِهِمْ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇക്കാര്യത്തിൽ ജനങ്ങൾ ഖുറൈശികളുടെ പിന്തുടർച്ചക്കാരാണ്. ജനങ്ങളിലെ മുസ്ലിംകൾ ഖുറൈഷികളിലെ മുസ്ലിംകളുടെ പിന്തുടർച്ചക്കാരും, അവരിലെ സത്യനിഷേധികൾ ഖുറൈഷികളിലെ സത്യനിഷേധികളുടെ പിന്തുടർച്ചക്കാരുമാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَتَبْتُ إِلَى جَابِرِ بْنِ سَمُرَةَ مَعَ غُلَامِي نَافِعٍ: أَنْ أَخْبِرْنِي بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَكَتَبَ إِلَيَّ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ جُمُعَة، عَشِيَّةَ رُجِمَ الْأَسْلَمِيُّ، فَقَالَ: "لَا يَزَالُ الدِّينُ قَائِمًا حَتَّى تَقُومَ السَّاعَةُ، أَوْ يَكُونَ عَلَيْكُمْ اثْنَا عَشَرَ خَلِيفَةً كُلُّهُمْ مِنْ قُرَيْشٍ". وَسَمِعْتُهُ يَقُولُ: "عُصَيْبَةٌ مِنَ الْمُسْلِمِينَ يَفْتَتِحُونَ الْبَيْتَ الْأَبْيَضَ بَيْتَ كِسْرَى، أَوْ: آلِ كِسْرَى". وَسَمِعْتُهُ يَقُولُ: "إِنَّ بَيْنَ يَدَيِ السَّاعَةِ كَذَّابِينَ، فَاحْذَرُوهُمْ". وَسَمِعْتُهُ يَقُولُ: "إِذَا أَعْطَى اللَّهُ أَحَدَكُمْ خَيْرًا فَلْيَبْدَأْ بِنَفْسِهِ وَأَهْلِ بَيْتِهِ". وَسَمِعْتُهُ يَقُولُ: "أَنَا الْفَرَطُ عَلَى الْحَوْضِ". (م)', 'ആമിറുബ്നു സഅ്ദിബ്നു അബീവഖാസ്(റ): എന്റെ അടിമയായ നാഫിഅ്(റ)വിന്റെ പക്കൽ ജാബിറുബ്നു സമുറ(റ)വിന്നായി ഞാൻ ഇപ്രകാരം ഒരു എഴുത്ത് എഴുതി അയച്ചു: റസൂൽ(സ)യിൽനിന്ന് നിങ്ങൾ കേട്ട എന്തെങ്കിലും എനിക്ക് അറിയിച്ചു തന്നാലും. നിവേദകൻ പറയുന്നു: അപ്പോൾ അദ്ദേഹം എനിക്ക് ഇപ്രകാരം എഴുതി: അസ്ലമി (മാഇസുബ്നു മാലിക്) എറിഞ്ഞു കൊല്ലപ്പെട്ട വെള്ളിയാഴ്ച വൈകുന്നേര സമയത്ത് റസൂൽ(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടു: "അന്ത്യനാൾ വരെ ദീൻ നിലനിൽക്കും. അല്ലെങ്കിൽ: നിങ്ങൾക്ക് പന്ത്രണ്ട് ഖലീഫമാരുണ്ടാകുന്നതുവരെ. അവരെല്ലാവരും ഖുറൈഷിൽ നിന്നുള്ളവർ ആയിരിക്കും." അവിടുന്ന് ഇപ്രകാരം പറയുന്നതും ഞാൻ കേട്ടു: "മുസ്ലിംകളിൽ നിന്നുള്ള ഒരു സംഘം വെളുത്ത വീട് കീഴടക്കും. അഥവാ കിസ്റായുടെ വീട്, അല്ലെങ്കിൽ: കിസ്റയുടെ കുടുംബത്തിന്റെ വീട്." അവിടുന്ന് ഇപ്രകാരം പറയുന്നതും ഞാൻ കേട്ടു: "അന്ത്യനാളിന്റെ മുമ്പ് കളവ് പറയുന്നവർ ധാരാളം ഉണ്ടാവും. അപ്പോൾ നിങ്ങൾ അവരെ സൂക്ഷിക്കുക." അവിടുന്ന് ഇപ്രകാരം പറയുന്നതും ഞാൻ കേട്ടു: "നിങ്ങളിലാർക്കെങ്കിലും അല്ലാഹു വല്ല നന്മയും നൽകിയാൽ അവൻ തന്റെ സ്വന്തത്തിൽ നിന്നും തന്റെ കുടുംബത്തിൽ നിന്നും തുടങ്ങിക്കൊള്ളട്ടെ." അവിടുന്ന് ഇപ്രകാരം പറയുന്നതും ഞാൻ കേട്ടു: "(ജനങ്ങൾക്ക് സൗകര്യങ്ങളൊരുക്കാനായി) ഹൗളുൽകൗസറിന്റെ അടുത്ത് ആദ്യം എത്തുന്നത് ഞാനായിരിക്കും." (മു)', 'عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'ആമിറുബ്നു സഅ്ദിബ്നു അബീവഖാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 119, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: دَخَلْتُ عَلَى حَفْصَةَ رَضِيَ اللهُ عَنْهَا فَقَالَتْ: أَعَلِمْتَ أَنَّ أَبَاكَ غَيْرُ مُسْتَخْلِفٍ؟ قَالَ: قُلْتُ: مَا كَانَ لِيَفْعَلَ، قَالَتْ: إِنَّهُ فَاعِلٌ، قَالَ: فَحَلَفْتُ أَنِّي أُكَلِّمُهُ فِي ذَلِكَ، فَسَكَتُّ حَتَّى غَدَوْتُ وَلَمْ أُكَلِّمْهُ، قَالَ: فَكُنْتُ كَأَنَّمَا أَحْمِلُ بِيَمِينِي جَبَلًا، حَتَّى رَجَعْتُ فَدَخَلْتُ عَلَيْهِ، فَسَأَلَنِي عَنْ حَالِ النَّاسِ وَأَنَا أُخْبِرُهُ، قَالَ: ثُمَّ قُلْتُ لَهُ: إِنِّي سَمِعْتُ النَّاسَ يَقُولُونَ مَقَالَةً، فَآلَيْتُ أَنْ أَقُولَهَا لَكَ، زَعَمُوا أَنَّكَ غَيْرُ مُسْتَخْلِفٍ، وَإِنَّهُ لَوْ كَانَ لَكَ رَاعِي إِبِلٍ أَوْ رَاعِي غَنَمٍ، ثُمَّ جَاءَكَ وَتَرَكَهَا رَأَيْتَ أَنْ قَدْ ضَيَّعَ، فَرِعَايَةُ النَّاسِ أَشَدُّ. قَالَ: فَوَافَقَهُ قَوْلِي، فَوَضَعَ رَأْسَهُ سَاعَةً ثُمَّ رَفَعَهُ إِلَيَّ فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يَحْفَظُ دِينَهُ، وَإِنِّي لَئِنْ لَا أَسْتَخْلِفْ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَسْتَخْلِفْ، وَإِنْ أَسْتَخْلِفْ فَإِنَّ أَبَا بَكْرٍ رَضِيَ اللهُ عَنْهُ قَدِ اسْتَخْلَفَ. قَالَ: فَوَاللَّهِ مَا هُوَ إِلَّا أَنْ ذَكَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ، فَعَلِمْتُ أَنَّهُ لَمْ يَكُنْ لِيَعْدِلَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَدًا، وَأَنَّهُ غَيْرُ مُسْتَخْلِفٍ. (م,د,ت)', 'ഇബ്നുഉമർ(റ): ഞാൻ ഹഫ്സ(റ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ മഹതി ചോദിച്ചു: നിശ്ചയം നിങ്ങളുടെ പിതാവ് (തന്റെ പകരക്കാരനായ) അടുത്ത ഖലീഫയെ നിശ്ചയിക്കുന്നില്ലെന്ന കാര്യം നിങ്ങളറിഞ്ഞോ? നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അദ്ദേഹം അങ്ങനെ ചെയ്യരുതായിരുന്നു. മഹതി പറഞ്ഞു: തീർച്ചയായും അദ്ദേഹം അത് ചെയ്യുന്നതാണ്. നിവേദകൻ പറയുന്നു: തീർച്ചയായും ഇവ്വിഷയത്തിൽ അദ്ദേഹവുമായി സംസാരിക്കുമെന്ന് അപ്പോൾ ഞാൻ സത്യംചെയ്തു. അങ്ങനെ പ്രഭാതമാകുംവരെ ഞാൻ മൗനം ദീക്ഷിച്ചു. അദ്ദേഹത്തോട് ഒന്നുംതന്നെ ഞാൻ സംസാരിച്ചതുമില്ല. നിവേദകൻ പറയുന്നു: എന്റെ വലതുഭാഗത്ത് ഒരു മല ഞാൻ ചുമക്കുന്നതു പോലെയായിരുന്നു അന്നേരം എന്റെ അവസ്ഥ. അങ്ങനെ ഞാൻ അദ്ദേഹത്തിന്റെ അടുക്കലേക്ക് മടങ്ങിച്ചെന്നു. അപ്പോൾ അദ്ദേഹമെന്നോട് ജനങ്ങളുടെ അവസ്ഥകളെക്കുറിച്ച് ചോദിച്ചു. ഞാനദ്ദേഹത്തിന് എല്ലാം പറഞ്ഞു കൊടുക്കുന്നുമുണ്ട്. നിവേദകൻ പറയുന്നു: പിന്നെ ഞാൻ അദ്ദേഹത്തോട് ഇപ്രകാരം പറഞ്ഞു: ജനങ്ങളുടെ സംസാരം ഞാൻ കേട്ടു. അത് അങ്ങയോട് പറയണമെന്ന് ഞാൻ സത്യം ചെയ്തിരിക്കുന്നു. താങ്കൾ അടുത്ത ഖലീഫയെ നിശ്ചയിക്കുന്നില്ലെന്നാണ് അവർ പറയുന്നത്. ആടുകളെയോ അല്ലെങ്കിൽ ഒട്ടകങ്ങളെയോ മേക്കുന്ന ഒരാൾ അങ്ങേക്കുണ്ടെങ്കിൽ, അവൻ അവയെ ഉപേക്ഷിച്ച് അങ്ങയുടെ അടുക്കൽ വന്നാൽ, നിശ്ചയം അവൻ അവയെ അവഗണിച്ചതായി അങ്ങ് മനസ്സിലാക്കും. എങ്കിൽ ജനങ്ങളെ ഭരിക്കുന്ന കാര്യം അതിലേറെ ശക്തിയേറിയതാണ്. നിവേദകൻ പറയുന്നു: എന്റെ വാക്കുകൾ അദ്ദേഹത്തെ അത്ഭുതപ്പെടുത്തി. അദ്ദേഹം അൽപനേരം തല താഴ്ത്തിവെച്ച് പിന്നെ എന്റെ നേരെ തല ഉയർത്തിയിട്ട് ഇപ്രകാരം പറഞ്ഞു: നിശ്ചയം അല്ലാഹു അവന്റെ ദീനിനെ കാക്കും. ഞാൻ എന്റെ പകരക്കാരനെ നിശ്ചയിക്കുന്നില്ലെങ്കിൽ നിശ്ചയം റസൂൽ(സ) അവിടുത്തെ പകരക്കാരനെ നിശ്ചയിച്ചിട്ടില്ല. ഇനി ഞാൻ എന്റെ പകരക്കാരനെ നിശ്ചയിക്കുകയാണെങ്കിൽ നിശ്ചയം അബൂബക്ർ(റ) അദ്ദേഹത്തിന്റെ പകരക്കാരനെ നിശ്ചയിച്ചിട്ടുമുണ്ട്. നിവേദകൻ പറയുന്നു: അല്ലാഹുവാണ് സത്യം, അദ്ദേഹം റസൂൽ(സ)യെയും അബൂബക്ർ(റ)വിനെയും പറഞ്ഞതിൽനിന്ന് റസൂൽ(സ)യ്ക്ക് തുല്ല്യമായി ഒരാളെയും അദ്ദേഹം കാണുന്നില്ലെന്നും അദ്ദേഹം തന്റെ പകരക്കാരനെ നിശ്ചയിക്കാൻ പോകുന്നില്ലെന്നും ഞാൻ മനസ്സിലാക്കി. (മു,ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا بُويِعَ لِخَلِيفَتَيْنِ فَاقْتُلُوا الْآخَرَ مِنْهُمَا". (م)', 'അബൂസഈദുൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടു ഖലീഫമാർ ബൈഅത്ത് ചെയ്യപ്പെട്ടാൽ അവരിൽ രണ്ടാമനെ നിങ്ങൾ വധിച്ചുകളയുക." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا الْإِمَامُ جُنَّةٌ، يُقَاتَلُ مِنْ وَرَائِهِ وَيُتَّقَى بِهِ، فَإِنْ أَمَرَ بِتَقْوَى اللَّهِ وَعَدَلَ فَإِنَّ لَهُ بِذَلِكَ أَجْرًا، وَإِنْ أَمَرَ بِغَيْرِهِ فَإِنَّ عَلَيْهِ وِزْرًا". (م,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഇമാം അക്രമങ്ങളിൽനിന്നുള്ള പരിചയാണ്. അദ്ദേഹത്തിന്റെ പിന്നിൽനിന്ന് യുദ്ധംചെയ്യപ്പെടുകയും അദ്ദേഹത്താൽ സംരക്ഷിക്കപ്പെടുകയും ചെയ്യും. ഇമാം അല്ലാഹുവിനോടുള്ള തഖ്വ കൽപിക്കുകയും നീതി പാലിക്കുകയും ചെയ്താൽ, അതു കാരണമായി അദ്ദേഹത്തിന് പ്രതിഫലം ഉണ്ടായിരിക്കുന്നതാണ്. ഇനി അതല്ലാത്തത് ഇമാം കൽപിച്ചാൽ അദ്ദേഹത്തിന് കുറ്റവുമുണ്ടായിരിക്കുന്നതാണ്." (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْمُقْسِطِينَ عِنْدَ اللَّهِ عَلَى مَنَابِرَ مِنْ نُورٍ، عَنْ يَمِينِ الرَّحْمَنِ عَزَّ وَجَلَّ، وَكِلْتَا يَدَيْهِ يَمِينٌ، الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا". (م,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം തങ്ങളുടെ വിധികളിലും തങ്ങളുടെ കുടുംബങ്ങളിലും തങ്ങൾ ഏറ്റെടുത്ത കാര്യങ്ങളിലും നീതി പുലർത്തുന്ന നീതിമാന്മാർ യോഗ്യനും ഉന്നതനുമായ അല്ലാഹുവിങ്കൽ അവന്റെ വലതു ഭാഗത്തായി പ്രകാശത്താലുള്ള മിമ്പറുകളിൽ ആയിരിക്കും, അല്ലാഹുവിന്റെ ഇരു കൈകളും വലത്തേതാണ് (നന്മയുള്ളതാണ്)." (മു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خِيَارُ أَئِمَّتِكُمُ الَّذِينَ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ، وَيُصَلُّونَ عَلَيْكُمْ وَتُصَلُّونَ عَلَيْهِمْ. وَشِرَارُ أَئِمَّتِكُمُ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ، وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ". قِيلَ: يَا رَسُولَ اللَّهِ، أَفَلَا نُنَابِذُهُمْ بِالسَّيْفِ؟ فَقَالَ: "لَا، مَا أَقَامُوا فِيكُمُ الصَّلَاةَ، وَإِذَا رَأَيْتُمْ مِنْ وُلَاتِكُمْ شَيْئًا تَكْرَهُونَهُ فَاكْرَهُوا عَمَلَهُ، وَلَا تَنْزِعُوا يَدًا مِنْ طَاعَةٍ". (م)', 'ഔഫുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ നേതാക്കളിൽ ഏറ്റവും നല്ലവർ, നിങ്ങൾ അവരെയും അവർ നിങ്ങളെയും സ്നേഹിക്കുകയും, അവർ നിങ്ങൾക്കും നിങ്ങൾ അവർക്കും നന്മ നേരുകയും ചെയ്യുന്നവരാണ്. നിങ്ങളുടെ നേതാക്കളിൽ ഏറ്റവും ദുഷിച്ചവർ, നിങ്ങൾ അവരെയും അവർ നിങ്ങളെയും വെറുക്കുകയും, നിങ്ങൾ അവരെയും അവർ നിങ്ങളെയും ശപിക്കുകയും ചെയ്യുന്നവരാണ്." അപ്പോൾ ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങൾ അവരെ വാളിന് ഇരയാക്കട്ടെയോ? അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അവർ നിങ്ങളിൽ നിസ്കാരം നിലനിർത്തുന്ന കാലമത്രയും നിങ്ങളത് ചെയ്യരുത്, നിങ്ങൾ വെറുക്കുന്ന വല്ലതും നിങ്ങളുടെ ഭരണാധികാരികളിൽ നിങ്ങൾ കണ്ടാൽ ആ കാര്യം ചെയ്യൽ നിങ്ങൾ വെറുക്കുക, അനുസരണയിൽനിന്ന് നിങ്ങളുടെ കൈകൾ നിങ്ങൾ ഊരരുത്." (മു)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 121, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَرَادَ اللَّهُ بِالْأَمِيرِ خَيْرًا جَعَلَ لَهُ وَزِيرَ صِدْق: إِنْ نَسِيَ ذَكَّرَهُ، وَإِنْ ذَكَرَ أَعَانَهُ. وَإِذَا أَرَادَ اللَّهُ بِهِ غَيْرَ ذَلِكَ جَعَلَ لَهُ وَزِيرَ سُوءٍ: إِنْ نَسِيَ لَمْ يُذَكِّرْهُ، وَإِنْ ذَكَرَ لَمْ يُعِنْهُ". (د)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു അമീറിനെക്കൊണ്ട് നന്മ ഉദ്ദേശിച്ചാൽ, അദ്ദേഹം മറന്നാൽ അദ്ദേഹത്തെ ഓർമ്മിപ്പിക്കുന്ന, ഓർമ്മിച്ചാൽ അദ്ദേഹത്തെ സഹായിക്കുന്ന ഒരു സത്യസന്ധനായ മന്ത്രിയെ അദ്ദേഹത്തിന് നിയമിച്ചുകൊടുക്കും. ഇനി അമീറിനെക്കൊണ്ട് അല്ലാഹു അതല്ലാത്തത് ഉദ്ദേശിച്ചാൽ അദ്ദേഹം മറന്നാൽ അദ്ദേഹത്തെ ഓർമ്മിപ്പിക്കാത്ത, ഓർമ്മിച്ചാൽ അദ്ദേഹത്തെ സഹായിക്കാത്ത ദുഷ്ടനായ ഒരു മന്ത്രിയെ അല്ലാഹു അദ്ദേഹത്തിന് നിയമിച്ചുകൊടുക്കും." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ وَلِيَ مِنْكُمْ عَمَلًا، فَأَرَادَ اللَّهُ بِهِ خَيْرًا، جَعَلَ لَهُ وَزِيرًا صَالِحًا: إِنْ نَسِيَ ذَكَّرَهُ، وَإِنْ ذَكَرَ أَعَانَهُ".(ن)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ഒരു ഭരണാധികാരം ഏറ്റെടുക്കുകയും അല്ലാഹു അവനെക്കൊണ്ട് നന്മ ഉദ്ദേശിക്കുകയും ചെയ്താൽ, അവൻ മറന്നാൽ അവനെ ഓർമ്മിപ്പിക്കുന്ന, ഓർമ്മിച്ചാൽ അവനെ സഹായിക്കുന്ന നല്ലവനായ ഒരു മന്ത്രിയെ അല്ലാഹു അവന് നിശ്ചയിച്ചു കൊടുക്കുന്നതാണ്." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عَبْدَ الرَّحْمَنِ بْنَ سَمُرَةَ، لَا تَسْأَلِ الْإِمَارَةَ، فَإِنَّكَ إِذَا أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ فِيهَا إِلَى نَفْسِكَ، وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا". (ق,د,ت,ن,جه)', 'അബ്ദുർറഹ്മാനുബ്നു സമുറത്(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "ഓ അബ്ദുർറഹ്മാനുബ്നു സമുറ, താങ്കൾ അധികാരം ചോദിക്കരുത്. കാരണം, ചോദിച്ചതിനാൽ താങ്കൾക്ക് അധികാരം നൽകപ്പെട്ടാൽ, നിശ്ചയമായും അധികാരത്തിന്റെ കാര്യത്തിൽ താങ്കൾ സ്വന്തത്തിലേക്ക് ഏൽപിക്കപ്പെടും. ഇനി ചോദിക്കാതെ താങ്കൾക്ക് അധികാരം നൽകപ്പെട്ടാൽ അധികാരത്തിന്റെ കാര്യത്തിൽ താങ്കൾ സഹായിക്കപ്പെടും." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുർറഹ്മാനുബ്നു സമുറത്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: انْطَلَقْتُ مَعَ رَجُلَيْنِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَشَهَّدَ أَحَدُهُمَا، ثُمَّ قَالَ: جِئْنَا لِتَسْتَعِينَ بِنَا عَلَى عَمَلِكَ، وَقَالَ الْآخَرُ مِثْلَ قَوْلِ صَاحِبِهِ، فَقَالَ: "إِنَّ أَخْوَنَكُمْ عِنْدَنَا مَنْ طَلَبَهُ". فَاعْتَذَرَ أَبُو مُوسَى إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: لَمْ أَعْلَمْ لِمَا جَاءَا لَهُ. فَلَمْ يَسْتَعِنْ بِهِمَا عَلَى شَيْءٍ حَتَّى مَاتَ. (ق,د)', 'അബൂമൂസാ(റ): രണ്ട് ആളുകളുമായി ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ അവരിലൊരാൾ സാക്ഷ്യവചനങ്ങൾ ഉരുവിടുകയും പിന്നെ ഇപ്രകാരം പറയുകയും ചെയ്തു: അങ്ങയുടെ ഭരണകാര്യങ്ങളിൽ ഞങ്ങളോട് അങ്ങ് സഹായമഭ്യർത്ഥിക്കാനാണ് ഞങ്ങൾ വന്നിരിക്കുന്നത്. രണ്ടാമനും തന്റെ കൂട്ടുകാരൻ പറഞ്ഞതുപോലെത്തന്നെ പറഞ്ഞു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നമ്മുടെ പക്കൽ നിങ്ങളിലെ ഏറ്റവും വലിയ വഞ്ചകൻ അധികാരം ചോദിച്ചവനാണ്." അപ്പോൾ നബി(സ)യോട് ഒഴികഴിവ് പറഞ്ഞുകൊണ്ട് അബൂമൂസാ(റ) ഇപ്രകാരം പറഞ്ഞു: അവരെന്തിനാണ് വന്നതെന്ന് ഞാൻ അറിഞ്ഞിട്ടില്ലായിരുന്നു. പിന്നീട് വഫാത്താകുംവരെ അവർ രണ്ടുപേരോടും അവിടുന്ന് സഹായം തേടിയിട്ടില്ല. (ബു,മു,ദ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 122, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّكُمْ سَتَحْرِصُونَ عَلَى الْإِمَارَةِ، وَإِنَّهَا سَتَكُونُ نَدَامَةً وَحَسْرَةً يَوْمَ الْقِيَامَةِ، فَنِعْمَتِ الْمُرْضِعَةُ وَبِئْسَتِ الْفَاطِمَةُ". (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം വരുംകാലങ്ങളിൽ നിങ്ങൾ നേതൃത്വത്തിനുവേണ്ടി കൊതിക്കും. നിശ്ചയം അന്ത്യനാളിൽ നിങ്ങൾക്കത് ദുഃഖവും ഖേദവുമായി മാറും. അപ്പോൾ നേതൃത്വത്തിലേക്കെത്തിക്കുന്ന കാര്യം (ജീവിതം) ഉത്തമവും നേതൃത്വത്തെ അവസാനിപ്പിക്കുന്ന കാര്യം (മരണം) മോശവുമായിത്തീരും." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا أَبَا ذَرٍّ إِنِّي أَرَاكَ ضَعِيفًا، وَإِنِّي أُحِبُّ لَكَ مَا أُحِبُّ لِنَفْسِي، لَا تَأَمَّرَنَّ عَلَى اثْنَيْنِ، وَلَا تَوَلَّيَنَّ مَالَ يَتِيمٍ". (م,ن)', 'അബൂദർറ്(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഓ അബൂദർറ്, ഒരു ബലഹീനനായി താങ്കളെ ഞാൻ മനസ്സിലാക്കുന്നു. മാത്രവുമല്ല എന്റെ സ്വന്തത്തിന് എന്താണോ ഞാൻ ആഗ്രഹിക്കുന്നത് അത് ഞാൻ താങ്കൾക്കും ആഗ്രഹിക്കുന്നു. അതിനാൽ രണ്ടുപേർക്കുമേൽ താങ്കൾ നേതാവാകുകയോ ഒരു യതീമിന്റെ സമ്പത്തിന്റെ സംരക്ഷനാവുകയോ ചെയ്യരുത്." (മു,ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَلَا تَسْتَعْمِلُنِي؟ قَالَ: فَضَرَبَ بِيَدِهِ عَلَى مَنْكِبِي، ثُمَّ قَالَ: "يَا أَبَا ذَرٍّ، إِنَّكَ ضَعِيفٌ، وَإِنَّهَا أَمَانَةٌ، وَإِنَّهَا يَوْمَ الْقِيَامَةِ خِزْيٌ وَنَدَامَةٌ، إِلَّا مَنْ أَخَذَهَا بِحَقِّهَا، وَأَدَّى الَّذِي عَلَيْهِ فِيهَا". (م)', 'അബൂദർറ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അങ്ങ് എന്നെ ഭരണാധികാരം ഏൽപിക്കുന്നില്ലെയോ? നിവേദകൻ പറയുന്നു: അപ്പോൾ അവിടുന്ന് തന്റെ കൈകൊണ്ട് എന്റെ തോളിൽ അടിച്ചുകൊണ്ട് പറഞ്ഞു: "ഓ അബൂദർറ്, താങ്കളൊരു ബലഹീനനാണ്, നിശ്ചയം അധികാരമെന്നത് ഒരു സൂക്ഷിപ്പു സ്വത്തുമാണ്. അർഹതയോടു കൂടെ അധികാരം ഏറ്റെടുക്കുകയും അതിൽ തന്റെ ഉത്തരവാദിത്തങ്ങൾ നിറവേറ്റുകയും ചെയ്തവന്നൊഴിച്ച്, നിശ്ചയം അന്ത്യദിനത്തിൽ അധികാരമെന്നത് ദുഃഖവും പരാജയവുമായിരിക്കും." (മു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَرَبَ عَلَى مَنْكِبِهِ، ثُمَّ قَالَ لَهُ: "أَفْلَحْتَ – يَا قُدَيْمُ – إِنْ مُتَّ وَلَمْ تَكُنْ أَمِيرًا وَلَا كَاتِبًا وَلَا عَرِيفًا". (د)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ): നിശ്ചയം റസൂൽ(സ) അദ്ദേഹത്തിന്റെ തോളിൽ അടിച്ചു, ശേഷം അദ്ദേഹത്തോട് പറഞ്ഞു: "ഓ ഖുദൈം, താങ്കൾ ഒരു ഭരണാധികാരിയോ എഴുത്തുകാരനോ കാര്യസ്ഥനോ ആകാതെ മരണപ്പെട്ടാൽ താങ്കൾ വിജയിച്ചിരിക്കുന്നു." (ദ)', 'الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ غَالِبٍ الْقَطَّانِ، عَنْ رَجُلٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ: أَنَّهُمْ كَانُوا عَلَى مَنْهَلٍ مِنَ الْمَنَاهِلِ، فَلَمَّا بَلَغَهُمُ الْإِسْلَامُ جَعَلَ صَاحِبُ الْمَاءِ لِقَوْمِهِ مِائَةً مِنَ الْإِبِلِ عَلَى أَنْ يُسْلِمُوا، فَأَسْلَمُوا، وَقَسَمَ الْإِبِلَ بَيْنَهُمْ، وَبَدَا لَهُ أَنْ يَرْتَجِعَهَا مِنْهُمْ، فَأَرْسَلَ ابْنَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ: ائْتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْ لَهُ: إِنَّ أَبِي يُقْرِئُكَ السَّلَامَ، وَإِنَّهُ جَعَلَ لِقَوْمِهِ مِائَةً مِنَ الْإِبِلِ عَلَى أَنْ يُسْلِمُوا، فَأَسْلَمُوا، وَقَسَمَ الْإِبِلَ بَيْنَهُمْ، وَبَدَا لَهُ أَنْ يَرْتَجِعَهَا مِنْهُمْ، أَفَهُوَ أَحَقُّ بِهَا أَمْ هُمْ؟ فَإِنْ قَالَ لَكَ: نَعَمْ، أَوْ: لَا، فَقُلْ لَهُ: إِنَّ أَبِي شَيْخٌ كَبِيرٌ، وَهُوَ عَرِيفُ الْمَاءِ، وَإِنَّهُ يَسْأَلُكَ أَنْ تَجْعَلَ لِي الْعِرَافَةَ بَعْدَهُ، فَأَتَاهُ، فَقَالَ: إِنَّ أَبِي يُقْرِئُكَ السَّلَامَ، فَقَالَ: "وَعَلَيْكَ وَعَلَى أَبِيكَ السَّلَامُ". فَقَالَ: إِنَّ أَبِي جَعَلَ لِقَوْمِهِ مِائَةً مِنَ الْإِبِلِ عَلَى أَنْ يُسْلِمُوا، فَأَسْلَمُوا، وَحَسُنَ إِسْلَامُهُمْ، ثُمَّ بَدَا لَهُ أَنْ يَرْتَجِعَهَا مِنْهُمْ، أَفَهُوَ أَحَقُّ بِهَا أَمْ هُمْ؟ فَقَالَ: "إِنْ بَدَا لَهُ أَنْ يُسْلِمَهَا لَهُمْ فَلْيُسْلِمْهَا، وَإِنْ بَدَا لَهُ أَنْ يَرْتَجِعَهَا فَهُوَ أَحَقُّ بِهَا مِنْهُمْ، فَإِنْ هُمْ أَسْلَمُوا فَلَهُمْ إِسْلَامُهُمْ، وَإِنْ لَمْ يُسْلِمُوا قُوتِلُوا عَلَى الْإِسْلَامِ". فَقَالَ: إِنَّ أَبِي شَيْخٌ كَبِيرٌ، وَهُوَ عَرِيفُ الْمَاءِ، وَإِنَّهُ يَسْأَلُكَ أَنْ تَجْعَلَ لِي الْعِرَافَةَ بَعْدَهُ. فَقَالَ: "إِنَّ الْعِرَافَةَ حَقٌّ، وَلَا بُدَّ لِلنَّاسِ مِنَ الْعُرَفَاءِ، وَلَكِنَّ الْعُرَفَاءَ فِي النَّارِ". (د)', 'ഗാലിബുൽ ഖത്താൻ ഒരാളിൽ നിന്നും അയാൾ തന്റെ പിതാവിൽ നിന്നും പിതാവ് പിതാമഹനിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: കുടിവെള്ളമുള്ള ഒരു സ്ഥലത്തായിരുന്നു അവർ താമസിച്ചിരുന്നത്. അതിനിടെ അവരിലേക്ക് ഇസ്ലാം ആഗതമായപ്പോൾ, തന്റെ സമുദായം ഇസ്ലാം സ്വീകരിക്കുന്നതിന്, ജലാശയത്തിന്റെ കൈകാര്യകർത്താവ് അവർക്ക് നൂറ് ഒട്ടകം വാഗ്ദാനം ചെയ്തു. അവർ മുസ്ലിംകളായി. അയാൾ അവർക്ക് ഒട്ടകങ്ങളെ വീതിച്ചുനൽകുകയും ചെയ്തു. പിന്നീടയാൾക്ക് ഒട്ടകങ്ങളെ തിരിച്ചുവാങ്ങാൻ തോന്നി. അങ്ങനെ അയാൾ മകനെ റസൂൽ(സ)യുടെയടുത്തേക്ക് യാത്രയാക്കിക്കൊണ്ട് പറഞ്ഞു: നീ നബി(സ)യുടെ സന്നിധിയിൽ ചെന്ന് പറയുക: എന്റെ പിതാവ് അങ്ങേക്ക് സലാം പറയുന്നു. തന്റെ സമുദായം ഇസ്ലാം സ്വീകരിക്കുന്നതിന് അദ്ദേഹം നൂറൊട്ടകം അവർക്ക് വാഗ്ദാനം ചെയ്തിരുന്നു. അങ്ങനെ അവർ മുസ്ലിംകളാവുകയും അദ്ദേഹം ഒട്ടകങ്ങളെ അവർക്കിടയിൽ വീതിച്ചുകൊടുക്കുകയും ചെയ്തു. പിന്നീടദ്ദേഹത്തിന് ഒട്ടകങ്ങളെ തിരിച്ചുവാങ്ങാൻ തോന്നി. അദ്ദേഹമതിന് അർഹനാണോ? അതോ അവർ തന്നെയാണോ അതർഹിക്കുന്നത്? അപ്പോൾ തിരുമേനി(സ) നിന്നോട് ''അങ്ങനെ ചെയ്യാം'' എന്നോ ''പാടില്ല'' എന്നോ പറഞ്ഞാൽ നീ അവിടുത്തോട് പറയുക: എന്റെ പിതാവ് ഒരു വൃദ്ധനാണ്. ജലാശയത്തിന്റെ ഉത്തരവാദി അദ്ദേഹമാണ്. അദ്ദേഹത്തിന് ശേഷം അതിന്റെ നേതൃത്വം എനിക്ക് നൽകാൻ അങ്ങയോടദ്ദേഹം ആവശ്യപ്പെടുന്നു. അങ്ങനെ ആ മകൻ നബി(സ)യുടെയടുത്തു ചെന്നു. എന്നിട്ട് പറഞ്ഞു: എന്റെ പിതാവ് അങ്ങേക്ക് സലാം പറയുന്നു. നബി(സ) പറഞ്ഞു: "നിന്റെ മേലും പിതാവിന്റെ മേലും രക്ഷയുണ്ടാവട്ടെ." മകൻ പറഞ്ഞു: ഇസ്ലാം സ്വീകരിച്ചാൽ നൂറ് ഒട്ടകം നൽകാമെന്ന് തന്റെ സമുദായത്തിന് എന്റെ പിതാവ് വാഗ്ദാനം നൽകി. അങ്ങനെ അവർ മുസ്ലിംകളായി. അവർ ഇസ്ലാമിന്റെ മാർഗത്തിൽ ശോഭിച്ചു. പിന്നീടദ്ദേഹത്തിന് ഒട്ടകങ്ങളെ തിരിച്ചുവാങ്ങാൻ തോന്നി. അദ്ദേഹമാണോ അതോ അവരാണോ അതിന് അവകാശപ്പെട്ടവർ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഒട്ടകങ്ങളെ അവർക്ക് നൽകാൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അങ്ങനെ ചെയ്യാം. അവയെ തിരിച്ചുവാങ്ങാൻ തോന്നുന്നുവെങ്കിൽ അദ്ദേഹമാണ് അവരേക്കാൾ അതിന് അവകാശപ്പെട്ടവൻ. അവർ ഇസ്ലാം സ്വീകരിച്ചിട്ടുണ്ടെങ്കിൽ അവർക്ക് അവരുടെ ഇസ്ലാമുണ്ട്. ഇസ്ലാം സ്വീകരിച്ചില്ലെങ്കിൽ ഇസ്ലാമിന്റെ പേരിൽ അവർ യുദ്ധം അഭിമുഖീകരിക്കേണ്ടി വരും." ശേഷം മകൻ പറഞ്ഞു: എന്റെ പിതാവ് ഒരു വൃദ്ധനാണ്. വെള്ളത്തിന്റെ കാര്യസ്ഥൻ (നാട്ടിലെ അധികാരി) അദ്ദേഹമാണ്. അദ്ദേഹത്തിന് ശേഷം ആ അധികാരം എനിക്ക് നൽകാൻ അദ്ദേഹം അങ്ങയോട് ആവശ്യപ്പെടുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നിശ്ചയം അധികാരം ബാധ്യതയാണ്. ജനങ്ങൾക്ക് അധികാരികളുണ്ടാവൽ ഒഴിച്ചുകൂടാനാവാത്തതുമാണ്. പക്ഷേ, അധികാരികൾ നരകത്തിലാണ്." (ദ)', 'غَالِبٍ الْقَطَّانِ، عَنْ رَجُلٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 124, 124, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أُسَيْدِ بْنِ حُضَيْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنَ الْأَنْصَارِ خَلَا بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَلَا تَسْتَعْمِلُنِي كَمَا اسْتَعْمَلْتَ فُلَانًا؟ فَقَالَ: "إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي أَثَرَةً، فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى الْحَوْضِ". (م)', 'ഉസൈദുബ്നു ഹുളൈർ(റ): നിശ്ചയം അൻസാരികളിൽപെട്ട ഒരാൾ റസൂൽ(സ)യോടൊപ്പം ഒറ്റക്കായി. അപ്പോഴദ്ദേഹം ചോദിച്ചു: ഇന്ന വ്യക്തിക്ക് അങ്ങ് ഭരണാധികാരം നൽകിയതുപോലെ എനിക്കും അങ്ങ് അധികാരം നൽകുന്നില്ലെയോ? അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം എന്റെ കാലശേഷം നിങ്ങൾ സ്വാർത്ഥതയെ അഭിമുഖീകരിക്കും. അപ്പോൾ ''ഹൗളി''ന്റെ (ഹൗളുൽ കൗസർ) പരിസരത്തുവെച്ച് എന്നെ കണ്ടുമുട്ടുംവരെ നിങ്ങൾ ക്ഷമ കൈകൊള്ളുക." (മു)', 'أُسَيْدِ بْنِ حُضَيْرٍ', 'ഉസൈദുബ്നു ഹുളൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ شُمَاسَةَ قَالَ: أَتَيْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَسْأَلُهَا عَنْ شَيْءٍ، فَقَالَتْ: مِمَّنْ أَنْتَ؟ فَقُلْتُ: رَجُلٌ مِنْ أَهْلِ مِصْرَ، فَقَالَتْ: كَيْفَ كَانَ صَاحِبُكُمْ لَكُمْ فِي غَزَاتِكُمْ هَذِهِ؟ فَقَالَ: مَا نَقَمْنَا مِنْهُ شَيْئًا، إِنْ كَانَ لَيَمُوتُ لِلرَّجُلِ مِنَّا الْبَعِيرُ فَيُعْطِيهِ الْبَعِيرَ، وَالْعَبْدُ فَيُعْطِيهِ الْعَبْدَ، وَيَحْتَاجُ إِلَى النَّفَقَةِ فَيُعْطِيهِ النَّفَقَةَ، فَقَالَتْ: أَمَا إِنَّهُ لَا يَمْنَعُنِي الَّذِي فَعَلَ فِي مُحَمَّدِ بْنِ أَبِي بَكْرٍ أَخِي أَنْ أُخْبِرَكَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي بَيْتِي هَذَا: "اللَّهُمَّ مَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَشَقَّ عَلَيْهِمْ فَاشْقُقْ عَلَيْهِ، وَمَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَرَفَقَ بِهِمْ فَارْفُقْ بِهِ". (م)', 'അബ്ദുർറഹ്മാനുബ്നു ശുമാസ(റ): ഒരു കാര്യത്തെക്കുറിച്ച് ചോദിക്കാനായി ഞാൻ ആഇശ(റ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ മഹതി ചോദിച്ചു: താങ്കൾ ആരുടെ കൂട്ടത്തിൽപെട്ടയാളാണ്? അപ്പോൾ ഞാൻ പറഞ്ഞു: മിസ്റുകാരിൽ പെട്ടയാളാണ്. അപ്പോൾ മഹതി ചോദിച്ചു: ഈ യുദ്ധത്തിലെ നിങ്ങളുടെ നേതാവ് എങ്ങനെയായിരുന്നു നിങ്ങളോട് പെരുമാറിയിരുന്നത്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾക്ക് ഒരു കാര്യത്തിലും അദ്ദേഹത്തോട് വെറുപ്പ് തോന്നിയിട്ടില്ല. ഞങ്ങളിലൊരാളുടെ ഒട്ടകം ചാകുന്നുവെങ്കിൽ അദ്ദേഹം അയാൾക്ക് ഒട്ടകം നൽകും, അടിമയാണെങ്കിൽ അദ്ദേഹം അയാൾക്ക് അടിമയെ നൽകും, ചെലവിന് വല്ലതും ആവശ്യമുണ്ടെങ്കിൽ അദ്ദേഹം അയാൾക്ക് അത് നൽകും. അപ്പോൾ മഹതി പറഞ്ഞു: എന്റെ സഹോദരൻ മുഹമ്മദുബ്ൻ അബീബക്റിനോട് അദ്ദേഹം ചെയ്തത്, എന്റെ ഈ വീട്ടിൽവെച്ച് റസൂൽ(സ) പറഞ്ഞതായി ഞാൻ കേട്ട കാര്യം താങ്കളെ അറിയിക്കുന്നതിൽനിന്ന് എന്നെ തടയുന്നില്ല. അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവേ, എന്റെ ഉമ്മത്തിന്റെ കാര്യത്തിൽ വല്ല അധികാരവും ഏറ്റെടുത്ത് അവരെ ബുദ്ധിമുട്ടിക്കുന്നവനെ നീ ബുദ്ധിമുട്ടിക്കേണമേ. അല്ലാഹുവേ, എന്റെ സമുദായത്തിന്റെ കാര്യത്തിൽ വല്ല അധികാരവും ഏറ്റെടുത്ത് അവരോട് കരുണ കാണിക്കുന്നവനോട് നീ കരുണ കാണിക്കേണമേ". (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ شُمَاسَةَ قَالَ', 'അബ്ദുർറഹ്മാനുബ്നു ശുമാസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الدِّينَ النَّصِيحَةُ، إِنَّ الدِّينَ النَّصِيحَةُ، إِنَّ الدِّينَ النَّصِيحَةُ". وَفِي رِوَايَةٍ: "الدِّينُ النَّصِيحَةُ". قَالُوا: لِمَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: "لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം മതമെന്നാൽ ഗുണകാംക്ഷയാണ്, നിശ്ചയം മതമെന്നാൽ ഗുണകാംക്ഷയാണ്, നിശ്ചയം മതമെന്നാൽ ഗുണകാംക്ഷയാണ്." മറ്റൊരു നിവേദനത്തിൽ: "മതമെന്നാൽ ഗുണകാംക്ഷയാണ്." അവർ ചോദിച്ചു: ആരോടാണ് അല്ലാഹുവിന്റെ പ്രവാചകരേ? അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിനോടും അവന്റെ ഗ്രന്ഥത്തോടും അവന്റെ പ്രവാചകനോടും മുസ്ലിംകളിലെ നേതാക്കന്മാരോടും അവരിലെ സാധാരണക്കാരോടും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 125, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=20), 1, 'وَفِي رِوَايَةٍ: "الدِّينُ النَّصِيحَةُ". قَالُوا: لِمَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: "لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "മതമെന്നാൽ ഗുണകാംക്ഷയാണ്." അവർ ചോദിച്ചു: ആരോടാണ് അല്ലാഹുവിന്റെ പ്രവാചകരേ? അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിനോടും അവന്റെ ഗ്രന്ഥത്തോടും അവന്റെ പ്രവാചകനോടും മുസ്ലിംകളിലെ നേതാക്കന്മാരോടും അവരിലെ സാധാരണക്കാരോടും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ الْحَسَنِ قَالَ: عَادَ عُبَيْدُ اللَّهِ بْنُ زِيَادٍ مَعْقِلَ بْنَ يَسَارٍ الْمُزَنِيَّ رَضِيَ اللهُ عَنْهُ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ، فَقَالَ مَعْقِلٌ: إِنِّي مُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَوْ عَلِمْتُ أَنَّ لِي حَيَاةً مَا حَدَّثْتُكَ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ عَبْدٍ يَسْتَرْعِيهِ اللَّهُ رَعِيَّةً يَمُوتُ يَوْمَ يَمُوتُ وَهُوَ غَاشٌّ لِرَعِيَّتِهِ، إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ". (م)', 'ഹസൻ(റ): മഅ്ഖിലുബ്നു യസാരിൽ മുസനി(റ)വിനെ അദ്ദേഹത്തിന്റെ മരണരോഗ സമയത്ത് ഉബൈദുല്ലാഹിബ്നു സിയാദ് സന്ദർശിച്ചു. അപ്പോൾ മഅ്ഖിൽ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യിൽനിന്ന് കേട്ട ഒരു ഹദീസ് താങ്കൾക്ക് പറഞ്ഞു തരികയാണ്. എനിക്ക് ഇനിയും ജീവിതമുണ്ടെന്ന് ഞാൻ അറിഞ്ഞിരുന്നുവെങ്കിൽ അത് താങ്കൾക്ക് ഞാൻ പറഞ്ഞു തരില്ലായിരുന്നു. റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഒരു ജനതയെ നയിക്കാൻ അല്ലാഹു ഏൽപിക്കുകയും അങ്ങനെ മരിക്കുന്ന ദിവസം തന്റെ പ്രജകളെ വഞ്ചിച്ചവനായി മരിക്കുകയും ചെയ്ത ഏതൊരു അടിമയുടെ മേലിലും അല്ലാഹു സ്വർഗ്ഗം നിഷിദ്ധമാക്കാതിരിക്കുകയില്ല." (മു)', 'الْحَسَنِ قَالَ', 'ഹസൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 126, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ الْحَسَنِ: أَنَّ عَائِذَ بْنَ عَمْرٍو: – وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – دَخَلَ عَلَى عُبَيْدِ اللَّهِ بْنِ زِيَادٍ، فَقَالَ: أَيْ بُنَيَّ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ شَرَّ الرِّعَاءِ الْحُطَمَةُ، فَإِيَّاكَ أَنْ تَكُونَ مِنْهُمْ". فَقَالَ لَهُ: اجْلِسْ فَإِنَّمَا أَنْتَ مِنْ نُخَالَةِ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: وَهَلْ كَانَتْ لَهُمْ نُخَالَةٌ؟ إِنَّمَا كَانَتِ النُّخَالَةُ بَعْدَهُمْ وَفِي غَيْرِهِمْ. (م)', 'ഹസൻ(റ): നിശ്ചയം ആഇദുബ്നു അംറ്(റ) - അദ്ദേഹം പ്രവാചകർ(സ)യുടെ അനുചരരിൽ ഒരാളാണ് - ഉബൈദുല്ലാഹിബ്നു സിയാദിന്റെ അടുക്കൽ ചെന്നു. എന്നിട്ട് പറഞ്ഞു: എന്റെ പൊന്നുമോനേ, നിശ്ചയം റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിശ്ചയം യജമാനരിൽ ഏറ്റവും മോശപ്പെട്ടവർ ക്രൂരവും പരുഷവുമായി പെരുമാറുന്നവരാണ്. അതിനാൽ താങ്കൾ അവരിൽ പെടുന്നത് സൂക്ഷിക്കുക." അപ്പോൾ അദ്ദേഹം ആഇദുബ്നു അംറ്(റ)വിനോട് പറഞ്ഞു: നിങ്ങൾ ഇരിക്കൂ. തീർച്ചയായും നിങ്ങൾ മുഹമ്മദ്(സ)യുടെ അനുചരരിൽ നിന്ന് അവശേഷിച്ചിട്ടുള്ള ചവറാകുന്നു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: അതിന് അവരിൽ ചവറുകളുണ്ടായിരുന്നോ? നിശ്ചയം ചവറുകളുണ്ടായത് അവർക്ക് ശേഷവും അവരല്ലാത്തവരിലുമാണ്. (മു)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 126, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عَبَّاسٍ، عَنِ الصَّعْبِ بْنِ جَثَّامَةَ – رَضِيَ اللهُ عَنْهُمْ –: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا حِمَى إِلَّا لِلَّهِ وَلِرَسُولِهِ". وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَمَى النَّقِيعَ، وَقَالَ: "لَا حِمَى إِلَّا لِلَّهِ عَزَّ وَجَلَّ". (خ,د,ن)', 'സ്വഅ്ബുബ്നു ജസ്സാമ(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനും അവന്റെ റസൂലിനുമല്ലാതെ സംരക്ഷിത സ്ഥലമില്ല." മറ്റൊരു നിവേദനം: നിശ്ചയം നബി(സ) നഖീഅ് എന്ന സ്ഥലം സംരക്ഷിത സ്ഥലമാക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "യോഗ്യനും ഉന്നതനുമായ അല്ലാഹുവിനല്ലാതെ സംരക്ഷിത സ്ഥലങ്ങളില്ല." (ബു,ദ,ന)', 'ابْنِ عَبَّاسٍ، عَنِ الصَّعْبِ بْنِ جَثَّامَةَ –', 'സ്വഅ്ബുബ്നു ജസ്സാമ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 126, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=23), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَمَى النَّقِيعَ، وَقَالَ: "لَا حِمَى إِلَّا لِلَّهِ عَزَّ وَجَلَّ". (خ,د,ن)', 'മറ്റൊരു നിവേദനം: നിശ്ചയം നബി(സ) നഖീഅ് എന്ന സ്ഥലം സംരക്ഷിത സ്ഥലമാക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "യോഗ്യനും ഉന്നതനുമായ അല്ലാഹുവിനല്ലാതെ സംരക്ഷിത സ്ഥലങ്ങളില്ല." (ബു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَخْلَفَ ابْنَ أُمِّ مَكْتُومٍ عَلَى الْمَدِينَةِ مَرَّتَيْنِ. (د)', 'അനസ്(റ): നിശ്ചയം നബി(സ) ഇബ്നു ഉമ്മിമഖ്തൂം(റ)വിനെ രണ്ടു പ്രാവശ്യം മദീനയിലെ പ്രതിനിധിയായി നിശ്ചയിച്ചു. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَبْدِ اللَّهِ الْهَوْزَنِيِّ قَالَ: لَقِيتُ بِلَالًا رَضِيَ اللهُ عَنْهُ مُؤَذِّنَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَلَبَ، فَقُلْتُ: يَا بِلَالُ، حَدِّثْنِي كَيْفَ كَانَتْ نَفَقَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَا كَانَ لَهُ شَيْءٌ، كُنْتُ أَنَا الَّذِي أَلِي ذَلِكَ مِنْهُ مُنْذُ بَعَثَهُ اللَّهُ إِلَى أَنْ تُوُفِّيَ، وَكَانَ إِذَا أَتَاهُ الْإِنْسَانُ مُسْلِمًا، فَرَآهُ عَارِيًا، يَأْمُرُنِي فَأَنْطَلِقُ فَأَسْتَقْرِضُ، فَأَشْتَرِي لَهُ الْبُرْدَةَ فَأَكْسُوهُ وَأُطْعِمُهُ، حَتَّى اعْتَرَضَنِي رَجُلٌ مِنَ الْمُشْرِكِينَ فَقَالَ: يَا بِلَالُ، إِنَّ عِنْدِي سَعَةً، فَلَا تَسْتَقْرِضْ مِنْ أَحَدٍ إِلَّا مِنِّي. فَفَعَلْتُ، فَلَمَّا أَنْ كَانَ ذَاتَ يَوْمٍ تَوَضَّأْتُ ثُمَّ قُمْتُ لِأُؤَذِّنَ بِالصَّلَاةِ، فَإِذَا الْمُشْرِكُ قَدْ أَقْبَلَ فِي عِصَابَةٍ مِنَ التُّجَّارِ، فَلَمَّا أَنْ رَآنِي قَالَ: يَا حَبَشِيُّ، قُلْتُ: يَا لَبَّاهُ، فَتَجَهَّمَنِي وَقَالَ لِي قَوْلًا غَلِيظًا، وَقَالَ لِي: أَتَدْرِي كَمْ بَيْنَكَ وَبَيْنَ الشَّهْرِ؟ قَالَ: قُلْتُ: قَرِيبٌ، قَالَ: إِنَّمَا بَيْنَكَ وَبَيْنَهُ أَرْبَعٌ، فَآخُذُكَ بِالَّذِي عَلَيْكَ فَأَرُدُّكَ تَرْعَى الْغَنَمَ كَمَا كُنْتَ قَبْلَ ذَلِكَ. فَأَخَذَ فِي نَفْسِي مَا يَأْخُذُ فِي أَنْفُسِ النَّاسِ، حَتَّى إِذَا صَلَّيْتُ الْعَتَمَةَ رَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَهْلِهِ فَاسْتَأْذَنْتُ عَلَيْهِ، فَأَذِنَ لِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ، بِأَبِي أَنْتَ وَأُمِّي، إِنَّ الْمُشْرِكَ الَّذِي كُنْتُ أَتَدَيَّنُ مِنْهُ قَالَ لِي كَذَا وَكَذَا، وَلَيْسَ عِنْدَكَ مَا تَقْضِي عَنِّي وَلَا عِنْدِي، وَهُوَ فَاضِحِي، فَأْذَنْ لِي أَنْ آبَقَ إِلَى بَعْضِ هَؤُلَاءِ الْأَحْيَاءِ الَّذِينَ قَدْ أَسْلَمُوا، حَتَّى يَرْزُقَ اللَّهُ رَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا يَقْضِي عَنِّي. وَفِي رِوَايَةٍ: فَسَكَتَ عَنِّي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاغْتَمَزْتُهَا. فَخَرَجْتُ حَتَّى إِذَا أَتَيْتُ مَنْزِلِي، فَجَعَلْتُ سَيْفِي وَجِرَابِي وَنَعْلِي وَمِجَنِّي عِنْدَ رَأْسِي، حَتَّى إِذَا انْشَقَّ عَمُودُ الصُّبْحِ الْأَوَّلِ أَرَدْتُ أَنْ أَنْطَلِقَ فَإِذَا إِنْسَانٌ يَسْعَى يَدْعُو: يَا بِلَالُ، أَجِبْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقْتُ حَتَّى أَتَيْتُهُ، فَإِذَا أَرْبَعُ رَكَائِبَ مُنَاخَاتٌ عَلَيْهِنَّ أَحْمَالُهُنَّ، فَاسْتَأْذَنْتُ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَبْشِرْ، فَقَدْ جَاءَكَ اللَّهُ بِقَضَائِكَ". ثُمَّ قَالَ: "أَلَمْ تَرَ الرَّكَائِبَ الْمُنَاخَاتِ الْأَرْبَعَ". فَقُلْتُ: بَلَى. فَقَالَ: "إِنَّ لَكَ رِقَابَهُنَّ وَمَا عَلَيْهِنَّ، فَإِنَّ عَلَيْهِنَّ كِسْوَةً وَطَعَامًا أَهْدَاهُنَّ إِلَيَّ عَظِيمُ فَدَكٍ، فَاقْبِضْهُنَّ وَاقْضِ دَيْنَكَ". فَفَعَلْتُ، فَذَكَرَ الْحَدِيثَ، ثُمَّ انْطَلَقْتُ إِلَى الْمَسْجِدِ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ فِي الْمَسْجِدِ، فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: "مَا فَعَلَ مَا قِبَلَكَ". قُلْتُ: قَضَى اللَّهُ كُلَّ شَيْءٍ كَانَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يَبْقَ شَيْءٌ. قَالَ: "أَفَضَلَ شَيْءٌ". قُلْتُ: نَعَمْ، قَالَ: "انْظُرْ أَنْ تُرِيحَنِي مِنْهُ، فَإِنِّي لَسْتُ بِدَاخِلٍ عَلَى أَحَدٍ مِنْ أَهْلِي حَتَّى تُرِيحَنِي مِنْهُ". فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَتَمَةَ دَعَانِي فَقَالَ: "مَا فَعَلَ الَّذِي قِبَلَكَ". قَالَ: قُلْتُ: هُوَ مَعِي لَمْ يَأْتِنَا أَحَدٌ، فَبَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، وَقَصَّ الْحَدِيثَ، حَتَّى إِذَا صَلَّى الْعَتَمَةَ – يَعْنِي مِنَ الْغَدِ – دَعَانِي قَالَ: "مَا فَعَلَ الَّذِي قِبَلَكَ". قَالَ: قُلْتُ: قَدْ أَرَاحَكَ اللَّهُ مِنْهُ يَا رَسُولَ اللَّهِ، فَكَبَّرَ وَحَمِدَ اللَّهَ، شَفَقًا مِنْ أَنْ يُدْرِكَهُ الْمَوْتُ وَعِنْدَهُ ذَلِكَ، ثُمَّ اتَّبَعْتُهُ حَتَّى إِذَا جَاءَ أَزْوَاجَهُ فَسَلَّمَ عَلَى امْرَأَةٍ امْرَأَةٍ، حَتَّى أَتَى مَبِيتَهُ، فَهَذَا الَّذِي سَأَلْتَنِي عَنْهُ. (د)', 'അബ്ദുല്ലാഹിൽ ഹൗസനീ(റ): റസൂൽ(സ)യുടെ മുഅദ്ദിനായ (ബാങ്ക് വിളിക്കുന്നയാൾ) ബിലാൽ(റ)വിനെ ഹലബിൽ വെച്ച് ഞാൻ കണ്ടുമുട്ടി. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഓ ബിലാൽ, റസൂൽ(സ)യുടെ ജീവിതച്ചെലവ് എങ്ങനെയായിരുന്നുവെന്ന് എനിക്ക് പറഞ്ഞു തന്നാലും. അദ്ദേഹം പറഞ്ഞു: അവിടുത്തേക്ക് ഒന്നുമുണ്ടായിരുന്നില്ല. അല്ലാഹു തിരുമേനി(സ)യെ നിയോഗിച്ചതു മുതൽ വഫാത് വരെ അവിടുത്തെ ചെലവിന്റെ കാര്യങ്ങൾ കൈകാര്യം ചെയ്തിരുന്നത് ഞാനായിരുന്നു. ഒരാൾ മുസ്ലിമായി അവിടുത്തെ സമീപിക്കുകയും വസ്ത്രമില്ലാത്തവനായി അവിടുന്ന് അയാളെ കാണുകയും ചെയ്താൽ, അവിടുന്ന് എന്നോട് കൽപിക്കുകയും ഞാൻ പോയി കടം വാങ്ങി അയാൾക്കുവേണ്ടി പുതപ്പ് വാങ്ങിക്കുകയും അയാളെ ധരിപ്പിക്കുകയും അയാൾക്ക് ഭക്ഷണം നൽകുകയും ചെയ്യും. അങ്ങനെയിരിക്കെ ബഹുദൈവാരാധകരിൽ പെട്ട ഒരാൾ എന്നെ അഭിമുഖീകരിച്ച് ഇപ്രകാരം പറഞ്ഞു: ഓ ബിലാൽ, നിശ്ചയം എന്റെ പക്കൽ ധാരാളം ധനമുണ്ട്, അതിനാൽ എന്നിൽ നിന്നല്ലാതെ മറ്റൊരാളിൽനിന്നും നീ കടം വാങ്ങരുത്. അപ്പോൾ ഞാൻ അങ്ങനെ ചെയ്തു. അങ്ങനെയിരിക്കെ ഒരു ദിവസം വുളു ചെയ്ത് നിസ്കരിക്കാനായി ബാങ്ക് വിളിക്കാൻ ഞാൻ നിന്നപ്പോൾ ആ ബഹുദൈവാരാധകനതാ ഒരു കൂട്ടം കച്ചവടക്കാരുമൊത്ത് വന്നിരിക്കുന്നു. എന്നെ കണ്ടപാടെ അയാൾ പറഞ്ഞു: ഓ ഹബശീ. ഞാൻ പറഞ്ഞു: ഞാനിതാ ഉത്തരം ചെയ്യുന്നു. അപ്പോൾ നീരസത്തോടെ അയാളെന്നെ സമീപിക്കുകയും എന്നോട് കഠിനമായ വാക്കുകൾ പറയുകയും ചെയ്തു. അയാളെന്നോട് ഇപ്രകാരം ചോദിച്ചു: നിനക്ക് (കടം വീട്ടാൻ) നിശ്ചയിച്ച മാസത്തിന് ഇനി എത്രയുണ്ടെന്ന് നിനക്കറിയില്ലേ? ഞാൻ പറഞ്ഞു: വളരെ അടുത്താണ്. അയാൾ പറഞ്ഞു: നിശ്ചയം നിനക്കും അതിനുമിടയിലുള്ളത് നാലാണ്. ശേഷം എനിക്ക് നിന്നിൽനിന്ന് കിട്ടാനുള്ളതിന് പകരമായി നിന്നെ ഞാൻ പിടികൂടുകയും മുമ്പ് നീ ആയിരുന്നതുപോലെ ആടുകളെ മേക്കുന്നവനായി നിന്നെ ഞാൻ മാറ്റുകയും ചെയ്യും. എല്ലാവരുടെയും മനസ്സു വേദനിക്കുന്നതുപോലെ അപ്പോൾ എന്റെ മനസ്സും വേദനിച്ചു. അങ്ങനെ ഞാൻ ഇശാ നമസ്കരിച്ച് കഴിഞ്ഞപ്പോഴേക്കും നബി(സ) അവിടുത്തെ കുടുംബത്തിലേക്ക് മടങ്ങി. അവിടുത്തെ കാണാൻ ഞാൻ സമ്മതം ചോദിക്കുകയും എനിക്ക് സമ്മതം നൽകപ്പെടുകയും ചെയ്തു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ ഉമ്മയും ഉപ്പയും അവിടുത്തേക്ക് ദണ്ണമാണ്, ഞാൻ കടം വാങ്ങാറുണ്ടായിരുന്ന ബഹുദൈവാരാധകൻ എന്നോട് ഇപ്രകാരമെല്ലാം പറഞ്ഞിരിക്കുന്നു. എനിക്കുവേണ്ടി കടം വീട്ടാനാവശ്യമായത് എന്റെ പക്കലോ അവിടുത്തെ പക്കലോ ഇല്ല. അയാളാണെങ്കിൽ എന്നെ വഷളാക്കുകയും ചെയ്യും. അതിനാൽ എനിക്ക് കടം വീട്ടാനാവശ്യമായത് അല്ലാഹു തന്റെ റസൂലിന് നൽകുന്നതുവരെ, ഇസ്ലാം സ്വീകരിച്ച ചില ഗോത്രങ്ങളിലേക്ക് ഓടിപ്പോകാൻ അവിടുന്നെനിക്ക് അനുവാദം നൽകിയാലും. മറ്റൊരു നിവേദനത്തിൽ: അപ്പോൾ തിരുമേനി(സ) മൗനം പാലിക്കുകയും എനിക്കതിൽ അതൃപ്തി തോന്നുകയും ചെയ്തു. ഞാൻ പുറത്തുവരികയും എന്റെ വീട്ടിൽചെന്ന് എന്റെ വാളും തോൽപാത്രവും ചെരിപ്പും പരിചയുമെല്ലാം എന്റെ തലക്കരികിൽ വെക്കുകയും ചെയ്തു. അങ്ങനെ ഒന്നാം പ്രഭാതത്തിന്റെ പ്രകാശം പൊട്ടിവിടർന്നപ്പോൾ ഞാൻ പുറപ്പെടാനുദ്ദേശിച്ചു. അപ്പോഴതാ, ഓ ബിലാൽ, അല്ലാഹുവിന്റെ റസൂലിന് താങ്കൾ ഉത്തരം നൽകുക എന്നു വിളിച്ചു പറഞ്ഞുകൊണ്ട് ഒരാൾ വരുന്നു. ഉടനെ ഞാൻ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് പോയി. അന്നേരമതാ ചരക്കുകളുമായി നാലു വാഹനങ്ങൾ നിർത്തിയിട്ടിരിക്കുന്നു. ഞാൻ സമ്മതം ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ സന്തോഷിക്കുക. നിശ്ചയം നിന്റെ കടം വീട്ടാനുള്ളത് അല്ലാഹു കൊണ്ടുവന്നു തന്നിരിക്കുന്നു." പിന്നെ അവിടുന്ന് പറഞ്ഞു: "നിർത്തിയിട്ട നാലു വാഹനങ്ങൾ നീ കണ്ടില്ലെയോ?" അപ്പോൾ ഞാൻ പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം അവയും അവയുടെ മേലിലുള്ളതും നിനക്കുള്ളതാണ്. ഫദകിലെ ചക്രവർത്തി എനിക്ക് സമ്മാനമായി നൽകിയ ഭക്ഷണവും വസത്രവുമാണ് അവയുടെ മേലുള്ളത്. അതിനാൽ അവയെടുത്ത് നിന്റെ കടം വീട്ടുക." അപ്പോൾ ഞാൻ അപ്രകാരം ചെയ്തു. അദ്ദേഹം ഹദീസ് തുടർന്നു: പിന്നെ ഞാൻ പള്ളിയിലേക്ക് പോയി. അപ്പോൾ റസൂൽ(സ) പള്ളിയിലിരിക്കുന്നുണ്ട്. ഞാനവിടുത്തോട് സലാം പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നിന്റെ പക്കലുള്ള സ്വത്തിന്റെ കാര്യമെന്തായി?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലിന്റെ മേലിലുണ്ടായിരുന്ന കടങ്ങളെല്ലാം അല്ലാഹു വീട്ടിയിരിക്കുന്നു. ഇനി ഒരു കടവും ബാക്കിയില്ല. അവിടുന്ന് ചോദിച്ചു: "(സ്വത്തിൽ) വല്ലതും ബാക്കിയുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "അതിൽനിന്ന് എനിക്ക് ആശ്വാസം നൽകുന്ന വല്ല മാർഗ്ഗങ്ങളും നീ നോക്കുക. നിശ്ചയം അതിൽനിന്ന് നീ എന്നെ ആശ്വാസവാനാക്കുന്നതുവരെ എന്റെ ഭാര്യമാരിൽ ഒരാളുടെ അടുത്തേക്കും ഞാൻ പ്രവേശിക്കുന്നതല്ല." അങ്ങനെ റസൂൽ(സ) ഇശാഅ് നമസ്കരിച്ചു കഴിഞ്ഞപ്പോൾ എന്നെ വിളിച്ചു ഇപ്രകാരം ചോദിച്ചു: "നിന്റെ പക്കലുള്ള സ്വത്തിന്റെ കാര്യമെന്തായി?" നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അത് എന്റെ പക്കലുണ്ട്, ഒരാളുംതന്നെ നമ്മുടെ അടുക്കൽ വന്നിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) പള്ളിയിൽ രാപാർത്തു. നിവേദകൻ ഹദീസിന്റെ ബാക്കി വിശദീകരിച്ചു. അങ്ങനെ റസൂൽ(സ) ഇശാഅ് നമസ്കരിച്ച് കഴിഞ്ഞപ്പോൾ - അഥവാ അടുത്ത ദിവസം - എന്നെ വിളിച്ച് ചോദിച്ചു: "നിന്റെ പക്കലുള്ള സ്വത്തിന്റെ കാര്യമെന്തായി?" നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, നിശ്ചയം അതിൽനിന്ന് അല്ലാഹു അങ്ങേക്ക് ആശ്വാസം നൽകിയിരിക്കുന്നു. അപ്പോൾ അവിടുന്ന് തക്ബീർ ചൊല്ലുകയും അല്ലാഹുവിനെ സ്തുതിക്കുകയും ചെയ്തു. അത് അടുത്തുണ്ടായിരിക്കെ മരണമെത്തുന്നത് ഭയപ്പെട്ടതിനാലായിരുന്നു അത്. പിന്നെ ഞാൻ അവിടുത്തെ പിന്തുടർന്നു. അങ്ങനെ അവിടുന്ന് തന്റെ ഭാര്യമാരുടെ അടുത്ത് ചെല്ലുകയും അവരിൽ ഓരോരുത്തരോടായി സലാം പറയുകയും ചെയ്തു. ശേഷം അവിടുന്ന് കിടപ്പറയിലേക്ക് പോയി. ഇതിനെക്കുറിച്ചാണ് നിങ്ങളെന്നോട് ചോദിച്ചത്. (ദ)', 'عَبْدِ اللَّهِ الْهَوْزَنِيِّ قَالَ', 'അബ്ദുല്ലാഹിൽ ഹൗസനീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 127, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=25), 1, 'وَفِي رِوَايَةٍ: فَسَكَتَ عَنِّي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاغْتَمَزْتُهَا. فَخَرَجْتُ حَتَّى إِذَا أَتَيْتُ مَنْزِلِي، فَجَعَلْتُ سَيْفِي وَجِرَابِي وَنَعْلِي وَمِجَنِّي عِنْدَ رَأْسِي، حَتَّى إِذَا انْشَقَّ عَمُودُ الصُّبْحِ الْأَوَّلِ أَرَدْتُ أَنْ أَنْطَلِقَ فَإِذَا إِنْسَانٌ يَسْعَى يَدْعُو: يَا بِلَالُ، أَجِبْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقْتُ حَتَّى أَتَيْتُهُ، فَإِذَا أَرْبَعُ رَكَائِبَ مُنَاخَاتٌ عَلَيْهِنَّ أَحْمَالُهُنَّ، فَاسْتَأْذَنْتُ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَبْشِرْ، فَقَدْ جَاءَكَ اللَّهُ بِقَضَائِكَ". ثُمَّ قَالَ: "أَلَمْ تَرَ الرَّكَائِبَ الْمُنَاخَاتِ الْأَرْبَعَ". فَقُلْتُ: بَلَى. فَقَالَ: "إِنَّ لَكَ رِقَابَهُنَّ وَمَا عَلَيْهِنَّ، فَإِنَّ عَلَيْهِنَّ كِسْوَةً وَطَعَامًا أَهْدَاهُنَّ إِلَيَّ عَظِيمُ فَدَكٍ، فَاقْبِضْهُنَّ وَاقْضِ دَيْنَكَ". فَفَعَلْتُ، فَذَكَرَ الْحَدِيثَ، ثُمَّ انْطَلَقْتُ إِلَى الْمَسْجِدِ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ فِي الْمَسْجِدِ، فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: "مَا فَعَلَ مَا قِبَلَكَ". قُلْتُ: قَضَى اللَّهُ كُلَّ شَيْءٍ كَانَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يَبْقَ شَيْءٌ. قَالَ: "أَفَضَلَ شَيْءٌ". قُلْتُ: نَعَمْ، قَالَ: "انْظُرْ أَنْ تُرِيحَنِي مِنْهُ، فَإِنِّي لَسْتُ بِدَاخِلٍ عَلَى أَحَدٍ مِنْ أَهْلِي حَتَّى تُرِيحَنِي مِنْهُ". فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَتَمَةَ دَعَانِي فَقَالَ: "مَا فَعَلَ الَّذِي قِبَلَكَ". قَالَ: قُلْتُ: هُوَ مَعِي لَمْ يَأْتِنَا أَحَدٌ، فَبَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، وَقَصَّ الْحَدِيثَ، حَتَّى إِذَا صَلَّى الْعَتَمَةَ – يَعْنِي مِنَ الْغَدِ – دَعَانِي قَالَ: "مَا فَعَلَ الَّذِي قِبَلَكَ". قَالَ: قُلْتُ: قَدْ أَرَاحَكَ اللَّهُ مِنْهُ يَا رَسُولَ اللَّهِ، فَكَبَّرَ وَحَمِدَ اللَّهَ، شَفَقًا مِنْ أَنْ يُدْرِكَهُ الْمَوْتُ وَعِنْدَهُ ذَلِكَ، ثُمَّ اتَّبَعْتُهُ حَتَّى إِذَا جَاءَ أَزْوَاجَهُ فَسَلَّمَ عَلَى امْرَأَةٍ امْرَأَةٍ، حَتَّى أَتَى مَبِيتَهُ، فَهَذَا الَّذِي سَأَلْتَنِي عَنْهُ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: അപ്പോൾ തിരുമേനി(സ) മൗനം പാലിക്കുകയും എനിക്കതിൽ അതൃപ്തി തോന്നുകയും ചെയ്തു. ഞാൻ പുറത്തുവരികയും എന്റെ വീട്ടിൽചെന്ന് എന്റെ വാളും തോൽപാത്രവും ചെരിപ്പും പരിചയുമെല്ലാം എന്റെ തലക്കരികിൽ വെക്കുകയും ചെയ്തു. അങ്ങനെ ഒന്നാം പ്രഭാതത്തിന്റെ പ്രകാശം പൊട്ടിവിടർന്നപ്പോൾ ഞാൻ പുറപ്പെടാനുദ്ദേശിച്ചു. അപ്പോഴതാ, ഓ ബിലാൽ, അല്ലാഹുവിന്റെ റസൂലിന് താങ്കൾ ഉത്തരം നൽകുക എന്നു വിളിച്ചു പറഞ്ഞുകൊണ്ട് ഒരാൾ വരുന്നു. ഉടനെ ഞാൻ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് പോയി. അന്നേരമതാ ചരക്കുകളുമായി നാലു വാഹനങ്ങൾ നിർത്തിയിട്ടിരിക്കുന്നു. ഞാൻ സമ്മതം ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ സന്തോഷിക്കുക. നിശ്ചയം നിന്റെ കടം വീട്ടാനുള്ളത് അല്ലാഹു കൊണ്ടുവന്നു തന്നിരിക്കുന്നു." പിന്നെ അവിടുന്ന് പറഞ്ഞു: "നിർത്തിയിട്ട നാലു വാഹനങ്ങൾ നീ കണ്ടില്ലെയോ?" അപ്പോൾ ഞാൻ പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം അവയും അവയുടെ മേലിലുള്ളതും നിനക്കുള്ളതാണ്. ഫദകിലെ ചക്രവർത്തി എനിക്ക് സമ്മാനമായി നൽകിയ ഭക്ഷണവും വസത്രവുമാണ് അവയുടെ മേലുള്ളത്. അതിനാൽ അവയെടുത്ത് നിന്റെ കടം വീട്ടുക." അപ്പോൾ ഞാൻ അപ്രകാരം ചെയ്തു. അദ്ദേഹം ഹദീസ് തുടർന്നു: പിന്നെ ഞാൻ പള്ളിയിലേക്ക് പോയി. അപ്പോൾ റസൂൽ(സ) പള്ളിയിലിരിക്കുന്നുണ്ട്. ഞാനവിടുത്തോട് സലാം പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നിന്റെ പക്കലുള്ള സ്വത്തിന്റെ കാര്യമെന്തായി?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലിന്റെ മേലിലുണ്ടായിരുന്ന കടങ്ങളെല്ലാം അല്ലാഹു വീട്ടിയിരിക്കുന്നു. ഇനി ഒരു കടവും ബാക്കിയില്ല. അവിടുന്ന് ചോദിച്ചു: "(സ്വത്തിൽ) വല്ലതും ബാക്കിയുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "അതിൽനിന്ന് എനിക്ക് ആശ്വാസം നൽകുന്ന വല്ല മാർഗ്ഗങ്ങളും നീ നോക്കുക. നിശ്ചയം അതിൽനിന്ന് നീ എന്നെ ആശ്വാസവാനാക്കുന്നതുവരെ എന്റെ ഭാര്യമാരിൽ ഒരാളുടെ അടുത്തേക്കും ഞാൻ പ്രവേശിക്കുന്നതല്ല." അങ്ങനെ റസൂൽ(സ) ഇശാഅ് നമസ്കരിച്ചു കഴിഞ്ഞപ്പോൾ എന്നെ വിളിച്ചു ഇപ്രകാരം ചോദിച്ചു: "നിന്റെ പക്കലുള്ള സ്വത്തിന്റെ കാര്യമെന്തായി?" നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അത് എന്റെ പക്കലുണ്ട്, ഒരാളുംതന്നെ നമ്മുടെ അടുക്കൽ വന്നിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) പള്ളിയിൽ രാപാർത്തു. നിവേദകൻ ഹദീസിന്റെ ബാക്കി വിശദീകരിച്ചു. അങ്ങനെ റസൂൽ(സ) ഇശാഅ് നമസ്കരിച്ച് കഴിഞ്ഞപ്പോൾ - അഥവാ അടുത്ത ദിവസം - എന്നെ വിളിച്ച് ചോദിച്ചു: "നിന്റെ പക്കലുള്ള സ്വത്തിന്റെ കാര്യമെന്തായി?" നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, നിശ്ചയം അതിൽനിന്ന് അല്ലാഹു അങ്ങേക്ക് ആശ്വാസം നൽകിയിരിക്കുന്നു. അപ്പോൾ അവിടുന്ന് തക്ബീർ ചൊല്ലുകയും അല്ലാഹുവിനെ സ്തുതിക്കുകയും ചെയ്തു. അത് അടുത്തുണ്ടായിരിക്കെ മരണമെത്തുന്നത് ഭയപ്പെട്ടതിനാലായിരുന്നു അത്. പിന്നെ ഞാൻ അവിടുത്തെ പിന്തുടർന്നു. അങ്ങനെ അവിടുന്ന് തന്റെ ഭാര്യമാരുടെ അടുത്ത് ചെല്ലുകയും അവരിൽ ഓരോരുത്തരോടായി സലാം പറയുകയും ചെയ്തു. ശേഷം അവിടുന്ന് കിടപ്പറയിലേക്ക് പോയി. ഇതിനെക്കുറിച്ചാണ് നിങ്ങളെന്നോട് ചോദിച്ചത്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عِيَاضِ بْنِ حِمَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَهْدَيْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاقَةً، فَقَالَ: "أَسْلَمْتَ". فَقُلْتُ: لَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي نُهِيتُ عَنْ زَبَدِ الْمُشْرِكِينَ". (د,ت)', 'ഇയാളുബ്നു ഹിമാർ(റ): ഞാൻ നബി(സ)ക്ക് ഒരു ഒട്ടകത്തെ സമ്മാനമായി നൽകി. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നീ മുസ്ലിമായിട്ടുണ്ടോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം ബഹുദൈവാരാധകരുടെ ദാനം എനിക്ക് വിലക്കപ്പെട്ടിരിക്കുന്നു." (ദ,തു)', 'عِيَاضِ بْنِ حِمَارٍ', 'ഇയാളുബ്നു ഹിമാർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ وَالٍ إِلَّا وَلَهُ بِطَانَتَانِ: بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ وَتَنْهَاهُ عَنِ الْمُنْكَرِ، وَبِطَانَةٌ لَا تَأْلُوهُ خَبَالًا. فَمَنْ وُقِيَ شَرَّهَا فَقَدْ وُقِيَ، وَهُوَ مِنَ الَّتِي تَغْلِبُ عَلَيْهِ مِنْهُمَا". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടുതരം പ്രത്യേകക്കാരില്ലാത്ത ഒരു ഭരണാധികാരിയുമില്ല: അദ്ദേഹത്തെ നന്മകൊണ്ട് കൽപിക്കുകയും തിന്മയിൽനിന്ന് വിലക്കുകയും ചെയ്യുന്ന ഒരു വിഭാഗം പ്രത്യേകക്കാരും, തെറ്റുകളിൽനിന്ന് അദ്ദേഹത്തെ തടയാത്ത ഒരു വിഭാഗം പ്രത്യേകക്കാരും. ഇതിന്റെ (രണ്ടാമത്തതിന്റെ) തിന്മയിൽനിന്ന് സംരക്ഷിക്കപ്പെട്ടവനാരോ അവൻ സംരക്ഷിക്കപ്പെട്ടിരിക്കുന്നു. ഇവ രണ്ടിൽ അവനിലേക്ക് മുന്തിനിൽക്കുന്നതേതാണോ ആ വിഭാഗത്തിൽ പെട്ടവനാണവൻ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 129, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا بَعَثَ اللَّهُ مِنْ نَبِيٍّ وَلَا اسْتَخْلَفَ مِنْ خَلِيفَةٍ إِلَّا كَانَتْ لَهُ بِطَانَتَانِ: بِطَانَةٌ تَأْمُرُهُ بِالْخَيْرِ وَبِطَانَةٌ تَأْمُرُهُ بِالشَّرِّ وَتَحُضُّهُ عَلَيْهِ، وَالْمَعْصُومُ مَنْ عَصَمَ اللَّهُ عَزَّ وَجَلَّ". (خ,ن)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടുതരം പ്രത്യേകക്കാരില്ലാത്ത ഒരു നബിയെയും അല്ലാഹു നിയോഗിച്ചിട്ടില്ല, ഒരു ഖലീഫയെയും അല്ലാഹു നിശ്ചയിച്ചിട്ടില്ല: അദ്ദേഹത്തോട് നന്മ കൽപിക്കുന്ന ഒരു വിഭാഗവും അദ്ദേഹത്തോട് തിന്മ കൽപിക്കുകയും അതിലേക്ക് അദ്ദേഹത്തെ പ്രേരിപ്പിക്കുകയും ചെയ്യുന്ന മറ്റൊരു വിഭാഗവും. അല്ലാഹു ആരെ സംരക്ഷിച്ചുവോ അവനാണ് സുരക്ഷിതൻ." (ബു,ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا بُعِثَ مِنْ نَبِيٍّ وَلَا كَانَ بَعْدَهُ مِنْ خَلِيفَةٍ إِلَّا وَلَهُ بِطَانَتَانِ: بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ وَتَنْهَاهُ عَنِ الْمُنْكَرِ، وَبِطَانَةٌ لَا تَأْلُوهُ خَبَالًا، فَمَنْ وُقِيَ بِطَانَةَ السُّوءِ فَقَدْ وُقِيَ". (ن)', 'അബൂഅയ്യൂബ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "രണ്ടുതരം പ്രത്യേകക്കാരില്ലാതെ ഒരു നബി നിയോഗിക്കപ്പെടുകയോ, അദ്ദേഹത്തിനുശേഷം ഒരു പ്രതിനിധിയുണ്ടാവുകയോ ചെയ്തിട്ടില്ല: അദ്ദേഹത്തോട് നന്മ കൽപിക്കുകയും തിന്മയിൽനിന്ന് തടയുകയും ചെയ്യുന്ന ഒരു വിഭാഗവും, തിന്മയിൽനിന്ന് അദ്ദേഹത്തെ തടയാത്ത മറ്റൊരു വിഭാഗവും. മോശപ്പെട്ട വിഭാഗത്തിൽനിന്ന് സംരക്ഷിക്കപ്പെട്ടവനാരോ നിശ്ചയം അവൻ സംരക്ഷിക്കപ്പെട്ടിരിക്കുന്നു." (ന)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "نَحْنُ الْآخِرُونَ السَّابِقُونَ". وَيَقُولُ: "مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ، وَمَنْ يُطِعِ الْأَمِيرَ فَقَدْ أَطَاعَنِي، وَمَنْ يَعْصِ الْأَمِيرَ فَقَدْ عَصَانِي، وَإِنَّمَا الْإِمَامُ جُنَّةٌ يُقَاتَلُ مِنْ وَرَائِهِ وَيُتَّقَى بِهِ، فَإِنْ أَمَرَ بِتَقْوَى اللَّهِ وَعَدَلَ، فَإِنَّ لَهُ بِذَلِكَ أَجْرًا، وَإِنْ قَالَ بِغَيْرِهِ فَإِنَّ عَلَيْهِ مِنْهُ". (ق,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "നാമാണ് അവസാനം വന്നവരും മുന്നിൽ നിൽക്കുന്നവരും." ശേഷം പറയുന്നു: "എനിക്ക് ആര് കീഴ്പ്പെട്ടുവോ അവൻ അല്ലാഹുവിന് കീഴ്പ്പെട്ടിരിക്കുന്നു. എന്നെ ആര് ധിക്കരിച്ചുവോ അവൻ അല്ലാഹുവിനോട് ധിക്കാരം കാണിച്ചിരിക്കുന്നു. അമീറിന് ആര് കീഴ്പ്പെട്ടുവോ അവൻ എനിക്ക് കീഴ്പ്പെട്ടിരിക്കുന്നു. അമീറിനെ ആര് ധിക്കരിച്ചുവോ അവൻ എന്നെ ധിക്കരിച്ചിരിക്കുന്നു. നിശ്ചയം നേതാവ് പരിചയാണ്. അവന്റെ പിന്നിൽ നിന്ന് യുദ്ധം നടക്കുന്നു. അവനെക്കൊണ്ട് സംരക്ഷിക്കപ്പെടുകയും ചെയ്യുന്നു. നേതാവ് അല്ലാഹുവിന് തഖ്വ ചെയ്യാൻ കൽപിക്കുകയും നീതി ചെയ്യുകയും ചെയ്താൽ അവന്നതിന് കൂലിയുണ്ട്. അതല്ലാത്തതുകൊണ്ട് അവൻ കൽപിച്ചാൽ അതിന്റെ തിന്മ അവൻ അനുഭവിക്കുകയും ചെയ്യും." (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: {يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ} [النساء: ٥٩] نُزِلَتْ فِي عَبْدِ اللَّهِ بْنِ قَيْسِ بْنِ عَدِيٍّ، بَعَثَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ''സത്യവിശ്വാസികളേ, അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും നിങ്ങളിലെ നേതാക്കളെയും നിങ്ങൾ അനുസരിക്കുക'' (നിസാഅ്: 59) ഈ സൂക്തം അബ്ദുല്ലാഹിബ്നു ഖൈസുബ്നു അദിയ്യ്(റ)വിനെക്കുറിച്ചാണ് ഇറങ്ങിയത്. അദ്ദേഹത്തെ നബി(സ) ഒരു യുദ്ധസംഘത്തിലയച്ചിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'النساء: ٥٩', null, 130, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "السَّمْعُ وَالطَّاعَةُ عَلَى الْمَرْءِ الْمُسْلِمِ فِيمَا أَحَبَّ وَكَرِهَ، مَا لَمْ يُؤْمَرْ بِمَعْصِيَةٍ، فَإِذَا أُمِرَ بِمَعْصِيَةٍ فَلَا سَمْعَ وَلَا طَاعَةَ". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "തെറ്റ് കൊണ്ട് കൽപിക്കപ്പെടാത്ത കാലത്തോളം, ഒരു മുസ്ലിം തനിക്ക് ഇഷ്ടപ്പെട്ടതോ വെറുത്തതോ ആയ കാര്യത്തിൽ അനുസരണ കൈക്കൊള്ളേണ്ടതാണ്. അവൻ തെറ്റായ ഒരു കാര്യം കൊണ്ട് കൽപിക്കപ്പെട്ടാൽ അതനുസരിക്കരുത്." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عُقْبَةَ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً فَسَلَحْتُ رَجُلًا مِنْهُمْ سَيْفًا، فَلَمَّا رَجَعَ قَالَ: لَوْ رَأَيْتَ مَا لَامَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: "أَعَجَزْتُمْ إِذْ بَعَثْتُ رَجُلًا مِنْكُمْ، فَلَمْ يَمْضِ لِأَمْرِي، أَنْ تَجْعَلُوا مَكَانَهُ مَنْ يَمْضِي لِأَمْرِي". (د)', 'ഉഖ്ബതുബ്നു മാലിക്(റ): നബി(സ) ഒരു യുദ്ധസംഘത്തെ അയച്ചു. അവരിലൊരാൾക്ക് ഞാനൊരു വാൾ കൊടുത്തു. മടങ്ങിവന്നപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഞങ്ങളെ ആക്ഷേപിച്ചത് നിങ്ങൾക്കു കാണണോ? നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ കൂട്ടത്തിൽ എന്റെ ആജ്ഞ പൂർത്തീകരിക്കാത്ത ഒരാളെ ഞാനയച്ചപ്പോൾ അയാളുടെ സ്ഥാനത്ത് എന്റെ കൽപന നിർവഹിക്കുന്ന മറ്റൊരാളെ വെക്കാൻ നിങ്ങൾ അശക്തരായോ?" (ദ)', 'عُقْبَةَ بْنِ مَالِكٍ', 'ഉഖ്ബതുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أُمِّ الْحُصَيْنِ الْأَحْمَسِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي حَجَّةِ الْوَدَاعِ، وَعَلَيْهِ بُرْدٌ قَدِ الْتَفَعَ بِهِ مِنْ تَحْتِ إِبْطِهِ، قَالَتْ: فَأَنَا أَنْظُرُ إِلَى عَضَلَةِ عَضُدِهِ تَرْتَجُّ، سَمِعْتُهُ يَقُولُ: "يَا أَيُّهَا النَّاسُ، اتَّقُوا اللَّهَ، وَإِنْ أُمِّرَ عَلَيْكُمْ عَبْدٌ حَبَشِيٌّ مُجَدَّعٌ، فَاسْمَعُوا لَهُ وَأَطِيعُوا، مَا أَقَامَ لَكُمْ كِتَابَ اللَّهِ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'ഉമ്മുഹുസൈനുൽ അഹ്മസിയ്യ(റ): ഹജ്ജത്തുൽ വിദാഇന്റെ ദിവസം റസൂൽ(സ) പ്രസംഗിക്കുന്നത് ഞാൻ കേട്ടു. കക്ഷത്തിന്റെ അടിഭാഗം മൂടിയ ഒരു വസ്ത്രം നബി(സ) ധരിച്ചിട്ടുണ്ടായിരുന്നു. ഉമ്മുഹുസൈൻ(റ) പറഞ്ഞു: ഞാൻ നബി(സ)യുടെ തണ്ടൻകയ്യിലെ പേശിയിലേക്ക് നോക്കുമ്പോൾ അത് ഇളകിക്കൊണ്ടിരിക്കുകയായിരുന്നു. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ജനങ്ങളേ, നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. എത്യോപ്യക്കാരനും അംഗവൈകല്യമുള്ളവനുമായ ഒരു അടിമ നിങ്ങൾക്ക് നേതാവായി വന്നാലും ശരി, അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തെ അവൻ നിങ്ങളിൽ നടപ്പാക്കുന്ന കാലത്തോളം നിങ്ങൾ അവനെ അനുസരിക്കുക." ഹദീസ് ഹസനാണ്. (മു,ദ,തു,ന,ജ)', 'أُمِّ الْحُصَيْنِ الْأَحْمَسِيَّةِ', 'ഉമ്മുഹുസൈനുൽ അഹ്മസിയ്യ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ. وَمَنْ أَطَاعَ الْإِمَامَ فَقَدْ أَطَاعَنِي، وَمَنْ عَصَى الْإِمَامَ فَقَدْ عَصَانِي". (ق,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും എന്നെ അനുസരിച്ചാൽ അവൻ അല്ലാഹുവിനെ അനുസരിച്ചു. ആരെങ്കിലും എനിക്ക് എതിരായാൽ അവൻ അല്ലാഹുവിന് എതിരായി. ആരെങ്കിലും നേതാവിനെ അനുസരിച്ചാൽ അവൻ എന്നെ അനുസരിച്ചു. ആരെങ്കിലും നേതാവിന് എതിരായാൽ അവൻ എനിക്ക് എതിരായി." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْمَعُوا وَأَطِيعُوا، وَإِنِ اسْتُعْمِلَ عَلَيْكُمْ عَبْدٌ حَبَشِيٌّ، كَأَنَّ رَأْسَهُ زَبِيبَةٌ". (خ,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കേൾക്കുന്നവരും അനുസരിക്കുന്നവരുമാവുക. നിങ്ങളുടെ നേതാവ്, ഉണക്കമുന്തിരി പോലെ തലയുള്ള അബ്സീനിയക്കാരനായ അടിമയാണെങ്കിലും ശരി." (ബു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 131, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ انْتَهَى إِلَى الرَّبَذَةِ وَقَدْ أُقِيمَتِ الصَّلَاةُ، فَإِذَا عَبْدٌ يَؤُمُّهُمْ، فَقِيلَ: هَذَا أَبُو ذَرٍّ. فَذَهَبَ يَتَأَخَّرُ، فَقَالَ أَبُو ذَرٍّ: أَوْصَانِي خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَسْمَعَ وَأُطِيعَ، وَإِنْ كَانَ عَبْدًا حَبَشِيًّا مُجَدَّعَ الْأَطْرَافِ. (جه)', 'അബൂദർറ്(റ): നിസ്കാരത്തിന് ഇഖാമത്ത് കൊടുത്ത സമയത്ത് അദ്ദേഹം ''റബദ'' എന്ന സ്ഥലത്തെത്തി. അവിടെ അവർക്ക് ഇമാം നിൽക്കുന്നത് ഒരു അടിമയായിരുന്നു. അബൂദർറ്(റ) വന്നിരിക്കുന്നുവെന്ന് പറയപ്പെട്ടു. അപ്പോൾ അടിമ പിന്നോട്ട് നിന്നു. അബൂദർറ്(റ) പറഞ്ഞു: അംഗവൈകല്യമുള്ള അബ്സീനിയക്കാരനായ ഒരു അടിമയാണെങ്കിലും ശരി, അവനെ അനുസരിക്കണമെന്ന് എന്റെ കൂട്ടുകാരൻ - റസൂൽ(സ) - എന്നെ ഉപദേശിച്ചിരിക്കുന്നു. (ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ بَدْرٍ، وَجِيءَ بِالْأُسَارَى، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا تَقُولُونَ فِي هَؤُلَاءِ الْأُسَارَى". (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ബദർ യുദ്ധ ദിവസം യുദ്ധത്തടവുകാരെ റസൂൽ(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "ഈ ബന്ധികളുടെ കാര്യത്തിൽ നിങ്ങളുടെ അഭിപ്രായമെന്താണ്?" (തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اكْتُبُوا لِي مَنْ تَلَفَّظَ بِالْإِسْلَامِ مِنَ النَّاسِ". فَكَتَبْنَا لَهُ أَلْفًا وَخَمْسَ مِائَةِ رَجُلٍ فَقُلْنَا: نَخَافُ وَنَحْنُ أَلْفٌ وَخَمْسُ مِائَةٍ، فَلَقَدْ رَأَيْتُنَا ابْتُلِينَا حَتَّى إِنَّ الرَّجُلَ لَيُصَلِّي وَحْدَهُ وَهُوَ خَائِفٌ. (خ)', 'ഹുദൈഫ(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങളിൽ നിന്ന് ഇസ്ലാമിന്റെ വചനം മൊഴിഞ്ഞവരെ എനിക്ക് നിങ്ങൾ രേഖപ്പെടുത്തിത്തരിക." അങ്ങനെ ആയിരത്തഞ്ഞൂറ് പേരെ ഞങ്ങൾ നബി(സ)ക്ക് എഴുതിക്കൊടുത്തു. ഞങ്ങൾ ചോദിച്ചു: ആയിരത്തഞ്ഞൂറ് പേരുണ്ടായിട്ട് ഇനിയും ഞങ്ങൾ ഭയപ്പെടണോ? എന്നാൽ ഇന്ന് പരീക്ഷണം വന്ന് ഞങ്ങളിലൊരാൾ പേടിച്ച് ഒറ്റയ്ക്ക് നമസ്കരിക്കുന്ന അവസ്ഥ ഞങ്ങൾക്ക് വന്നിരിക്കുന്നതായി ഞാൻ കാണുന്നു. (ബു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أُمِّ الْحُصَيْنِ بِنْتِ إِسْحَاقَ الْأَحْمَسِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي حَجَّةِ الْوَدَاعِ: "وَلَوِ اسْتُعْمِلَ عَلَيْكُمْ عَبْدٌ حَبَشِيٌّ، يَقُودُكُمْ بِكِتَابِ اللَّهِ، فَاسْمَعُوا لَهُ وَأَطِيعُوا". (م,ن)', 'ഉമ്മുൽഹുസൈൻ ബിൻതുഇസ്ഹാഖിൽ അഹ്മസിയ്യ(റ): ഹജ്ജതുൽ വിദാഇൽ റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ ഗ്രന്ഥമനുസരിച്ച് നിങ്ങളെ നയിക്കുന്ന, നീഗ്രോയായ ഒരു അടിമയാണ് നിങ്ങളുടെ ഭരണാധികാരിയായി നിയമിക്കപ്പെട്ടതെങ്കിലും, നിങ്ങളദ്ദേഹത്തിന് ചെവികൊടുക്കുകയും അനുസരിക്കുകയും ചെയ്യുക." (മു,ന)', 'أُمِّ الْحُصَيْنِ بِنْتِ إِسْحَاقَ الْأَحْمَسِيَّةِ', 'ഉമ്മുൽഹുസൈൻ ബിൻതുഇസ്ഹാഖിൽ അഹ്മസിയ്യ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 132, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ يَحْيَى بْنِ حُصَيْنٍ، عَنْ جَدَّتِهِ أُمِّ الْحُصَيْنِ رَضِيَ اللَّهُ عَنْهَا، قَالَ: سَمِعْتُهَا تَقُولُ: حَجَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةَ الْوَدَاعِ، قَالَتْ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْلًا كَثِيرًا، ثُمَّ سَمِعْتُهُ يَقُولُ: "إِنْ أُمِّرَ عَلَيْكُمْ عَبْدٌ مُجَدَّعٌ – حَسِبْتُهَا قَالَتْ – أَسْوَدُ، يَقُودُكُمْ بِكِتَابِ اللَّهِ، فَاسْمَعُوا لَهُ وَأَطِيعُوا". (م)', 'യഹ്യബ്നു ഹുസൈൻ(റ) തന്റെ വല്ല്യുമ്മയായ ഉമ്മുൽ ഹുസൈൻ(റ)യിൽ നിന്ന് നിവേദനം: മഹതി പറയുന്നതായി ഞാൻ കേട്ടു: ഹജ്ജതുൽ വിദാഇൽ റസൂൽ(സ)യോടൊപ്പം ഞാൻ ഹജ്ജ് ചെയ്തു. മഹതി പറയുന്നു: അപ്പോൾ റസൂൽ(സ) കുറേ കാര്യങ്ങൾ പറഞ്ഞു. ശേഷം അവിടുന്ന് പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ ഗ്രന്ഥമനുസരിച്ച് നിങ്ങളെ നയിക്കുന്ന, അംഗവൈകല്യമുള്ള ഒരു അടിമ - ''കറുത്തവനായ'' എന്നുകൂടി മഹതി പറഞ്ഞുവെന്നാണ് ഞാൻ വിചാരിക്കുന്നത് - നിങ്ങളുടെ നേതാവാക്കപ്പെട്ടാൽ നിങ്ങളദ്ദേഹത്തിന് ചെവികൊടുക്കുകയും അനുസരിക്കുകയും ചെയ്യുക." (മു)', 'يَحْيَى بْنِ حُصَيْنٍ، عَنْ جَدَّتِهِ أُمِّ الْحُصَيْنِ', 'യഹ്യബ്നു ഹുസൈൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّاسُ يَسْأَلُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَيْرِ، وَكُنْتُ أَسْأَلُهُ عَنِ الشَّرِّ مَخَافَةَ أَنْ يُدْرِكَنِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ إِنَّا كُنَّا فِي جَاهِلِيَّةٍ وَشَرٍّ، فَجَاءَنَا اللَّهُ بِهَذَا الْخَيْرِ، فَهَلْ بَعْدَ هَذَا الْخَيْرِ شَرٌّ؟ قَالَ: "نَعَمْ". فَقُلْتُ لَهُ: هَلْ بَعْدَ ذَلِكَ الشَّرِّ مِنْ خَيْرٍ؟ قَالَ: "نَعَمْ، وَفِيهِ دَخَنٌ". قُلْتُ: وَمَا دَخَنُهُ؟ قَالَ: "قَوْمٌ يَسْتَنُّونَ بِغَيْرِ سُنَّتِي وَيَهْدُونَ بِغَيْرِ هَدْيِي، تَعْرِفُ مِنْهُمْ وَتُنْكِرُ". فَقُلْتُ: هَلْ بَعْدَ ذَلِكَ الْخَيْرِ مِنْ شَرٍّ؟ قَالَ: "نَعَمْ، دُعَاةٌ عَلَى أَبْوَابِ جَهَنَّمَ، مَنْ أَجَابَهُمْ إِلَيْهَا قَذَفُوهُ فِيهَا". فَقُلْتُ: يَا رَسُولَ اللَّهِ صِفْهُمْ لَنَا. قَالَ: "نَعَمْ، قَوْمٌ مِنْ جِلْدَتِنَا وَيَتَكَلَّمُونَ بِأَلْسِنَتِنَا". قُلْتُ: يَا رَسُولَ اللَّهِ، فَمَا تَرَى إِنْ أَدْرَكَنِي ذَلِكَ؟ قَالَ: "تَلْزَمُ جَمَاعَةَ الْمُسْلِمِينَ وَإِمَامَهُمْ" فَقُلْتُ: فَإِنْ لَمْ تَكُنْ لَهُمْ جَمَاعَةٌ وَلَا إِمَامٌ؟ قَالَ: "فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا، وَلَوْ أَنْ تَعَضَّ عَلَى أَصْلِ شَجَرَةٍ، حَتَّى يُدْرِكَكَ الْمَوْتُ وَأَنْتَ عَلَى ذَلِكَ". (ق)', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ): ജനങ്ങൾ റസൂൽ(സ)യോട് നന്മയെക്കുറിച്ച് ചോദിക്കുമായിരുന്നു. എന്നാൽ എനിക്ക് തിന്മയെത്തുന്നത് ഭയന്നതിനാൽ ഞാനവിടുത്തോട് തിന്മയെക്കുറിച്ച് ചോദിക്കുമായിരുന്നു. അങ്ങനെ ഞാനവിടുത്തോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം ഞങ്ങൾ അജ്ഞതയിലും തിന്മയിലുമായിരുന്നു, അങ്ങനെ അല്ലാഹു ഞങ്ങൾക്ക് ഈ നന്മ കൊണ്ടുതന്നു. അതിനാൽ ഈ നന്മക്കു ശേഷം വല്ല തിന്മയുമുണ്ടോ? അവിടുന്ന് പറഞ്ഞു: "അതെ." അപ്പോൾ ഞാൻ ചോദിച്ചു: ആ തിന്മക്കു ശേഷം വല്ല നന്മയുമുണ്ടോ? അവിടുന്ന് പറഞ്ഞു: "അതെ, അതിലൊരു തകരാറുമുണ്ട്." ഞാൻ ചോദിച്ചു: എന്താണതിന്റെ തകരാറ്? അവിടുന്ന് പറഞ്ഞു: "എന്റേതല്ലാത്ത ചര്യയെ പിന്തുടരുകയും എന്റേതല്ലാത്ത മാർഗ്ഗം സ്വീകരിക്കുകയും ചെയ്യുന്ന ഒരു വിഭാഗമാണത്. നീയവരെ അറിയുകയും എതിർക്കുകയും ചെയ്യും." അപ്പോൾ ഞാൻ ചോദിച്ചു: ആ നന്മക്കു ശേഷം വല്ല തിന്മയുമുണ്ടോ? അവിടുന്ന് പറഞ്ഞു: "അതെ, നരകവാതിൽക്കലുള്ള ഒരു പറ്റം പ്രബോധകരാണവർ. അതിലേക്കുള്ള അവരുടെ വിളിക്ക് ഉത്തരം ചെയ്യുന്നവരെ അവർ നരകത്തിലകപ്പെടുത്തുന്നതാണ്." അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവരുടെ വിശേഷണങ്ങൾ ഞങ്ങൾക്ക് പറഞ്ഞുതന്നാലും. അവിടുന്ന് പറഞ്ഞു: "അതെ, നമ്മുടെ ജാതിയിൽ പെട്ടവരും നമ്മുടെ ഭാഷ സംസാരിക്കുന്നവരുമായ ഒരു സമൂഹമാണത്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ആ വിഭാഗത്തെ ഞാൻ കണ്ടുമുട്ടിയാൽ എന്താണു ചെയ്യേണ്ടത്? അവിടുന്ന് പറഞ്ഞു: "മുസ്ലിംകളുടെ സംഘത്തെയും അവരുടെ നേതാവിനെയും നീ മുറുകെ പിടിക്കുക." അപ്പോൾ ഞാൻ ചോദിച്ചു: അവർക്ക് സംഘമോ നേതാവോ ഇല്ലെങ്കിലോ? അവിടുന്ന് പറഞ്ഞു: "അപ്പോൾ ഒരു മരത്തിന്റെ മുരടിൽ കടിച്ചുപിടിച്ചുകൊണ്ടെങ്കിലും എല്ലാ വിഭാഗങ്ങളിൽനിന്നും നീ വിട്ടുനിൽക്കുക, ആ അവസ്ഥയിൽ നിനക്ക് മരണമാസന്നമാകും വരെ." (ബു,മു)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 133, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ قَالَ: دَخَلْتُ الْمَسْجِدَ فَإِذَا عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا جَالِسٌ فِي ظِلِّ الْكَعْبَةِ، وَالنَّاسُ مُجْتَمِعُونَ عَلَيْهِ، فَأَتَيْتُهُمْ فَجَلَسْتُ إِلَيْهِ، فَقَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَنَزَلْنَا مَنْزِلًا، فَمِنَّا مَنْ يُصْلِحُ خِبَاءَهُ، وَمِنَّا مَنْ يَنْتَضِلُ، وَمِنَّا مَنْ هُوَ فِي جَشَرِهِ، إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الصَّلَاةَ جَامِعَةً، فَاجْتَمَعْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّهُ لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلَّا كَانَ حَقًّا عَلَيْهِ أَنْ يَدُلَّ أُمَّتَهُ عَلَى خَيْرِ مَا يَعْلَمُهُ لَهُمْ، وَيُنْذِرَهُمْ شَرَّ مَا يَعْلَمُهُ لَهُمْ، وَإِنَّ أُمَّتَكُمْ هَذِهِ جُعِلَ عَافِيَتُهَا فِي أَوَّلِهَا، وَسَيُصِيبُ آخِرَهَا بَلَاءٌ وَأُمُورٌ تُنْكِرُونَهَا، وَتَجِيءُ فِتْنَةٌ فَيُرَقِّقُ بَعْضُهَا بَعْضًا، وَتَجِيءُ الْفِتْنَةُ، فَيَقُولُ الْمُؤْمِنُ: هَذِهِ مُهْلِكَتِي، ثُمَّ تَنْكَشِفُ، وَتَجِيءُ الْفِتْنَةُ فَيَقُولُ الْمُؤْمِنُ: هَذِهِ هَذِهِ، فَمَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنِ النَّارِ وَيُدْخَلَ الْجَنَّةَ فَلْتَأْتِهِ مَنِيَّتُهُ وَهُوَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ، وَلْيَأْتِ إِلَى النَّاسِ الَّذِي يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ. وَمَنْ بَايَعَ إِمَامًا فَأَعْطَاهُ صَفْقَةَ يَدِهِ، وَثَمَرَةَ قَلْبِهِ، فَلْيُطِعْهُ إِنِ اسْتَطَاعَ، فَإِنْ جَاءَ آخَرُ يُنَازِعُهُ فَاضْرِبُوا عُنُقَ الْآخَرِ". فَدَنَوْتُ مِنْهُ فَقُلْتُ [لَهُ]: أَنْشُدُكَ اللَّهَ، آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَأَهْوَى إِلَى أُذُنَيْهِ وَقَلْبِهِ بِيَدَيْهِ، وَقَالَ: سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي. فَقُلْتُ لَهُ: هَذَا ابْنُ عَمِّكَ مُعَاوِيَةُ، يَأْمُرُنَا أَنْ نَأْكُلَ أَمْوَالَنَا بَيْنَنَا بِالْبَاطِلِ وَنَقْتُلَ أَنْفُسَنَا، وَاللَّهُ عَزَّ وَجَلَّ يَقُولُ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا} [النساء: ٢٩]. قَالَ: فَسَكَتَ سَاعَةً ثُمَّ قَالَ: أَطِعْهُ فِي طَاعَةِ اللَّهِ، وَاعْصِهِ فِي مَعْصِيَةِ اللَّهِ عَزَّ وَجَلَّ. (م,ن)', 'അബ്ദുർറഹ്മാനിബ്നു അബ്ദിറബ്ബിൽ കഅ്ബ: ഞാൻ പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോഴതാ അബ്ദുല്ലാഹിബ്നു അംറിബ്നിൽ ആസ്(റ) കഅ്ബയുടെ തണലിലിരിക്കുന്നു. ജനങ്ങൾ അദ്ദേഹത്തിനു ചുറ്റും കൂടിയിട്ടുമുണ്ട്. ഞാനവരുടെ അടുക്കൽ ചെല്ലുകയും അദ്ദേഹത്തിന്റെയടുത്ത് ഇരിക്കുകയും ചെയ്തു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യുടെ കൂടെ ഒരു യാത്രയിലായിരിക്കെ ഞങ്ങൾ ഒരിടത്തിറങ്ങി. അപ്പോൾ ഞങ്ങളിൽ ചിലർ തങ്ങളുടെ തമ്പുകൾ ശരിയാക്കുന്നു. ചിലർ അമ്പെയ്ത്തു മൽസരം നടത്തുന്നു. ചിലർ മൃഗങ്ങളെ മേയാൻ വിടുന്നു. അന്നേരം റസൂൽ(സ)ക്കുവേണ്ടി ഒരാൾ ഇപ്രകാരം വിളിച്ചു പറഞ്ഞു: ''അസ്സ്വലാത്ത ജാമിഅ'' (നിസ്കാരം നിർവ്വഹിക്കാൻ സമയമായി). അപ്പോൾ ഞങ്ങൾ റസൂൽ(സ)ക്ക് ചുറ്റും കൂടുകയും അവിടുന്ന് ഇപ്രകാരം പറയുകയും ചെയ്തു: "തന്റെ സമുദായത്തിന് നന്മയാണെന്ന് അറിഞ്ഞത് അവർക്ക് അറിയിച്ചു കൊടുക്കലും, അവർക്ക് തിന്മയാണെന്ന് മനസ്സിലാക്കിയതിനെ സംബന്ധിച്ച് അവർക്ക് മുന്നറിയിപ്പ് നൽകലും നിർബന്ധ ബാധ്യതയല്ലാത്ത ഒരു പ്രവാചകനും എനിക്കു മുമ്പുണ്ടായിട്ടില്ല. നിശ്ചയം നിങ്ങളുടെ ഈ സമുദായത്തിന്റെ ആരോഗ്യം (നന്മ) അതിന്റെ ആദ്യത്തിലാണ്. അതിന്റെ അവസാനക്കാർക്ക് നിരവധി വിപത്തുകളും നിങ്ങൾ വെറുക്കുന്ന പല കാര്യങ്ങളും വന്നുചേരും. കുഴപ്പങ്ങളുണ്ടാവുകയും അവയിൽ ചിലത് അതികഠിനമായതിനാൽ മറ്റു ചിലത് കാഠിന്യം കുറഞ്ഞതായി അനുഭവപ്പെടുകയും ചെയ്യും. കുഴപ്പങ്ങളുണ്ടാവുകയും ഇത് എന്നെ നശിപ്പിക്കുന്നതാണെന്ന് സത്യവിശ്വാസി പറയുകയും പിന്നീടത് നീങ്ങിപ്പോവുകയും ചെയ്യും. പിന്നെയും ഫിത്നയുണ്ടാവും. അപ്പോൾ ഇതാണ് ഏറ്റവും കഠിനമായ വിപത്ത് എന്ന് വിശ്വാസി പറയും. അതിനാൽ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കപ്പെടാനും നരകത്തെതൊട്ട് വിദൂരത്താക്കപ്പെടാനും ആരെങ്കിലും ആഗ്രഹിക്കുന്നുവെങ്കിൽ, അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നവനായിരിക്കെ മരണം അവന് വന്നുകൊള്ളട്ടെ. തന്നോട് വർത്തിക്കപ്പെടാനാഗ്രഹിക്കുന്ന രൂപത്തിൽ ജനങ്ങളോടവൻ വർത്തിക്കുകയും ചെയ്യട്ടെ. ഒരാൾ ഒരു നേതാവുമായി ഉടമ്പടി ചെയ്യുകയും തന്റെ കരാറും ആത്മാർത്ഥ സ്നേഹവുമെല്ലാം അദ്ദേഹത്തിനവൻ നൽകുകയും ചെയ്താൽ, സാധ്യമെങ്കിലവൻ അദ്ദേഹത്തെ അനുസരിച്ചു കൊള്ളട്ടെ. ഇനി അദ്ദേഹത്തിനെതിരെ മറ്റൊരാൾ രംഗപ്രവേശം ചെയ്താൽ അവന്റെ പിരടി നിങ്ങൾ വെട്ടുക." അപ്പോൾ ഞാൻ അദ്ദേഹത്തിന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിനെ മുൻനിർത്തി ഞാൻ ചോദിക്കുന്നു: റസൂൽ(സ)യിൽനിന്ന് താങ്കളിത് കേട്ടുവോ? അപ്പോൾ അദ്ദേഹം തന്റെ ഇരു കൈകൾകൊണ്ട് തന്റ ഇരു ചെവികളിലേക്കും ഹൃദയത്തിലേക്കും ചൂണ്ടിക്കൊണ്ട് പറഞ്ഞു: എന്റെ ഇരു ചെവികളും അത് കേൾക്കുകയും എന്റെ ഹൃദയം അത് മനഃപ്പാഠമാക്കുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ അദ്ദേഹത്തോട് ഞാൻ പറഞ്ഞു: ഞങ്ങൾ പരസ്പരം ഞങ്ങളുടെ സ്വത്ത് അനർഹമായി ഭക്ഷിക്കുവാനും ആത്മഹത്യ ചെയ്യുവാനും, അങ്ങയുടെ പിതൃവ്യപുത്രനായ മുആവിയ(റ) ഇതാ ഞങ്ങളോട് കൽപിക്കുന്നു. അല്ലാഹുവാണെങ്കിൽ പറയുന്നു: ''സത്യവിശ്വാസികളേ, പരസ്പര തൃപ്തിയോടെയുള്ള കച്ചവടമൊഴിച്ച്, നിങ്ങളുടെ സമ്പത്ത് നിങ്ങൾ പരസ്പരം അനർഹമായി ഭക്ഷിക്കരുത്. നിങ്ങൾ ആത്മഹത്യ ചെയ്യുകയും അരുത്. നിശ്ചയം അല്ലാഹു നിങ്ങളോട് കരുണയുള്ളവനാകുന്നു.'' (നിസാഅ്: 29) നിവേദകൻ പറയുന്നു: അപ്പോഴദ്ദേഹം അൽപസമയം നിശബ്ദനായി. ശേഷം പറഞ്ഞു: അല്ലാഹുവിനോടുള്ള അനുസരണയിൽ നിങ്ങൾ അദ്ദേഹത്തെ അനുസരിക്കുകയും അല്ലാഹുവിനെ ധിക്കരിക്കുമ്പോൾ നിങ്ങൾ അദ്ദേഹത്തെ ധിക്കരിക്കുകയും ചെയ്യുക. (മു,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ قَالَ', 'അബ്ദുർറഹ്മാനിബ്നു അബ്ദിറബ്ബിൽ കഅ്ബ', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'النساء: ٢٩', null, 134, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ وَائِلٍ الْحَضْرَمِيِّ قَالَ: سَأَلَ سَلَمَةُ بْنُ يَزِيدَ الْجُعْفِيُّ رَضِيَ اللَّهُ عَنْهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللَّهِ، أَرَأَيْتَ إِنْ قَامَتْ عَلَيْنَا أُمَرَاءُ يَسْأَلُونَا حَقَّهُمْ وَيَمْنَعُونَا حَقَّنَا، فَمَا تَأْمُرُنَا؟ فَأَعْرَضَ عَنْهُ، ثُمَّ سَأَلَهُ فَأَعْرَضَ عَنْهُ، ثُمَّ سَأَلَهُ فِي الثَّانِيَةِ أَوْ فِي الثَّالِثَةِ، فَجَذَبَهُ الْأَشْعَثُ بْنُ قَيْسٍ وَقَالَ: اسْمَعُوا وَأَطِيعُوا، فَإِنَّمَا عَلَيْهِمْ مَا حُمِّلُوا وَعَلَيْكُمْ مَا حُمِّلْتُمْ. وَفِي رِوَايَةٍ قَالَ: فَجَذَبَهُ الْأَشْعَثُ بْنُ قَيْسٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْمَعُوا وَأَطِيعُوا، فَإِنَّمَا عَلَيْهِمْ مَا حُمِّلُوا وَعَلَيْكُمْ مَا حُمِّلْتُمْ". (م)', 'വാഇലുൽ ഹള്റമീ(റ): സലമതുബ്നു യസീദിൽ ജുഅ്ഫീ(റ) റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, തങ്ങളുടെ അവകാശങ്ങൾ ചോദിച്ചു വാങ്ങുകയും ഞങ്ങളുടെ അവകാശങ്ങൾ തടയുകയും ചെയ്യുന്ന നേതാക്കൾ ഞങ്ങളിലുണ്ടായാൽ ഞങ്ങളെന്തു ചെയ്യണമെന്നാണ് അവിടുന്ന് കൽപിക്കുന്നത്? അപ്പോൾ അവിടുന്ന് അദ്ദേഹത്തിൽനിന്ന് തിരിഞ്ഞുകളഞ്ഞു. അദ്ദേഹം പിന്നെയും ചോദിച്ചു: അപ്പോഴും തിരുമേനി(സ) തിരിഞ്ഞുകളഞ്ഞു. പിന്നെയുമദ്ദേഹം രണ്ടോ മൂന്നോ പ്രാവശ്യം ചോദിച്ചു. അപ്പോൾ അശ്അസുബ്നു ഖൈസ്(റ) അദ്ദേഹത്തെ പിടിച്ചു വലിച്ചുകൊണ്ട് പറഞ്ഞു: നിങ്ങൾ അദ്ദേഹത്തെ അനുസരിക്കുകയും വഴിപ്പെടുകയും ചെയ്യുക. നിശ്ചയം അവർ ഏൽപിക്കപ്പെട്ട ഉത്തരവാദിത്തം നിറവേറ്റൽ അവർക്കും, നിങ്ങൾ ഏൽപിക്കപ്പെട്ട ഉത്തരവാദിത്തം നിറവേറ്റൽ നിങ്ങൾക്കും നിർബന്ധമാണ്. മറ്റൊരു നിവേദനം: അപ്പോൾ അശ്അസുബ്നു ഖൈസ്(റ) അദ്ദേഹത്തെ പിടിച്ചു വലിച്ചു. അന്നേരം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളദ്ദേഹത്തെ അനുസരിക്കുകയും കേൾക്കുകയും ചെയ്യുക. നിശ്ചയം അവർ ഏൽപിക്കപ്പെട്ട ഉത്തരവാദിത്തം നിറവേറ്റൽ അവർക്കും, നിങ്ങൾ ഏൽപിക്കപ്പെട്ട ഉത്തരവാദിത്തം നിറവേറ്റൽ നിങ്ങൾക്കും നിർബന്ധമാണ്." (മു)', 'وَائِلٍ الْحَضْرَمِيِّ قَالَ', 'വാഇലുൽ ഹള്റമീ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=44), 1, 'وَفِي رِوَايَةٍ قَالَ: فَجَذَبَهُ الْأَشْعَثُ بْنُ قَيْسٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْمَعُوا وَأَطِيعُوا، فَإِنَّمَا عَلَيْهِمْ مَا حُمِّلُوا وَعَلَيْكُمْ مَا حُمِّلْتُمْ". (م)', 'മറ്റൊരു നിവേദനം: അപ്പോൾ അശ്അസുബ്നു ഖൈസ്(റ) അദ്ദേഹത്തെ പിടിച്ചു വലിച്ചു. അന്നേരം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളദ്ദേഹത്തെ അനുസരിക്കുകയും കേൾക്കുകയും ചെയ്യുക. നിശ്ചയം അവർ ഏൽപിക്കപ്പെട്ട ഉത്തരവാദിത്തം നിറവേറ്റൽ അവർക്കും, നിങ്ങൾ ഏൽപിക്കപ്പെട്ട ഉത്തരവാദിത്തം നിറവേറ്റൽ നിങ്ങൾക്കും നിർബന്ധമാണ്." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْغَزْوُ غَزْوَانِ: فَأَمَّا مَنِ ابْتَغَى وَجْهَ اللَّهِ، وَأَطَاعَ الْإِمَامَ، وَأَنْفَقَ الْكَرِيمَةَ، وَاجْتَنَبَ الْفَسَادَ، فَإِنَّ نَوْمَهُ وَنُبْهَتَهُ أَجْرٌ كُلُّهُ. وَأَمَّا مَنْ غَزَا رِيَاءً وَسُمْعَةً، وَعَصَى الْإِمَامَ، وَأَفْسَدَ فِي الْأَرْضِ، فَإِنَّهُ لَا يَرْجِعُ بِالْكَفَافِ". (د,ن)', 'മുആദുബ്നു ജബൽ(റ): റസൂൽ(സ) പറഞ്ഞു: "യുദ്ധം രണ്ടു വിധമാണ്: അല്ലാഹുവിന്റെ തൃപ്തി ആഗ്രഹിച്ച്, ഇമാമിനെ അനുസരിച്ച്, ഏറ്റവും പ്രിയപ്പെട്ടതിനെ ചെലവഴിച്ച്, അക്രമങ്ങൾ ഉപേക്ഷിച്ച് യുദ്ധം ചെയ്യുന്നവന്റെ ഉറക്കവും ഉണർച്ചയും മുഴുവൻ അവന് കൂലിയാണ്. അഹന്തയ്ക്കും പ്രശസ്തിക്കും വേണ്ടി, നേതാവിനെ അനുസരിക്കാതെ, ഭൂമിയിൽ ഫസാദുണ്ടാക്കിക്കൊണ്ട് യുദ്ധം ചെയ്യുന്നവൻ കൂലി മതിയായിക്കൊണ്ട് മടങ്ങുകയില്ല." (ദ,ന)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 135, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَنْ خَرَجَ مِنَ الطَّاعَةِ وَفَارَقَ الْجَمَاعَةَ، فَمَاتَ مَاتَ مِيتَةً جَاهِلِيَّةً. وَمَنْ قَاتَلَ تَحْتَ رَايَةٍ عِمِّيَّةٍ يَغْضَبُ لِعَصَبَةٍ، أَوْ يَدْعُو إِلَى عَصَبَةٍ، أَوْ يَنْصُرُ عَصَبَةً، فَقُتِلَ فَقِتْلَةٌ جَاهِلِيَّةٌ. وَمَنْ خَرَجَ عَلَى أُمَّتِي يَضْرِبُ بَرَّهَا وَفَاجِرَهَا، وَلَا يَتَحَاشَى مِنْ مُؤْمِنِهَا، وَلَا يَفِي لِذِي عَهْدٍ عَهْدَهُ، فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അനുസരണയിൽനിന്ന് പുറത്തുകടക്കുകയും സംഘത്തിൽനിന്ന് വിട്ടുനിൽക്കുകയും ചെയ്ത് മരണം വരിച്ചവൻ ജാഹിലിയ്യാ (അജ്ഞാന കാലത്തേതിനു സമമായ) മരണം മരിച്ചിരിക്കുന്നു. ഒരു വിഭാഗത്തിനു വേണ്ടി പക്ഷപാതിത്വത്തോടെ ദേഷ്യപ്പെട്ടുകൊണ്ടോ, അല്ലെങ്കിൽ ഒരു വിഭാഗത്തിലേക്ക് ക്ഷണിച്ചുകൊണ്ടോ, അല്ലെങ്കിൽ ഒരു വിഭാഗത്തെ സഹായിക്കാൻ വേണ്ടിയോ ഒരാൾ അഹങ്കാരത്തിന്റെ കൊടിക്കു കീഴിൽ യുദ്ധം ചെയ്ത് കൊല ചെയ്യപ്പെട്ടാൽ ജാഹിലിയ്യാ കാലത്തെ കൊലയാണത്. കരാർ ചെയ്തവരുടെ കരാർ പൂർത്തീകരിക്കുകയോ, സത്യവിശ്വാസികളെ മാറ്റിനിർത്തുകയോ ചെയ്യാതെ, എന്റെ സമുദായത്തിലെ നല്ലവരെയും മോശപ്പെട്ടവരെയുമെല്ലാം അക്രമിച്ചുകൊണ്ട് പുറപ്പെട്ടവൻ എന്നിൽ പെട്ടവനല്ല, ഞാൻ അവനിൽ പെട്ടവനുമല്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ نَافِعٍ قَالَ: جَاءَ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا إِلَى عَبْدِ اللَّهِ بْنِ مُطِيعٍ حِينَ كَانَ مِنْ أَمْرِ الْحَرَّةِ مَا كَانَ، زَمَنَ يَزِيدَ بْنِ مُعَاوِيَةَ، فَقَالَ: اطْرَحُوا لِأَبِي عَبْدِ الرَّحْمَنِ وِسَادَةً. فَقَالَ: إِنِّي لَمْ آتِكَ لِأَجْلِسَ، أَتَيْتُكَ لِأُحَدِّثَكَ حَدِيثًا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُهُ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ خَلَعَ يَدًا مِنْ طَاعَةٍ لَقِيَ اللَّهَ يَوْمَ الْقِيَامَةِ لَا حُجَّةَ لَهُ، وَمَنْ مَاتَ وَلَيْسَ فِي عُنُقِهِ بَيْعَةٌ مَاتَ مِيتَةً جَاهِلِيَّةً". (م)', 'നാഫിഅ്(റ): യസീദുബ്നു മുആവിയയുടെ കാലത്ത്, ഹർറയിലെ സംഭവ വികാസങ്ങളുണ്ടായ സമയത്ത്, അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) അബ്ദുല്ലാഹിബ്നു മുത്വീഇന്റെ അടുക്കൽ വന്നു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: അബൂഅബ്ദുർറഹ്മാന് നിങ്ങൾ തലയിണയിട്ടു കൊടുക്കുക. അപ്പോഴദ്ദേഹം പറഞ്ഞു: ഇരിക്കാൻ വേണ്ടിയല്ല ഞാൻ നിങ്ങളുടെ അടുക്കൽ വന്നിരിക്കുന്നത്. റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ട ഒരു ഹദീസ് നിങ്ങൾക്ക് പറഞ്ഞുതരാൻ വേണ്ടിയാണ് ഞാൻ നിങ്ങളുടെ അടുക്കൽ വന്നിരിക്കുന്നത്. റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അനുസരണയിൽനിന്ന് ആരെങ്കിലും തന്റെ കൈ ഊരിയാൽ, (തന്റെ പക്കൽ) ന്യായമില്ലാത്തവനായി അവൻ അല്ലാഹുവിനെ കണ്ടുമുട്ടും. പിരടിയിൽ ഉടമ്പടിയില്ലാത്തവനായി ഒരാൾ മരിച്ചാൽ അവൻ ജാഹിലിയ്യാ മരണമാണ് മരിച്ചിരിക്കുന്നത്." (മു)', 'نَافِعٍ قَالَ', 'നാഫിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقَدْ أَتَانِي الْيَوْمَ رَجُلٌ فَسَأَلَنِي عَنْ أَمْرٍ مَا دَرَيْتُ مَا أَرُدُّ عَلَيْهِ، فَقَالَ: أَرَأَيْتَ رَجُلًا مُؤْدِيًا نَشِيطًا يَخْرُجُ مَعَ أُمَرَائِنَا فِي الْمَغَازِي، فَيَعْزِمُ عَلَيْنَا فِي أَشْيَاءَ لَا نُحْصِيهَا، فَقُلْتُ لَهُ: وَاللَّهِ مَا أَدْرِي مَا أَقُولُ لَكَ، إِلَّا أَنَّا كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَسَى أَنْ لَا يَعْزِمَ عَلَيْنَا فِي أَمْرٍ إِلَّا مَرَّةً حَتَّى نَفْعَلَهُ، وَإِنَّ أَحَدَكُمْ لَنْ يَزَالَ بخير مَا اتَّقَى اللَّهَ، وَإِذَا شَكَّ فِي نَفْسِهِ شَيْءٌ سَأَلَ رَجُلًا فَشَفَاهُ مِنْهُ، وَأَوْشَكَ أَنْ لَا تَجِدُوهُ، وَالَّذِي لَا إِلَهَ إِلَّا هُوَ مَا أَذْكُرُ مَا غَبَرَ مِنَ الدُّنْيَا إِلَّا كَالثَّغْبِ، شُرِبَ صَفْوُهُ، وَبَقِيَ كَدْرُهُ. (خ)', 'അബ്ദുല്ല(റ): ഇന്ന് ഒരാൾ എന്നെ സമീപിച്ച് ഒരു കാര്യത്തെക്കുറിച്ച് ചോദിച്ചു. എന്താണ് മറുപടി പറയുകയെന്ന് എനിക്ക് നിശ്ചയമുണ്ടായിരുന്നില്ല. അയാൾ ചോദിച്ചു: ശക്തനും ഉന്മേഷവാനുമായ ഒരു പടയാളി നമ്മുടെ നേതാക്കളോടൊപ്പം യുദ്ധത്തിന് പുറപ്പെടുന്നു. നമുക്ക് കഴിയാത്ത കാര്യങ്ങൾ അവൻ നമ്മോട് കൽപിക്കുന്നു. അതിനെക്കുറിച്ച് താങ്കളുടെ അഭിപ്രായമെന്ത്? ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണെ, ഞാനെന്താണ് പറയേണ്ടതെന്ന് എനിക്കറിയില്ല. പക്ഷേ; ഞങ്ങൾ നബി(സ)യുടെ കൂടെ ആയിരുന്നപ്പോൾ ഒരു പ്രാവശ്യത്തിൽ കൂടുതലായി ഒരു കാര്യം ഞങ്ങളോട് അവിടുന്ന് കൽപിക്കാറുണ്ടായിരുന്നില്ല, അപ്പോഴേക്ക് ഞങ്ങളത് നിർവ്വഹിച്ചിരിക്കും. അല്ലാഹുവിനെ സൂക്ഷിച്ചു കൊണ്ടിരിക്കുന്ന കാലമത്രയും നിങ്ങളിലോരോരുത്തരും നന്മയിലായിരിക്കും. വല്ലവരുടെയും മനസ്സിൽ വല്ല സംശയവും തോന്നിയാൽ മറ്റൊരാളോട് ചോദിച്ച് സംശയം ദൂരീകരിച്ചുകൊള്ളുക. പക്ഷേ, അത്തരം ഒരാളെ നിങ്ങൾക്ക് കിട്ടാൻ പ്രയാസമായ കാലം അടുത്തിരിക്കുന്നു. അല്ലാഹുവാണെ, അവനല്ലാതെ ആരാധ്യനില്ല, മലഞ്ചെരുവിലെ കലക്കുവെള്ളം നിറഞ്ഞ ജലാശയം പോലെയാണ് ദുൻയാവിലെ ശേഷിച്ച കാലത്തെ ഞാൻ കാണുന്നത്. അതിൽനിന്ന് തെളിഞ്ഞതെല്ലാം കുടിച്ചുകഴിഞ്ഞു, കലങ്ങിയത് ബാക്കിയാവുകയും ചെയ്തു. (ബു)', 'عَبْدِ اللَّهِ', 'അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 136, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ جَيْشًا وَأَمَّرَ عَلَيْهِمْ رَجُلًا، وَأَمَرَهُمْ أَنْ يَسْمَعُوا لَهُ وَيُطِيعُوا. فَأَجَّجَ نَارًا وَأَمَرَهُمْ أَنْ يَقْتَحِمُوا فِيهَا، فَأَبَى قَوْمٌ أَنْ يَدْخُلُوهَا وَقَالُوا: إِنَّمَا فَرَرْنَا مِنَ النَّارِ، وَأَرَادَ قَوْمٌ أَنْ يَدْخُلُوهَا، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَوْ دَخَلُوهَا – أَوْ دَخَلُوا فِيهَا – لَمْ يَزَالُوا فِيهَا". وَقَالَ: "لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ". (ق,د,ن)', 'അലി(റ): റസൂൽ(സ) ഒരു സൈന്യത്തെ അയക്കുകയും ഒരു വ്യക്തിയെ അവർക്ക് നേതാവായി നിശ്ചയിക്കുകയും ചെയ്തു. അദ്ദേഹം പറയുന്നത് കേൾക്കുകയും അനുസരിക്കുകയും ചെയ്യണമെന്ന് റസൂൽ(സ) അവരോട് കൽപിച്ചു. അങ്ങനെ അദ്ദേഹം തീ കത്തിക്കുകയും അതിലേക്ക് എടുത്ത്ചാടാൻ അവരോട് ആജ്ഞാപിക്കുകയും ചെയ്തു. ചിലർ അതിൽ പ്രവേശിക്കാൻ വിസമ്മതിച്ചു. അവർ പറഞ്ഞു: ഞങ്ങൾ നരകത്തീയിൽ നിന്നാണ് ഓടിയകലുന്നത്. ചിലർ അതിൽ പ്രവേശിക്കാനുദ്ദേശിച്ചു. ഈ വിവരം നബി(സ)യുടെ അടുത്തെത്തിയപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അവർ അതിൽ പ്രവേശിക്കുകയായിരുന്നെങ്കിൽ അവർ എന്നെന്നും അതിൽ (നരകത്തിൽ) നിലകൊള്ളുമായിരുന്നു." ശേഷം പറഞ്ഞു: "അല്ലാഹുവിന് എതിര് ചെയ്യുന്ന കാര്യത്തിൽ അനുസരണയില്ല, നന്മയിൽ മാത്രമാണ് അനുസരിക്കേണ്ടത്." (ബു,മു,ദ,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 137, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "السَّمْعُ وَالطَّاعَةُ عَلَى الْمَرْءِ الْمُسْلِمِ فِيمَا أَحَبَّ وَكَرِهَ، مَا لَمْ يُؤْمَرْ بِمَعْصِيَةٍ، فَإِنْ أُمِرَ بِمَعْصِيَةٍ فَلَا سَمْعَ عَلَيْهِ وَلَا طَاعَةَ". حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "തിന്മ കൊണ്ട് കൽപിക്കപ്പെടാത്തിടത്തോളം താൻ ഇഷ്ടപ്പെടുന്നതിലും വെറുക്കുന്നതിലും മുസ്ലിമായ മനുഷ്യൻ അനുസരണയുള്ളവനാവണം. തിന്മ കൊണ്ട് കൽപിക്കപ്പെട്ടാൽ അവൻ വഴിപ്പെടുകയോ അനുസരിക്കുകയോ ചെയ്യരുത്." (ബു,മു,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 137, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ عَلْقَمَةَ بْنَ مُجَزِّزٍ عَلَى بَعْثٍ وَأَنَا فِيهِمْ، فَلَمَّا انْتَهَى إِلَى رَأْسِ غَزَاتِهِ – أَوْ: كَانَ بِبَعْضِ الطَّرِيقِ – اسْتَأْذَنَتْهُ طَائِفَةٌ مِنَ الْجَيْشِ، فَأَذِنَ لَهُمْ وَأَمَّرَ عَلَيْهِمْ عَبْدَ اللَّهِ بْنَ حُذَافَةَ بْنِ قَيْسٍ السَّهْمِيَّ، فَكُنْتُ فِيمَنْ غَزَا مَعَهُ، فَلَمَّا كَانَ بِبَعْضِ الطَّرِيقِ أَوْقَدَ الْقَوْمُ نَارًا لِيَصْطَلُوا أَوْ لِيَصْنَعُوا عَلَيْهَا صَنِيعًا. فَقَالَ عَبْدُ اللَّهِ، وَكَانَتْ فِيهِ دُعَابَةٌ: أَلَيْسَ لِي عَلَيْكُمُ السَّمْعُ وَالطَّاعَةُ؟ قَالُوا: بَلَى. قَالَ: فَمَا أَنَا بِآمِرِكُمْ بِشَيْءٍ إِلَّا صَنَعْتُمُوهُ؟ قَالُوا: نَعَمْ. قَالَ: فَإِنِّي أَعْزِمُ عَلَيْكُمْ إِلَّا تَوَاثَبْتُمْ فِي هَذِهِ النَّارِ. فَقَامَ نَاسٌ فَتَحَجَّزُوا، فَلَمَّا ظَنَّ أَنَّهُمْ وَاثِبُونَ قَالَ: أَمْسِكُوا عَلَى أَنْفُسِكُمْ، فَإِنَّمَا كُنْتُ أَمْزَحُ مَعَكُمْ. فَلَمَّا قَدِمْنَا ذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَمَرَكُمْ مِنْهُمْ بِمَعْصِيَةِ اللَّهِ فَلَا تُطِيعُوهُ". (ن,جه)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ): റസൂൽ(സ) അൽഖമതുബ്നു മുജസ്സിർ(റ)വിനെ ഒരു സംഘത്തിന്റെ നേതാവാക്കി പറഞ്ഞയച്ചു. ഞാനും അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. അങ്ങനെ ലക്ഷ്യസ്ഥാനത്തെത്തിയപ്പോൾ - അല്ലെങ്കിൽ വഴിയിൽ വെച്ച് - സൈന്യത്തിലെ ചിലർ അൽഖമതുബ്നു മുജസ്സിർ(റ)വിനോട് (മറ്റൊരു വഴിയിലൂടെ നീങ്ങാൻ) സമ്മതം ചോദിക്കുകയും അദ്ദേഹം അവർക്ക് സമ്മതം നൽകുകയും അബ്ദുല്ലാഹിബ്നു ഹുദാഫ(റ)വിനെ അദ്ദേഹം അവരുടെ നേതാവാക്കുകയും ചെയ്തു. ഞാനും അബ്ദുല്ല(റ)വിന്റെ കൂടെ യുദ്ധം ചെയ്തവരുടെ കൂട്ടത്തിലായിരുന്നു. വഴിയിൽ വെച്ച് തീ കായാൻ വേണ്ടിയോ പാചകംചെയ്യാൻ വേണ്ടിയോ ജനങ്ങൾ തീ കത്തിച്ചു. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു - അബ്ദുല്ല(റ) തമാശ പറയാറുണ്ടായിരുന്നു - എന്നെ അനുസരിക്കൽ നിങ്ങൾക്ക് നിർബന്ധമല്ലേ? അവർ പറഞ്ഞു: അതെ. അബ്ദുല്ല(റ) പറഞ്ഞു: ഞാൻ കൽപിക്കുന്നതെല്ലാം നിങ്ങൾ ചെയ്യില്ലേ? അവർ പറഞ്ഞു: അതെ. അബ്ദുല്ല(റ) പറഞ്ഞു: നിങ്ങൾ ഈ തീയിലേക്ക് എടുത്തുചാടണമെന്ന് ഞാൻ കൽപിക്കുന്നു. അപ്പോൾ ചിലർ എഴുന്നേറ്റ് ചാടാൻ ഒരുങ്ങി. അവർ ചാടുമെന്ന് അബ്ദുല്ല(റ)വിന് തോന്നിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ ചാടരുത്. ഞാൻ തമാശ പറയുകയായിരുന്നു. ഞങ്ങൾ തിരിച്ചെത്തിയപ്പോൾ അവർ അത് നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവരിലാരെങ്കിലും നിങ്ങളോട് തിന്മ കൽപിച്ചാൽ നിങ്ങൾ അനുസരിക്കരുത്." (ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 138, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَيَلِي أُمُورَكُمْ بَعْدِي رِجَالٌ يُطْفِئُونَ السُّنَّةَ وَيَعْمَلُونَ بِالْبِدْعَةِ، وَيُؤَخِّرُونَ الصَّلَاةَ عَنْ مَوَاقِيتِهَا". فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنْ أَدْرَكْتُهُمْ كَيْفَ أَفْعَلُ؟ قَالَ: "تَسْأَلُنِي يَا ابْنَ أُمِّ عَبْدٍ كَيْفَ تَفْعَلُ؟ لَا طَاعَةَ لِمَنْ عَصَى اللَّهَ". (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെ ചര്യയെ കെടുത്തുകയും (ഒഴിവാക്കുകയും) പുത്തൻകാര്യങ്ങൾ കൊണ്ടുവരികയും ചെയ്യുന്ന ചിലർ എനിക്കുശേഷം നിങ്ങളുടെ നേതാക്കളായി വരും. നമസ്കാരങ്ങളെ അവർ അതിന്റെ സമയത്തെതൊട്ട് പിന്തിക്കും." ഞാൻ ചോദിച്ചു: റസൂലേ, അവരുടെ കാലത്ത് ഞാനുണ്ടെങ്കിൽ എന്താണ് ചെയ്യേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "ഇബ്നു ഉമ്മുഅബ്ദേ, എന്താണ് ചെയ്യേണ്ടതെന്നാണോ നീ ചോദിക്കുന്നത്? അല്ലാഹുവിനെ ധിക്കരിക്കുന്നവനെ അനുസരിക്കരുത്." (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 138, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ جَيْشًا وَأَمَّرَ عَلَيْهِمْ رَجُلًا، فَأَوْقَدَ نَارًا. فَقَالَ: ادْخُلُوهَا. فَأَرَادَ نَاسٌ أَنْ يَدْخُلُوهَا، وَقَالَ الْآخَرُونَ: إِنَّا قَدْ فَرَرْنَا مِنْهَا. فَذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِلَّذِينَ أَرَادُوا أَنْ يَدْخُلُوهَا: "لَوْ دَخَلْتُمُوهَا لَمْ تَزَالُوا فِيهَا إِلَى يَوْمِ الْقِيَامَةِ". وَقَالَ لِلْآخَرِينَ قَوْلًا حَسَنًا، وَقَالَ: "لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ". (م,ن)', 'അലി(റ): നിശ്ചയം റസൂൽ(സ) ഒരു സൈന്യത്തെ അയക്കുകയും ഒരാളെ അവരുടെ നേതാവാക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം തീ കത്തിച്ചുകൊണ്ട് പറഞ്ഞു: നിങ്ങളതിൽ പ്രവേശിക്കുക. അപ്പോൾ ചിലയാളുകൾ തീയിൽ പ്രവേശിക്കാനുദ്ദേശിക്കുകയും, മറ്റുള്ളവർ, ഞങ്ങൾ അതിൽനിന്ന് (നരകത്തിൽനിന്ന്) പേടിച്ചാണ് ഓടുന്നതെന്ന് പറയുകയും ചെയ്തു. അങ്ങനെ ഇക്കാര്യം റസൂൽ(സ)യോട് പറയപ്പെട്ടു. അപ്പോൾ തീയിൽ പ്രവേശിക്കാനുദ്ദേശിച്ചവരോട് അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളതിൽ പ്രവേശിച്ചിരുന്നെങ്കിൽ അന്ത്യനാൾവരെ നിങ്ങളതിൽതന്നെ ആകുമായിരുന്നു." മറ്റുള്ളവരോട് അവിടുന്ന് നല്ലവാക്ക് പറയുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "അല്ലാഹുവിനെ ധിക്കരിക്കുന്നതിൽ അനുസരണയരുത്. നിശ്ചയം നന്മയിൽ മാത്രമാണ് അനുസരണ വേണ്ടത്." (മു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 138, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ جُنَادَةَ بْنِ أَبِي أُمَيَّةَ قَالَ: دَخَلْنَا عَلَى عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ وَهُوَ مَرِيضٌ، فَقُلْنَا: حَدِّثْنَا – أَصْلَحَكَ اللَّهُ – بِحَدِيثٍ يَنْفَعُ اللَّهُ بِهِ، سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: دَعَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْنَاهُ، فَكَانَ فِيمَا أَخَذَ عَلَيْنَا: أَنْ بَايَعَنَا عَلَى السَّمْعِ وَالطَّاعَةِ، فِي مَنْشَطِنَا وَمَكْرَهِنَا وَعُسْرِنَا وَيُسْرِنَا، وَأَثَرَةً عَلَيْنَا، وَأَنْ لَا نُنَازِعَ الْأَمْرَ أَهْلَهُ. قَالَ: "إِلَّا أَنْ تَرَوْا كُفْرًا بَوَاحًا، عِنْدَكُمْ مِنَ اللَّهِ فِيهِ بُرْهَانٌ". (ق)', 'ജുനാദതുബ്നു അബീഉമയ്യ(റ): ഉബാദതുബ്നു സ്വാമിത്(റ) രോഗിയായിരിക്കെ ഞങ്ങളദ്ദേഹത്തിന്റെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹു ഞങ്ങൾക്ക് ഉപകാരം നൽകാൻ കാരണമാകുന്ന, റസൂൽ(സ)യിൽനിന്ന് താങ്കൾ കേട്ട ഒരു ഹദീസ് ഞങ്ങൾക്ക് പറഞ്ഞു തന്നാലും - അല്ലാഹു നിങ്ങൾക്ക് നന്മ വരുത്തട്ടെ - അപ്പോഴദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഞങ്ങളെ വിളിക്കുകയും ഞങ്ങളവിടുത്തോട് ഉടമ്പടി ചെയ്യുകയും ചെയ്തു. അന്നേരമവിടുന്ന് ഞങ്ങളോട് ചെയ്ത ഉടമ്പടിയിൽ പെട്ടതിവയാണ്: ഞങ്ങൾക്ക് ഇഷ്ടപ്പെടുന്നതിലും ഇഷ്ടപ്പെടാത്തതിലും പ്രയാസമുള്ളതിലും പ്രയാസമില്ലാത്തതിലും അനുസരണയും കേൾവിയും വേണമെന്നും, സ്വന്തത്തേക്കാൾ മറ്റുള്ളവർക്ക് മുൻഗണന നൽകണമെന്നും, അധികാരത്തിന്റെ വിഷയത്തിൽ അതിന്റെ ആളുകളോട് തർക്കിക്കരുതെന്നും അവിടുന്ന് ഞങ്ങളോട് ഉടമ്പടി ചെയ്തു. അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളുടെ പക്കൽ അല്ലാഹുവിൽ നിന്നുള്ള തെളിവുള്ള വ്യക്തമായ കുഫ്റ് (സത്യനിഷേധം) നിങ്ങൾ കണ്ടാലൊഴികെ." (ബു,മു)', 'جُنَادَةَ بْنِ أَبِي أُمَيَّةَ قَالَ', 'ജുനാദതുബ്നു അബീഉമയ്യ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 139, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ تِسْعَةٌ، خَمْسَةٌ وَأَرْبَعَةٌ، أَحَدُ الْعَدَدَيْنِ مِنَ الْعَرَبِ وَالْآخَرُ مِنَ الْعَجَمِ، فَقَالَ: "اسْمَعُوا، هَلْ سَمِعْتُمْ أَنَّهُ سَتَكُونُ بَعْدِي أُمَرَاءُ، مَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِكَذِبِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ، وَلَيْسَ يَرِدُ عَلَيَّ الْحَوْضَ. وَمَنْ لَمْ يَدْخُلْ عَلَيْهِمْ وَلَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ، وَسَيَرِدُ عَلَيَّ الْحَوْضَ". (ن)', 'കഅ്ബുബ്നു ഉജ്റ(റ): റസൂൽ(സ) ഞങ്ങളുടെ അടുത്തേക്ക് വന്നു. ഞങ്ങൾ ഒമ്പതു പേരായിരുന്നു. അഞ്ചും നാലും, ആദ്യത്തേത് അറബികളുടെയും രണ്ടാമത്തേത് അനറബികളുടേയും എണ്ണമാണ്. അങ്ങനെ അവിടുന്ന് പറഞ്ഞു: "നിങ്ങൾ കേൾക്കുവീൻ, എനിക്കുശേഷം ധാരാളം അമീറുമാരുണ്ടാകുമെന്ന് നിങ്ങൾ കേട്ടിട്ടുണ്ടോ, ഒരാൾ അവരുടെ അടുക്കൽ ചെല്ലുകയും അവരുടെ നുണകളെ സത്യമാക്കുകയും അക്രമത്തിന് അവരെ സഹായിക്കുകയും ചെയ്താൽ, അവനെന്നിൽ പെട്ടവനല്ല, ഞാൻ അവനിൽ പെട്ടവനുമല്ല. ഹൗളുൽ കൗസറിനായി അവൻ എന്റെയടുക്കൽ വരുന്നതുമല്ല. അവരുടെ അടുക്കൽ പോവുകയോ അവരുടെ നുണകൾ സത്യമാക്കുകയോ അക്രമത്തിന് അവരെ സഹായിക്കുകയോ ചെയ്യാത്തവൻ എന്നിൽ പെട്ടവനാണ്. ഞാൻ അവനിൽ പെട്ടവനുമാണ്. ഹൗളുൽ കൗസറിനായി അവൻ എന്റെയടുക്കൽ വരുന്നതുമാണ്." (ന)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്നു ഉജ്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 139, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "إِنَّهُ يُسْتَعْمَلُ عَلَيْكُمْ أُمَرَاءُ، فَتَعْرِفُونَ وَتُنْكِرُونَ، فَمَنْ كَرِهَ فَقَدْ بَرِئَ، وَمَنْ أَنْكَرَ فَقَدْ سَلِمَ، وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ". قَالُوا: يَا رَسُولَ اللَّهِ، أَلَا نُقَاتِلُهُمْ؟ قَالَ: "لَا، مَا صَلَّوْا". أَيْ مَنْ كَرِهَ بِقَلْبِهِ وَأَنْكَرَ بِقَلْبِهِ. (م)', 'നബി(സ)യുടെ പത്നിയായ ഉമ്മുസലമ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങളുടെ മേൽ ധാരാളം നേതാക്കൾ അധികാരമേൽപിക്കപ്പെടും. അങ്ങനെ നിങ്ങളവരെ മനസ്സിലാക്കുകയും കുറ്റപ്പെടുത്തുകയും ചെയ്യും. നിശ്ചയം (അവരെ) വെറുത്തവൻ മുക്തനായിരിക്കുന്നു. നിശ്ചയം കുറ്റപ്പെടുത്തിയവൻ രക്ഷപ്പെട്ടിരിക്കുന്നു. പക്ഷെ, (അവരെ) ഇഷ്ടപ്പെടുകയും പിൻപറ്റുകയും ചെയ്തവർ (വിജയിക്കില്ല)." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളവരെ വധിച്ചുകളയട്ടെയോ? അവിടുന്ന് പറഞ്ഞു: "അവർ നിസ്കരിക്കുന്ന കാലമത്രയും അത് ചെയ്യരുത്." അതായത് ഹൃദയംകൊണ്ട് വെറുക്കുകയും ഹൃദയംകൊണ്ട് കുറ്റപ്പെടുത്തുകയും ചെയ്തവർ. (മു)', 'أُمِّ سَلَمَةَ', 'നബി(സ)യുടെ പത്നിയായ ഉമ്മുസലമ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَجَعْنَا مِنَ الْعَامِ الْمُقْبِلِ فَمَا اجْتَمَعَ مِنَّا اثْنَانِ عَلَى الشَّجَرَةِ الَّتِي بَايَعْنَا تَحْتَهَا كَانَتْ رَحْمَةً مِنَ اللَّهِ، فَقِيلَ لَهُ: عَلَى أَيِّ شَيْءٍ بَايَعَهُمْ، عَلَى الْمَوْتِ؟ قَالَ: لَا، بَلْ بَايَعَهُمْ عَلَى الصَّبْرِ. (خ)', 'ഇബ്നുഉമർ(റ): രണ്ടാമത്തെ വർഷം ഞങ്ങൾ മടങ്ങിപ്പോന്നു. അല്ലാഹുവിൽ നിന്നുള്ള അനുഗ്രഹമായിട്ട് ഏത് മരത്തിൻ ചുവട്ടിൽ വെച്ചാണോ ഞങ്ങൾ ഉടമ്പടി ചെയ്തത്, ആ മരത്തിന്റെയടുത്ത് പിന്നീട് ഞങ്ങളിൽ നിന്നുള്ള രണ്ടു പേർ ഒരുമിച്ചുകൂടിയിട്ടില്ല. ഇബ്നുഉമർ(റ)വിനോട് ചോദിക്കപ്പെട്ടു: ഏത് വിഷയത്തിലാണ് അവരോട് നബി(സ) ഉടമ്പടി ചെയ്തത്, മരണത്തിന്റെ കാര്യത്തിലാണോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: അല്ല, ക്ഷമയുടെ വിഷയത്തിലാണ് അവരോട് ഉടമ്പടി ചെയ്തത്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَبْدِاللَّهِ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ زَمَنُ الْحَرَّةِ أَتَاهُ آتٍ فَقَالَ لَهُ: إِنَّ ابْنَ حَنْظَلَةَ يُبَايِعُ النَّاسَ عَلَى الْمَوْتِ؟ فَقَالَ: لَا أُبَايِعُ عَلَى هَذَا أَحَدًا بَعْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ): ഹർറയുടെ കാലം ആയപ്പോൾ അബ്ദുല്ല(റ)വിന്റെ സമീപം ഒരാൾ വന്നുകൊണ്ട് പറഞ്ഞു: ഇബ്നുഹൻളല(റ) മരണവിഷയത്തിൽ ജനങ്ങളോട് ഉടമ്പടി ചെയ്യുന്നുണ്ടല്ലോ? അബ്ദുല്ല(റ) പറഞ്ഞു: റസൂൽ(സ)ക്ക് ശേഷം ഈ വിഷയത്തിൽ ഞാൻ ഒരാളോടും ഉടമ്പടി ചെയ്യുകയില്ല. (ബു)', 'عَبْدِاللَّهِ بْنِ زَيْدٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ عَدَلْتُ إِلَى ظِلِّ الشَّجَرَةِ، فَلَمَّا خَفَّ النَّاسُ قَالَ: "يَا ابْنَ الْأَكْوَعِ أَلَا تُبَايِعُ؟" قَالَ: قُلْتُ: قَدْ بَايَعْتُ يَا رَسُولَ اللَّهِ، قَالَ: "وَأَيْضًا". فَبَايَعْتُهُ الثَّانِيَةَ، فَقُلْتُ لَهُ: يَا أَبَا مُسْلِمٍ عَلَى أَيِّ شَيْءٍ كُنْتُمْ تُبَايِعُونَ يَوْمَئِذٍ؟ قَالَ: عَلَى الْمَوْتِ. (خ)', 'സലമതുബ്നുൽ അക്വഅ്(റ): ഞാൻ നബി(സ)യോട് ഉടമ്പടി ചെയ്ത് ഒരു മരത്തണലിലേക്ക് മാറിനിന്നു. ജനങ്ങൾ അടങ്ങിയപ്പോൾ നബി(സ) ചോദിച്ചു: "ഇബ്നുൽ അക്വഅേ, നീ ഉടമ്പടി ചെയ്യുന്നില്ലേ?" ഞാൻ പറഞ്ഞു: റസൂലേ, ഞാൻ ഉടമ്പടി ചെയ്തുവല്ലോ. നബി(സ) പറഞ്ഞു: "വീണ്ടും ഉടമ്പടി ചെയ്യുക." അങ്ങനെ ഞാൻ രണ്ടാം പ്രാവശ്യവും അവിടുത്തോട് ഉടമ്പടി ചെയ്തു. (ഇതു പറഞ്ഞപ്പോൾ) ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: അബൂമുസ്ലിമേ, ഏതു വിഷയത്തിലായിരുന്നു അന്ന് നിങ്ങൾ ഉടമ്പടി ചെയ്തിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: മരണത്തിന്റെ കാര്യത്തിൽ. (ബു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 140, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ مُجَاشِعٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَأَخِي، فَقُلْتُ: بَايِعْنَا عَلَى الْهِجْرَةِ، فَقَالَ: "مَضَتِ الْهِجْرَةُ لِأَهْلِهَا". فَقُلْتُ: عَلَامَ تُبَايِعُنَا؟ قَالَ: "عَلَى الْإِسْلَامِ وَالْجِهَادِ". (خ)', 'മുജാശിഅ്(റ): ഞാനും എന്റെ സഹോദരനും നബി(സ)യുടെ സന്നിധിയിൽ ചെന്നു. ഞാൻ പറഞ്ഞു: ഹിജ്റയുടെ കാര്യത്തിൽ അങ്ങ് ഞങ്ങളോട് ഉടമ്പടി ചെയ്യുക. നബി(സ) പറഞ്ഞു: "ഹിജ്റയുടെ ആളുകൾക്ക് അതിന്റെ സമയം കഴിഞ്ഞിരിക്കുന്നു." ഞാൻ ചോദിച്ചു: ഏത് വിഷയത്തിലാണ് അങ്ങ് ഞങ്ങളോട് ഉടമ്പടി ചെയ്യുന്നത്? നബി(സ) പറഞ്ഞു: "ഇസ്ലാമിന്റെയും ധർമ്മസമരത്തിന്റെയും കാര്യത്തിൽ." (ബു)', 'مُجَاشِعٍ', 'മുജാശിഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، فِي الْعُسْرِ وَالْيُسْرِ، وَالْمَنْشَطِ وَالْمَكْرَهِ، وَالْأَثَرَةِ عَلَيْنَا، وَأَنْ لَا نُنَازِعَ الْأَمْرَ أَهْلَهُ، وَأَنْ نَقُولَ الْحَقَّ حَيْثُمَا كُنَّا، لَا نَخَافُ فِي اللَّهِ لَوْمَةَ لَائِمٍ. (ق,ن,جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): അല്ലാഹുവിന്റെ കാര്യത്തിൽ ഒരാളുടെയും ആക്ഷേപത്തെ ഞങ്ങൾ പേടിക്കുകയില്ല, എവിടെയാണെങ്കിലും ഞങ്ങൾ സത്യം പറയും, കാര്യങ്ങളിൽ അതിന്റെ നടത്തിപ്പുകാരോട് തർക്കിക്കുകയില്ല, വെറുപ്പുണ്ടാകുമ്പോഴും ഉന്മേഷമുണ്ടാകുമ്പോഴും ഞങ്ങൾ കേൾവിയും അനുസരണയും കാണിക്കും, ഞങ്ങളേക്കാൾ മറ്റുള്ളവരെ തെരഞ്ഞെടുക്കും എന്നീ വിഷയങ്ങളിൽ ഞങ്ങൾ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തു. (ബു,മു,ന,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْعَةً أَوْ ثَمَانِيَةً أَوْ تِسْعَةً، فَقَالَ: "أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ". فَبَسَطْنَا أَيْدِيَنَا. فَقَالَ قَائِلٌ: يَا رَسُولَ اللَّهِ، إِنَّا قَدْ بَايَعْنَاكَ، فَعَلَامَ نُبَايِعُكَ؟ فَقَالَ: "أَنْ تَعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَتُقِيمُوا الصَّلَوَاتِ الْخَمْسَ، وَتَسْمَعُوا وَتُطِيعُوا، وَلَا تَسْأَلُوا النَّاسَ شَيْئًا". قَالَ: فَلَقَدْ رَأَيْتُ بَعْضَ أُولَئِكَ النَّفَرِ يَسْقُطُ سَوْطُهُ، فَلَا يَسْأَلُ أَحَدًا يُنَاوِلُهُ إِيَّاهُ. (م,د,ن,جه)', 'ഔഫുബ്നു മാലികുൽ അശ്ജഇൗ(റ): ഞങ്ങൾ ഏഴോ എട്ടോ ഒൻപതോ പേർ നബി(സ)യുടെ സമീപം നിൽക്കുകയായിരുന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "നിങ്ങൾ അല്ലാഹുവിന്റെ റസൂലിനോട് ഉടമ്പടി ചെയ്യുന്നില്ലേ?" അപ്പോൾ ഞങ്ങൾ കൈകൾ നീട്ടി. അപ്പോൾ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ അങ്ങയോട് ഉടമ്പടി ചെയ്തിട്ടുണ്ട്. അതുകൊണ്ട് ഏത് വിഷയത്തിലാണ് ഇനി അങ്ങയോട് ഉടമ്പടി ചെയ്യേണ്ടത്? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ ആരാധിക്കും, അവനോട് ഒന്നിനെയും പങ്കുചേർക്കുകയില്ല, അഞ്ച് നിസ്കാരങ്ങളെ നിലനിർത്തും, കേൾക്കുന്നവരും അനുസരണയുള്ളവരുമാകും, ജനങ്ങളോട് ഒന്നും ആവശ്യപ്പെടുകയില്ല എന്നീ വിഷയങ്ങളിൽ." ഔഫുബ്നു മാലിക്(റ) പറഞ്ഞു: അക്കൂട്ടരിൽ ചിലയാളുകളെ ഞാൻ കണ്ടു, തന്റെ ചാട്ടവാർ വീണാൽ പോലും അവർ മറ്റുള്ളവരോട് അത് എടുത്തുതരാൻ ആവശ്യപ്പെടാറുണ്ടായിരുന്നില്ല. (മു,ദ,ന,ജ)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ', 'ഔഫുബ്നു മാലികുൽ അശ്ജഇൗ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، فَقَالَ: "فِيمَا اسْتَطَعْتُمْ". (م,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ)യോട് കേൾവിയുടെയും അനുസരണയുടെയും വിഷയത്തിൽ ഞങ്ങൾ ഉടമ്പടി ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് കഴിയുന്ന കാര്യത്തിൽ." (മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى: إِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ، وَعَلَى فِرَاقِ الْمُشْرِكِ. وَفِي رِوَايَةٍ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُبَايِعُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، ابْسُطْ يَدَكَ حَتَّى أُبَايِعَكَ، وَاشْتَرِطْ عَلَيَّ، فَأَنْتَ أَعْلَمُ. قَالَ: "أُبَايِعُكَ عَلَى أَنْ تَعْبُدَ اللَّهَ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتُنَاصِحَ الْمُسْلِمِينَ، وَتُفَارِقَ الْمُشْرِكِينَ". (م,ن)', 'ജരീർ(റ): നിസ്കാരം നിലനിർത്തൽ, സകാത് കൊടുക്കൽ, എല്ലാ മുസ്ലിംകൾക്കും ഗുണംകാംക്ഷിക്കൽ, ബഹുദൈവ വിശ്വാസിയെ വേർപിരിയൽ എന്നീ കാര്യങ്ങളുടെ മേൽ ഞാൻ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തു. മറ്റൊരു നിവേദനം: നബി(സ) ബൈഅതു ചെയ്തുകൊണ്ടിരിക്കെ ഞാൻ അവിടുത്തെയടുക്കൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് കൈ നിവർത്തിയാലും, ഞാനങ്ങയോട് ഉടമ്പടി ചെയ്യട്ടെ. അവിടുന്നെനിക്ക് നിബന്ധനകൾ വെച്ചാലും, അവിടുന്നാണല്ലോ കൂടുതൽ അറിവുള്ളവർ. അവിടുന്ന് പറഞ്ഞു: "നീ അല്ലാഹുവിനെ ആരാധിക്കണം, നിസ്കാരം നിലനിർത്തണം, സകാത് കൊടുക്കണം, മുസ്ലിംകൾക്ക് ഗുണംകാക്ഷിക്കണം, ബഹുദൈവാരാധകരോട് വിട്ടുനിൽക്കണം എന്നിവയുടെ മേൽ നിന്നോട് ഞാൻ ഉടമ്പടി ചെയ്യുന്നു." (മു,ന)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 141, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=64), 1, 'وَفِي رِوَايَةٍ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُبَايِعُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، ابْسُطْ يَدَكَ حَتَّى أُبَايِعَكَ، وَاشْتَرِطْ عَلَيَّ، فَأَنْتَ أَعْلَمُ. قَالَ: "أُبَايِعُكَ عَلَى أَنْ تَعْبُدَ اللَّهَ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتُنَاصِحَ الْمُسْلِمِينَ، وَتُفَارِقَ الْمُشْرِكِينَ". (م,ن)', 'മറ്റൊരു നിവേദനം: നബി(സ) ബൈഅതു ചെയ്തുകൊണ്ടിരിക്കെ ഞാൻ അവിടുത്തെയടുക്കൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് കൈ നിവർത്തിയാലും, ഞാനങ്ങയോട് ഉടമ്പടി ചെയ്യട്ടെ. അവിടുന്നെനിക്ക് നിബന്ധനകൾ വെച്ചാലും, അവിടുന്നാണല്ലോ കൂടുതൽ അറിവുള്ളവർ. അവിടുന്ന് പറഞ്ഞു: "നീ അല്ലാഹുവിനെ ആരാധിക്കണം, നിസ്കാരം നിലനിർത്തണം, സകാത് കൊടുക്കണം, മുസ്ലിംകൾക്ക് ഗുണംകാക്ഷിക്കണം, ബഹുദൈവാരാധകരോട് വിട്ടുനിൽക്കണം എന്നിവയുടെ മേൽ നിന്നോട് ഞാൻ ഉടമ്പടി ചെയ്യുന്നു." (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَبْدِ اللَّهِ بْنِ هِشَامٍ رَضِيَ اللَّهُ عَنْهُ، وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَذَهَبَتْ بِهِ أُمُّهُ زَيْنَبُ بِنْتُ حُمَيْدٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ بَايِعْهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هُوَ صَغِيرٌ". فَمَسَحَ رَأْسَهُ. (خ,د)', 'അബ്ദുല്ലാഹിബ്നു ഹിശാം(റ): അദ്ദേഹം നബി(സ)യെ കണ്ടുമുട്ടിയിട്ടുണ്ട്. അദ്ദേഹത്തെ തന്റെ ഉമ്മയായ സൈനബുബിൻതു ഹുമൈദ്(റ) നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുപോയി, ഇപ്രകാരം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ഇവനോട് ഉടമ്പടി ചെയ്താലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൻ പ്രായം കുറഞ്ഞവനാണ്." ശേഷം അവിടുന്ന് അദ്ദേഹത്തിന്റെ തല തടവി. (ബു,ദ)', 'عَبْدِ اللَّهِ بْنِ هِشَامٍ', 'അബ്ദുല്ലാഹിബ്നു ഹിശാം(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 142, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ وَحَوْلَهُ عِصَابَةٌ مِنْ أَصْحَابِهِ: "تُبَايِعُونِي عَلَى أَنْ لَا تُشْرِكُوا بِاللَّهِ شَيْئًا، وَلَا تَسْرِقُوا، وَلَا تَزْنُوا، وَلَا تَقْتُلُوا أَوْلَادَكُمْ، وَلَا تَأْتُوا بِبُهْتَانٍ تَفْتَرُونَهُ بَيْنَ أَيْدِيكُمْ وَأَرْجُلِكُمْ، وَلَا تَعْصُونِي فِي مَعْرُوفٍ. فَمَنْ وَفَّى فَأَجْرُهُ عَلَى اللَّهِ، وَمَنْ أَصَابَ مِنْكُمْ شَيْئًا فَعُوقِبَ بِهِ فَهُوَ لَهُ كَفَّارَةٌ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا ثُمَّ سَتَرَهُ اللَّهُ فَأَمْرُهُ إِلَى اللَّهِ: إِنْ شَاءَ عَفَا عَنْهُ، وَإِنْ شَاءَ عَاقَبَهُ". وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا تُبَايِعُونِي عَلَى مَا بَايَعَ عَلَيْهِ النِّسَاءُ؟ أَنْ لَا تُشْرِكُوا بِاللَّهِ...". قُلْنَا: بَلَى يَا رَسُولَ اللَّهِ، فَبَايَعْنَاهُ عَلَى ذَلِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَمَنْ أَصَابَ بَعْدَ ذَلِكَ شَيْئًا فَنَالَتْهُ عُقُوبَةٌ فَهُوَ كَفَّارَةٌ، وَمَنْ لَمْ تَنَلْهُ عُقُوبَةٌ فَأَمْرُهُ إِلَى اللَّهِ: إِنْ شَاءَ غَفَرَ لَهُ وَإِنْ شَاءَ عَاقَبَهُ". (ن)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): ചുറ്റും ഒരുകൂട്ടം സ്വഹാബാക്കളുണ്ടായിരിക്കെ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് ഒന്നിനെയും പങ്കുചേർക്കില്ലെന്നും, മോഷ്ടിക്കില്ലെന്നും, വ്യഭിചരിക്കില്ലെന്നും, നിങ്ങളുടെ സന്താനങ്ങളെ വധിക്കില്ലെന്നും, ഇല്ലാത്തത് കെട്ടിച്ചമച്ചുണ്ടാക്കി പരസ്പരം ദുരാരോപണങ്ങൾ നടത്തുകയില്ലെന്നും, നന്മയിൽ എനിക്ക് എതിര് പ്രവർത്തിക്കുകയില്ലെന്നും നിങ്ങളെന്നോട് ഉടമ്പടി ചെയ്യുക. ഉടമ്പടി പൂർണ്ണമായും പാലിച്ചവർക്കുള്ള പ്രതിഫലം അല്ലാഹുവിങ്കലാണ്. ഇനി ഒരാൾ അവയിൽ നിന്ന് എന്തെങ്കിലും ചെയ്യുകയും അതു കാരണമായി ശിക്ഷിക്കപ്പെടുകയും ചെയ്താൽ അത് അവനുള്ള പ്രായശ്ചിത്തമാണ്. അവയിൽ നിന്ന് ഏതെങ്കിലുമൊന്ന് ഒരാൾ ചെയ്യുകയും അല്ലാഹുവത് മറച്ചുവെക്കുകയും ചെയ്താൽ അവന്റെ കാര്യം അല്ലാഹുവിന്റെ അടുക്കലാണ്: അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവന് മാപ്പ് കൊടുക്കും, അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവനെ ശിക്ഷിക്കും."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=66), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا تُبَايِعُونِي عَلَى مَا بَايَعَ عَلَيْهِ النِّسَاءُ؟ أَنْ لَا تُشْرِكُوا بِاللَّهِ...". قُلْنَا: بَلَى يَا رَسُولَ اللَّهِ، فَبَايَعْنَاهُ عَلَى ذَلِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَمَنْ أَصَابَ بَعْدَ ذَلِكَ شَيْئًا فَنَالَتْهُ عُقُوبَةٌ فَهُوَ كَفَّارَةٌ، وَمَنْ لَمْ تَنَلْهُ عُقُوبَةٌ فَأَمْرُهُ إِلَى اللَّهِ: إِنْ شَاءَ غَفَرَ لَهُ وَإِنْ شَاءَ عَاقَبَهُ". (ن)', 'മറ്റൊരു നിവേദനം: നിശ്ചയം റസൂൽ(സ) ചോദിച്ചു: "സ്ത്രീകൾ ഉടമ്പടി ചെയ്ത കാര്യങ്ങളിൽ നിങ്ങൾ എന്നോട് ഉടമ്പടി ചെയ്യുന്നില്ലെയോ? നിങ്ങൾ അല്ലാഹുവിനോട് ഒന്നിനെയും പങ്കുചേർക്കില്ലെന്നും..." ഞങ്ങൾ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ പ്രവാചകരേ. അങ്ങനെ ഞങ്ങൾ അക്കാര്യങ്ങളിൽ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉടമ്പടിക്കു ശേഷം അതിൽ ഏതെങ്കിലുമൊന്ന് ഒരാൾ ചെയ്യുകയും അയാൾക്ക് ശിക്ഷ ലഭിക്കുകയും .ചെയ്താൽ അത് പ്രായശ്ചിത്തമാണ്. ഇനി ഒരാൾക്ക് ശിക്ഷ ലഭിച്ചില്ലെങ്കിൽ അവന്റെ കാര്യം അല്ലാഹുവിന്റെ പക്കലാണ്: അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവന് പൊറുത്തു കൊടുക്കും, അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവനെ ശിക്ഷിക്കും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، فِي عُسْرِنَا وَيُسْرِنَا، وَمَنْشَطِنَا وَمَكَارِهِنَا، وَعَلَى أَنْ لَا نُنَازِعَ الْأَمْرَ أَهْلَهُ، وَعَلَى أَنْ نَقُولَ بِالْعَدْلِ أَيْنَ كُنَّا، لَا نَخَافُ فِي اللَّهِ لَوْمَةَ لَائِمٍ. (ن)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): ഞങ്ങളുടെ സുഖാവസ്ഥയിലും ക്ലേശാവസ്ഥയിലും, ഉന്മേഷാവസ്ഥയിലും ആപൽഘട്ടങ്ങളിലുമെല്ലാം അനുസരിക്കുകയും കേൾക്കുകയും ചെയ്യുമെന്നും, അധികാരത്തിന്റെ കാര്യത്തിൽ ഭരണാധികാരികളോട് തർക്കിക്കില്ലെന്നും, എവിടെയായിരുന്നാലും നീതിപൂർവ്വം മാത്രം ഞങ്ങൾ സംസാരിക്കുമെന്നും, അല്ലാഹുവിന്റെ വിഷയത്തിൽ ആക്ഷേപകന്റെ ആക്ഷേപം ഞങ്ങൾ ഭയപ്പെടില്ലെന്നും ഞങ്ങൾ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തു. (ന)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، فِي عُسْرِنَا وَيُسْرِنَا، وَمَنْشَطِنَا وَمَكْرَهِنَا، وَأَثَرَةً عَلَيْنَا، وَأَنْ لَا نُنَازِعَ الْأَمْرَ أَهْلَهُ، وَأَنْ نَقُومَ بِالْحَقِّ حَيْثُمَا كَانَ، لَا نَخَافُ فِي اللَّهِ لَوْمَةَ لَائِمٍ. (ن)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): ഞങ്ങളുടെ സുഖാവസ്ഥയിലും ക്ലേശാവസ്ഥയിലും, ഉന്മേഷാവസ്ഥയിലും ആപൽഘട്ടങ്ങളിലും എല്ലാം അനുസരിക്കുകയും കേൾക്കുകയും ചെയ്യുമെന്നും, സ്വന്തത്തേക്കാൾ മറ്റുള്ളവരെ തെരഞ്ഞെടുക്കുമെന്നും, അധികാരത്തിന്റെ കാര്യത്തിൽ അതിന്റെ അവകാശികളോട് തർക്കിക്കില്ലെന്നും, എവിടെയായിരുന്നാലും സത്യത്തോടൊപ്പം നിലകൊള്ളുമെന്നും, അല്ലാഹുവിന്റെ വിഷയത്തിൽ ആക്ഷേപകന്റെ ആക്ഷേപത്തെ ഞങ്ങൾ ഭയപ്പെടില്ലെന്നും റസൂൽ(സ)യോട് ഞങ്ങൾ ഉടമ്പടി ചെയ്തു. (ന)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَيْكَ بِالطَّاعَةِ فِي مَنْشَطِكَ وَمَكْرَهِكَ، وَعُسْرِكَ وَيُسْرِكَ، وَأَثَرَةٍ عَلَيْكَ". (ن)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഉന്മേഷാവസ്ഥയിലും വെറുക്കപ്പെടുന്ന അവസ്ഥയിലും, സുഖാവസ്ഥയിലും ക്ലേശാവസ്ഥയിലും അനുസരിക്കലും, നിന്നെക്കാൾ മറ്റുള്ളവരെ നീ തെരഞ്ഞെടുക്കലും നിനക്ക് നിർബന്ധമാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى النُّصْحِ لِكُلِّ مُسْلِمٍ. وَفِي رِوَايَةٍ: بَايَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، وَأَنْ أَنْصَحَ لِكُلِّ مُسْلِمٍ. (ن)', 'ജരീർ(റ): എല്ലാ മുസ്ലിംകൾക്കും ഗുണംകാംക്ഷിക്കാമെന്ന് റസൂൽ(സ)യോട് ഞാൻ ഉടമ്പടി ചെയ്തു. മറ്റൊരു നിവേദനം: കേൾവിയുടെയും അനുസരണയുടെയും കാര്യത്തിലും എല്ലാ മുസ്ലിംകൾക്കും ഗുണംകാംക്ഷിക്കാം എന്നതിലും ഞാൻ നബി(സ)യോട് ഉടമ്പടി ചെയ്തു. (ന)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 143, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=70), 1, 'وَفِي رِوَايَةٍ: بَايَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، وَأَنْ أَنْصَحَ لِكُلِّ مُسْلِمٍ. (ن)', 'മറ്റൊരു നിവേദനം: കേൾവിയുടെയും അനുസരണയുടെയും കാര്യത്തിലും എല്ലാ മുസ്ലിംകൾക്കും ഗുണംകാംക്ഷിക്കാം എന്നതിലും ഞാൻ നബി(സ)യോട് ഉടമ്പടി ചെയ്തു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمْ نُبَايِعْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمَوْتِ، إِنَّمَا بَايَعْنَاهُ عَلَى أَنْ لَا نَفِرَّ. (ن)', 'ജാബിർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോട് മരണത്തിന്മേൽ ഉടമ്പടി ചെയ്തിട്ടില്ല. നിശ്ചയം. ഞങ്ങൾ അവിടുത്തോട് ഉടമ്പടി ചെയ്തത് ഞങ്ങൾ ഭയന്നോടുകയില്ലെന്നാണ്.(ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ يَعْلَى بْنِ أُمَيَّةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جِئْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَبِي أُمَيَّةَ يَوْمَ الْفَتْحِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، بَايِعْ أَبِي عَلَى الْهِجْرَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُبَايِعُهُ عَلَى الْجِهَادِ، وَقَدِ انْقَطَعَتِ الْهِجْرَةُ". (ن)', 'യഅ്ലബ്നു ഉമയ്യ(റ): മക്കാ വിജയ ദിവസം എന്റെ പിതാവായ ഉമയ്യ(റ)വുമായി റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ പിതാവിനോട് ഹിജ്റയുടെ കാര്യത്തിൽ ഉടമ്പടി ചെയ്താലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാനദ്ദേഹത്തോട് ധർമ്മസമരത്തിന്റെ കാര്യത്തിൽ ഉടമ്പടി ചെയ്യാം, നിശ്ചയം ഹിജ്റ മുറിഞ്ഞു പോയിരിക്കുന്നു." (ന)', 'يَعْلَى بْنِ أُمَيَّةَ', 'യഅ്ലബ്നു ഉമയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي جِئْتُ أُبَايِعُكَ عَلَى الْهِجْرَةِ، وَلَقَدْ تَرَكْتُ أَبَوَيَّ يَبْكِيَانِ؟ قَالَ: "ارْجِعْ إِلَيْهِمَا فَأَضْحِكْهُمَا كَمَا أَبْكَيْتَهُمَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പറഞ്ഞു: നിശ്ചയം അങ്ങയോട് ഹിജ്റയുടെ കാര്യത്തിൽ ഉടമ്പടി ചെയ്യാനാണ് ഞാൻ വന്നിരിക്കുന്നത്. നിശ്ചയം എന്റെ മാതാപിതാക്കളെ കരയുന്നവരായി ഞാൻ വിട്ടുപോന്നിരിക്കുകയാണ്? അവിടുന്ന് പറഞ്ഞു: "നീ അവരിലേക്ക് മടങ്ങിച്ചെന്ന് അവരെ കരയിപ്പിച്ചതു പോലെ ചിരിപ്പിക്കുക." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ لَهُ: أُبَايِعُكَ عَلَى السَّمْعِ وَالطَّاعَةِ، فِيمَا أَحْبَبْتُ وَفِيمَا كَرِهْتُ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَوَ تَسْتَطِيعُ ذَلِكَ يَا جَرِيرُ؟ أَوَ تُطِيقُ ذَلِكَ". قَالَ: "قُلْ: فِيمَا اسْتَطَعْتُ". فَبَايَعَنِي: وَالنُّصْحِ لِكُلِّ مُسْلِمٍ. (ن)', 'ജരീർ(റ): നബി(സ)യുടെ അടുക്കൽ ചെന്ന് ഞാൻ അവിടുത്തോട് പറഞ്ഞു: ഞാനിഷ്ടപ്പെടുന്ന കാര്യങ്ങളിലും വെറുക്കുന്ന കാര്യങ്ങളിലും അനുസരിക്കുകയും കേൾക്കുകയും ചെയ്യുമെന്ന് ഞാൻ അവിടുത്തോട് ഉടമ്പടി ചെയ്യുന്നു. നബി(സ) പറഞ്ഞു: "ജരീറേ, താങ്കൾക്കതിന് കഴിയുമോ, താങ്കൾക്കത് സാധിക്കുമോ?" അവിടുന്ന് പറഞ്ഞു: "കഴിവിന്റെ പരമാവധിയെന്ന് താങ്കൾ പറയുക." അങ്ങനെ അവിടുന്ന് എല്ലാ മുസ്ലിംകളോടുമുള്ള ഗുണകാംക്ഷ കൊണ്ടും എന്നോട് ഉടമ്പടി ചെയ്തു. (ന)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 144, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا نُبَايِعُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، ثُمَّ يَقُولُ: "فِيمَا اسْتَطَعْتَ". وَفِي رِوَايَةٍ: "فِيمَا اسْتَطَعْتُمْ". (م,د,ن,جه)', 'ഇബ്നുഉമർ(റ): കേൾക്കൽ, അനുസരിക്കൽ എന്നിവയുടെ മേൽ ഞങ്ങൾ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്യുമായിരുന്നു. പിന്നെ അവിടുന്ന് പറയും: "നിനക്ക് കഴിയുന്ന കാര്യങ്ങളിൽ." മറ്റൊരു നിവേദന പ്രകാരം: "നിങ്ങൾക്ക് കഴിയുന്ന കാര്യങ്ങളിൽ." (മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=4 and h.hadith_no=75), 1, 'وَفِي رِوَايَةٍ: "فِيمَا اسْتَطَعْتُمْ". (م,د,ن,جه)', 'മറ്റൊരു നിവേദന പ്രകാരം: "നിങ്ങൾക്ക് കഴിയുന്ന കാര്യങ്ങളിൽ." (മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنِ الشَّرِيدِ بْنِ سُوَيْدٍ الثَّقَفِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ فِي وَفْدِ ثَقِيفٍ رَجُلٌ مَجْذُومٌ، فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ارْجِعْ، فَقَدْ بَايَعْتُكَ". (ن)', 'ശരീദുബ്നു സുവൈദിസ്സഖഫി(റ): സഖീഫ് ഗോത്രക്കാരുടെ സംഘത്തിൽ കുഷ്ഠം രോഗം പിടിപെട്ട ഒരാളുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) ഒരാളെ അയച്ചുകൊണ്ട് അയാളോട് പറഞ്ഞു: "നീ മടങ്ങിപ്പോവുക, നിശ്ചയം ഞാൻ നിന്നോട് ഉടമ്പടി ചെയ്തിരിക്കുന്നു." (ന)', 'الشَّرِيدِ بْنِ سُوَيْدٍ الثَّقَفِيِّ', 'ശരീദുബ്നു സുവൈദിസ്സഖഫി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي حَازِمٍ قَالَ: قَاعَدْتُ أَبَا هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ خَمْسَ سِنِينَ، فَسَمِعْتُهُ يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَانَتْ بَنُو إِسْرَائِيلَ تَسُوسُهُمُ الْأَنْبِيَاءُ، كُلَّمَا هَلَكَ نَبِيٌّ خَلَفَهُ نَبِيٌّ، وَإِنَّهُ لَا نَبِيَّ بَعْدِي، وَسَتَكُونُ خُلَفَاءُ فَتَكْثُرُ". قَالُوا: فَمَا تَأْمُرُنَا؟ قَالَ: "فُوا بِبَيْعَةِ الْأَوَّلِ فَالْأَوَّلِ، وَأَعْطُوهُمْ حَقَّهُمْ، فَإِنَّ اللَّهَ سَائِلُهُمْ عَمَّا اسْتَرْعَاهُمْ". (م)', 'അബൂഹാസിം(റ): അഞ്ചു വർഷം ഞാൻ അബൂഹുറൈറ(റ)വിനോടൊന്നിച്ച് ഇരുന്നിട്ടുണ്ട്. റസൂൽ(സ) പറഞ്ഞതായി അദ്ദേഹം ഹദീസ് പറയുന്നത് അക്കാലത്ത് ഞാൻ കേട്ടിട്ടുണ്ട്, തിരുമേനി(സ) പറഞ്ഞു: "ബനൂ ഇസ്റാഇൗല്യരെ അമ്പിയാക്കളായിരുന്നു നയിച്ചിരുന്നത്. ഒരു നബി വഫാതാകുമ്പോഴെല്ലാം മറ്റൊരു നബി അദ്ദേഹത്തിന്റെ പ്രതിനിധിയായി വരും. നിശ്ചയം എന്റെ ശേഷം ഒരു നബിയും വരാനില്ല. എന്നാൽ പ്രതിനിധികളുണ്ടാകും, അവർ ധാരാളം പേരുണ്ടാകും." അവർ ചോദിച്ചു: അപ്പോൾ ഞങ്ങൾ എന്തു ചെയ്യണമെന്നാണ് അവിടുന്ന് കൽപിക്കുന്നത്? അവിടുന്ന് പറഞ്ഞു: "അവരോട് ചെയ്ത ഉടമ്പടി; ആദ്യം ഒന്നാമത്തെയാളോടും പിന്നെ അടുത്തയാളോടും എന്ന രീതിയിൽ നിങ്ങൾ പാലിക്കുക. അവരോടുള്ള കടമകൾ നിങ്ങൾ വീട്ടുക. നിശ്ചയം, അല്ലാഹു അവരോട് അവൻ അവരെ ഏൽപിച്ച ഭരണീയരെ സംബന്ധിച്ച് ചോദിക്കുന്നതാണ്." (മു)', 'أَبِي حَازِمٍ قَالَ', 'അബൂഹാസിം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ أَعْرَابِيًّا بَايَعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْإِسْلَامِ، فَأَصَابَ الْأَعْرَابِيَّ وَعْكٌ بِالْمَدِينَةِ، فَجَاءَ الْأَعْرَابِيُّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَقِلْنِي بَيْعَتِي. فَأَبَى، ثُمَّ جَاءَهُ فَقَالَ: أَقِلْنِي بَيْعَتِي. فَأَبَى، فَخَرَجَ الْأَعْرَابِيُّ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا الْمَدِينَةُ كَالْكِيرِ، تَنْفِي خَبَثَهَا وَتَنْصَعُ طِيبَهَا". (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നിശ്ചയം ഒരു അഅ്റാബി റസൂൽ(സ)യോട് ഇസ്ലാമിന്റെ കാര്യത്തിൽ ഉടമ്പടി ചെയ്തു. പിന്നീട് ആ അഅ്റാബിക്ക് മദീനയിൽ വെച്ച് ഒരു രോഗം പിടിപെട്ടു. അന്നേരമയാൾ റസൂൽ(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്നോട് ചെയ്ത ഉടമ്പടി അവിടുന്ന് തിരിച്ചെടുത്താലും. റസൂൽ അതിന് വിസമ്മതിച്ചു. പിന്നെയും അയാൾ വന്ന് പറഞ്ഞു: എന്നോട് ചെയ്ത ഉടമ്പടി അവിടുന്ന് തിരിച്ചെടുത്താലും. അപ്പോഴും അവിടുന്നതിന് വിസമ്മതിച്ചു. അപ്പോൾ അഅ്റാബി സ്ഥലം വിട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം മദീന ഉല പോലെയാണ്, അത് അതിലെ ന്യൂനതകളെ പുറന്തള്ളുകയും നല്ലതിനെ ശുദ്ധമാക്കുകയും ചെയ്യും." (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 145, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا يَوْمَ الْحُدَيْبِيَةِ أَلْفًا وَأَرْبَعَ مِائَةٍ، فَبَايَعْنَاهُ وَعُمَرُ رَضِيَ اللَّهُ عَنْهُ آخِذٌ بِيَدِهِ تَحْتَ الشَّجَرَةِ، وَهِيَ سَمُرَةٌ، وَقَالَ: بَايَعْنَاهُ عَلَى أَنْ لَا نَفِرَّ، وَلَمْ نُبَايِعْهُ عَلَى الْمَوْتِ. (م,ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഹുദൈബിയ്യാ ദിവസം ഞങ്ങൾ ആയിരത്തി നാനൂറ് പേരുണ്ടായിരുന്നു. അങ്ങനെ ഉമർ(റ) തിരുമേനി(സ)യുടെ കൈ പിടിച്ചുകൊണ്ടിരിക്കെ ആ മുൾമരത്തിനു ചുവട്ടിൽ വെച്ച് ഞങ്ങൾ അവിടുത്തോട് ഉടമ്പടി ചെയ്തു. ജാബിർ(റ) പറഞ്ഞു: ഞങ്ങൾ പിന്തിരിഞ്ഞോടുകയില്ല എന്ന വിഷയത്തിലാണ് (ഞങ്ങൾ) അവിടുത്തോട് ഉടമ്പടി ചെയ്തത്. മരണത്തിന്റെ കാര്യത്തിൽ ഞങ്ങൾ ഉടമ്പടി ചെയ്തിട്ടില്ല. (മു,തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ قَالَ: سَأَلْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا عَنْ أَصْحَابِ الشَّجَرَةِ؟ فَقَالَ: لَوْ كُنَّا مِائَةَ أَلْفٍ لَكَفَانَا، كُنَّا أَلْفًا وَخَمْسَ مِائَةٍ. (م)', 'സാലിമുബ്നു അബിൽജഅ്ദ്(റ): ''അസ്ഹാബുശ്ശജറ''യെ (മരത്തിൻ ചുവട്ടിൽവെച്ച് ഉടമ്പടി ചെയ്ത ആളുകളെ) സംബന്ധിച്ച് ഞാൻ ജാബിറുബ്നു അബ്ദില്ല(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ ഒരു ലക്ഷം പേരുണ്ടെങ്കിലും ഞങ്ങൾക്കത് (നബി(സ)യുടെ വിരലുകൾക്കിടയിലൂടെ വന്ന വെള്ളം) മതിയാകുമായിരുന്നു. അന്ന് ഞങ്ങൾ ആയിരത്തി അഞ്ഞൂറ് പേരായിരുന്നു. (മു)', 'سَالِمِ بْنِ أَبِي الْجَعْدِ قَالَ', 'സാലിമുബ്നു അബിൽജഅ്ദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ أَصْحَابُ الشَّجَرَةِ أَلْفًا وَثَلَاثَ مِائَةٍ، وَكَانَتْ أَسْلَمُ ثُمُنَ الْمُهَاجِرِينَ. (م)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): മരത്തിൻ ചുവട്ടിൽവെച്ച് ഉടമ്പടി ചെയ്തവർ ആയിരത്തി മുന്നൂറ് പേരായിരുന്നു. അസ്ലം ഗോത്രക്കാർ അന്ന് മുഹാജിറുകളുടെ എട്ടിലൊന്നേ ഉണ്ടായിരുന്നുള്ളൂ. (മു)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا، فِي قَوْلِهِ تَعَالَى: {لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ} [الفتح: ١٨] قَالَ جَابِرٌ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَنْ لَا نَفِرَّ، وَلَمْ نُبَايِعْهُ عَلَى الْمَوْتِ. حسن صحيح. (ت,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ''മരത്തിന്റെ ചുവട്ടിൽ വെച്ച് അങ്ങയോട് ഉടമ്പടി ചെയ്യുന്ന സന്ദർഭത്തിൽ അല്ലാഹു സത്യവിശ്വാസികളിൽ തൃപ്തനായിരിക്കുന്നു'' (ഫത്ഹ്: 18) എന്ന സൂക്തത്തെക്കുറിച്ച് ജാബിർ(റ) പറഞ്ഞു: ഞങ്ങൾ പിന്തിരിയുകയില്ല എന്ന വിഷയത്തിലാണ് (ഞങ്ങൾ) റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തത്. മരണത്തിന്റെ കാര്യത്തിൽ ഞങ്ങൾ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തിട്ടില്ല. (തു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], 'الفتح: ١٨', null, 146, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ يَزِيدَ بْنِ أَبِي عُبَيْدٍ قَالَ: قُلْتُ لِسَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ: عَلَى أَيِّ شَيْءٍ بَايَعْتُمْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْحُدَيْبِيَةِ؟ قَالَ: عَلَى الْمَوْتِ. حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'യസീദുബ്നു അബീഉബൈദ്(റ): ഞാൻ സലമതുബ്നുൽ അക്വഅ്(റ)വിനോട് ചോദിച്ചു: ഹുദൈബിയ്യ ദിവസം ഏതു കാര്യത്തിലാണ് നിങ്ങൾ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തത്? സലമ(റ) പറഞ്ഞു: മരണത്തിന്റെ കാര്യത്തിൽ. (ബു,മു,തു,ന)', 'يَزِيدَ بْنِ أَبِي عُبَيْدٍ قَالَ', 'യസീദുബ്നു അബീഉബൈദ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ عَبْدٌ فَبَايَعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْهِجْرَةِ، وَلَمْ يَشْعُرِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ عَبْدٌ، فَجَاءَ سَيِّدُهُ يُرِيدُهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بِعْنِيهِ". فَاشْتَرَاهُ بِعَبْدَيْنِ أَسْوَدَيْنِ، ثُمَّ لَمْ يُبَايِعْ أَحَدًا بَعْدَ ذَلِكَ حَتَّى يَسْأَلَهُ: أَعَبْدٌ هُوَ؟ (م,د,ت,ن,جه)', 'ജാബിർ(റ): ഒരു അടിമ വന്നുകൊണ്ട് ഹിജ്റയുടെ കാര്യത്തിൽ നബി(സ)യോട് ഉടമ്പടി ചെയ്തു. അദ്ദേഹം അടിമയായിരുന്നുവെന്ന് നബി(സ) അറിഞ്ഞിരുന്നില്ല. ശേഷം അദ്ദേഹത്തിന്റെ ഉടമ അദ്ദേഹത്തെ തേടിവന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവനെ നീ എനിക്ക് വിൽക്കുക." അങ്ങനെ രണ്ട് കറുത്ത അടിമകൾക്കു പകരം അദ്ദേഹത്തെ നബി(സ) വാങ്ങി. ശേഷം ''അവൻ അടിമയാണോ'' എന്ന് ചോദിക്കാതെ നബി(സ) ആരോടും ഉടമ്പടി ചെയ്തിട്ടില്ല. (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أُخْبِرْتُ عَنْ بَيْعَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النِّسَاءَ، قَالَتْ: مَا مَسَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ امْرَأَةٍ قَطُّ، إِلَّا أَنْ يَأْخُذَ عَلَيْهَا، فَإِذَا أَخَذَ عَلَيْهَا فَأَعْطَتْهُ قَالَ: "اذْهَبِي فَقَدْ بَايَعْتُكِ". (ق,د)', 'ആഇശ(റ): റസൂൽ(സ) സത്രീകളോട് ബൈഅത് ചെയ്തതിനെ സംബന്ധിച്ച് മഹതി പറയുന്നു: റസൂൽ(സ) സ്ത്രീകളോട് ഉടമ്പടി ചെയ്യുകയെന്നല്ലാതെ ഒരു സ്ത്രീയുടെയും കൈ സ്പർശിച്ചിട്ടില്ല. സ്ത്രീയോട് അവിടുന്ന് ഉടമ്പടി ചെയ്യുകയും കരാർ സ്വീകരിക്കുകയും ചെയ്താൽ അവിടുന്ന് പറയും: "നീ പോവുക, ഞാൻ നിന്നോട് ഉടമ്പടി ചെയ്തിരിക്കുന്നു." (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا أَرَدْتُ أَنْ أُبَايِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ امْرَأَةً أَسْعَدَتْنِي فِي الْجَاهِلِيَّةِ، فَأَذْهَبُ فَأُسْعِدُهَا ثُمَّ أَجِيئُكَ فَأُبَايِعُكَ. قَالَ: "اذْهَبِي فَأَسْعِدِيهَا". قَالَتْ: فَذَهَبْتُ فَسَاعَدْتُهَا ثُمَّ جِئْتُ، فَبَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ഉമ്മുഅതിയ്യ(റ): റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്യാൻ ഉദ്ദേശിച്ചപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അജ്ഞാന കാലത്ത് ഒരു സ്ത്രീ എന്നെ കരയാൻ (മരിച്ചയാൾക്കു വേണ്ടിയുള്ള വിലാപം) സഹായിച്ചിരുന്നു. അതിനാൽ ഞാൻ പോയി അവളെ (കരയാൻ) സഹായിക്കുകയും ശേഷം അങ്ങയുടെ അടുത്ത് വന്ന് ഉടമ്പടി ചെയ്യുകയും ചെയ്യട്ടെയോ? അവിടുന്ന് പറഞ്ഞു: "നീ പോയി അവളെ (കരയാൻ) സഹായിക്കുക." മഹതി പറയുന്നു: അപ്പോൾ ഞാൻ പോയി അവളെ സഹായിക്കുകയും ശേഷം തിരിച്ചുവന്ന് റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്യുകയും ചെയ്തു. (ന)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَخَذَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيْعَةَ عَلَى أَنْ لَا نَنُوحَ. (ن)', 'ഉമ്മുഅതിയ്യ(റ): മരിച്ചവരുടെ മേൽ ഞങ്ങൾ ഉച്ചത്തിൽ കരയുകയില്ലയെന്ന വിഷയത്തിൽ റസൂൽ(സ) ഞങ്ങളോട് ഉടമ്പടി ചെയ്തു. (ന)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا قَالَتْ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نِسْوَةٍ مِنَ الْأَنْصَارِ نُبَايِعُهُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، نُبَايِعُكَ عَلَى أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا، وَلَا نَسْرِقَ، وَلَا نَزْنِيَ، وَلَا نَأْتِيَ بِبُهْتَانٍ نَفْتَرِيهِ بَيْنَ أَيْدِينَا وَأَرْجُلِنَا، وَلَا نَعْصِيَكَ فِي مَعْرُوفٍ. قَالَ: "فِيمَا اسْتَطَعْتُنَّ وَأَطَقْتُنَّ". قَالَتْ: قُلْنَا: اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا، هَلُمَّ نُبَايِعْكَ يَا رَسُولَ اللَّهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَا أُصَافِحُ النِّسَاءَ، إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ. أَوْ: مِثْلُ قَوْلِي لِامْرَأَةٍ وَاحِدَةٍ". (ن)', 'ഉമൈമതു ബിൻതു റുവൈഖ(റ): ഉടമ്പടി ചെയ്യാൻവേണ്ടി, കുറേ അൻസ്വാരീ സ്ത്രീകളോടൊപ്പം ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു. ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിനോട് ഒന്നിനെയും പങ്കു ചേർക്കുകയില്ല, മോഷ്ടിക്കുകയില്ല, വ്യഭിചരിക്കുകയില്ല, ഒരാളെക്കുറിച്ചും കെട്ടിച്ചമച്ചുണ്ടാക്കിയ ആരോപണം ഞങ്ങൾ ഉന്നയിക്കുകയില്ല, ഒരു നന്മയിലും അങ്ങയോട് അനുസരണക്കേട് കാണിക്കുകയില്ല എന്നീ വിഷയങ്ങളിൽ ഞങ്ങൾ അങ്ങയോട് ഉടമ്പടി ചെയ്യുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് സാധ്യമാവുകയും കഴിയുകയും ചെയ്യുന്നയത്ര." മഹതി പറയുന്നു: ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലും ഞങ്ങളോട് ഏറ്റവും കരുണ ചെയ്യുന്നവരാണ്. അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയോട് ഞങ്ങൾ ഉടമ്പടി (ഹസ്തദാനം) ചെയ്യുന്നതിനു വേണ്ടി അങ്ങ് വന്നാലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഞാൻ സ്ത്രീകളോട് ഹസ്തദാനം ചെയ്യുകയില്ല. നിശ്ചയം ഞാൻ നൂറ് സ്ത്രീകളോട് സംസാരിക്കുന്നത് ഒരു സ്ത്രീയോട് സംസാരിക്കും പോലെത്തന്നെയാണ്. അല്ലെങ്കിൽ: ഒരു സ്ത്രീയോട് ഞാൻ സംസാരിക്കുന്നതിന് തുല്യം തന്നെയാണ്." (ന)', 'أُمَيْمَةَ بِنْتِ رُقَيْقَةَ', 'ഉമൈമതു ബിൻതു റുവൈഖ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: بَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نِسْوَةٍ، فَقَالَ لَنَا: "فِيمَا اسْتَطَعْتُنَّ وَأَطَقْتُنَّ". قُلْتُ: اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنَّا بِأَنْفُسِنَا. قُلْتُ: يَا رَسُولَ اللَّهِ، بَايِعْنَا. تَعْنِي: صَافِحْنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'ഉമൈമതുബിൻതു റുവൈഖ(റ): ചില സ്ത്രീകളോടൊപ്പം ഞാൻ റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തു. അപ്പോൾ റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞു: "നിങ്ങൾക്ക് കഴിയുകയും സാധ്യമാവുകയും ചെയ്യുന്ന കാര്യത്തിൽ". ഞാൻ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ ദൂതരും ഞങ്ങളേക്കാൾ ഞങ്ങളോട് കാരുണ്യമുള്ളവരാണ്. ഞാൻ പറഞ്ഞു: റസൂലേ, ഞങ്ങളോട് ഉടമ്പടി ചെയ്താലും - ഞങ്ങളോട് ഹസ്തദാനം ചെയ്താലും എന്നാണ് മഹതി ഉദ്ദേശിച്ചത് - അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നൂറ് സ്ത്രീകളോടുള്ള എന്റെ സംസാരം ഒരു സ്ത്രീയോടുള്ള എന്റെ സംസാരം പോലെത്തന്നെയാണ്." (തു,ന,ജ)', 'أُمَيْمَةَ بِنْتِ رُقَيْقَةَ', 'ഉമൈമതുബിൻതു റുവൈഖ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَتِ الْمُؤْمِنَاتُ، إِذَا هَاجَرْنَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُمْتَحَنَّ بِقَوْلِ اللَّهِ: {يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ} إِلَى آخِرِ الْآيَةِ. قَالَتْ عَائِشَةُ: فَمَنْ أَقَرَّ بِهَا مِنَ الْمُؤْمِنَاتِ فَقَدْ أَقَرَّ بِالْمِحْنَةِ. فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – إِذَا أَقْرَرْنَ بِذَلِكَ مِنْ قَوْلِهِنَّ – قَالَ لَهُنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "انْطَلِقْنَ، فَقَدْ بَايَعْتُكُنَّ". لَا – وَاللَّهِ – مَا مَسَّتْ يَدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ امْرَأَةٍ قَطُّ، غَيْرَ أَنَّهُ يُبَايِعُهُنَّ بِالْكَلَامِ. قَالَتْ عَائِشَةُ: وَاللَّهِ، مَا أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى النِّسَاءِ إِلَّا مَا أَمَرَهُ اللَّهُ، وَلَا مَسَّتْ كَفُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَفَّ امْرَأَةٍ قَطُّ، وَكَانَ يَقُولُ لَهُنَّ إِذَا أَخَذَ عَلَيْهِنَّ: "قَدْ بَايَعْتُكُنَّ". كَلَامًا. (ق,جه)', 'ആഇശ(റ): സത്യവിശ്വാസിനികളായ സ്ത്രീകൾ റസൂൽ(സ)യുടെ അടുത്തേക്ക് പലായനം ചെയ്താൽ ''സത്യവിശ്വാസിനികളായ സ്ത്രീകൾ ഉടമ്പടിക്കായി അങ്ങയുടെ അടുത്ത് വന്നാൽ'' എന്ന സൂക്തംകൊണ്ട് അവരുടെ വിശ്വാസം പരീക്ഷിക്കപ്പെടാറുണ്ടായിരുന്നു. ആഇശ(റ) പറയുന്നു: സത്യവിശ്വാസിനികളിൽ ഇക്കാര്യത്തെ സ്വീകരിച്ചവർ പരീക്ഷണത്തെ സ്വീകരിച്ചിരിക്കുകയാണ്. അങ്ങനെ അവരുടെ സംസാരത്തിൽ ആ വ്യവസ്ഥകളെ അവർ അംഗീകരിച്ചാൽ റസൂൽ(സ) അവരോട് ഇപ്രകാരം പറയും: "നിങ്ങൾ തിരിച്ചു പോവുക, ഞാൻ നിങ്ങളോട് ഉടമ്പടി ചെയ്തിരിക്കുന്നു." അല്ലാഹുവാണെ, റസൂൽ(സ)യുടെ കരം ഒരു സ്ത്രീയുടെയും കരത്തെ സ്പർശിച്ചട്ടില്ല. എന്നാൽ റസൂൽ(സ) സ്ത്രീകളോട് സംസാരം കൊണ്ടായിരുന്നു ഉടമ്പടി ചെയ്തിരുന്നത്. ആഇശ(റ) പറഞ്ഞു: അല്ലാഹു സത്യം, റസൂൽ(സ) അല്ലാഹു പറഞ്ഞ കാര്യങ്ങളിലല്ലാതെ സ്ത്രീകളോട് ഉടമ്പടിചെയ്തിട്ടില്ല. റസൂൽ(സ)യുടെ മുൻകൈ ഒരു സ്ത്രീയുടെയും മുൻകൈയുമായി സ്പർശിച്ചിട്ടില്ല. സ്ത്രീകളോട് കരാർ ചെയ്തുകഴിഞ്ഞാൽ റസൂൽ(സ) അവരോട് ഇപ്രകാരം വാക്കാൽ പറയാറുണ്ടായിരുന്നു: "ഞാൻ നിങ്ങളോട് ഉടമ്പടിചെയ്തിരിക്കുന്നു." (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 148, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ وَلَا يَنْظُرُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ: رَجُلٌ عَلَى فَضْلِ مَاءٍ بِالْفَلَاةِ يَمْنَعُهُ مِنِ ابْنِ السَّبِيلِ. وَرَجُلٌ بَايَعَ رَجُلًا بِسِلْعَةٍ بَعْدَ الْعَصْرِ، فَحَلَفَ بِاللَّهِ لَأَخَذَهَا بِكَذَا وَكَذَا، فَصَدَّقَهُ، وَهُوَ عَلَى غَيْرِ ذَلِكَ. وَرَجُلٌ بَايَعَ إِمَامًا، لَا يُبَايِعُهُ إِلَّا لِدُنْيَا: فَإِنْ أَعْطَاهُ مِنْهَا وَفَى لَهُ، وَإِنْ لَمْ يُعْطِهِ مِنْهَا لَمْ يَفِ لَهُ". (ق,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് കൂട്ടരിലേക്ക് അന്ത്യനാളിൽ അല്ലാഹു നോക്കുകയില്ല, അവരോട് സംസാരിക്കുകയില്ല, അവരെ സംശുദ്ധമാക്കുകയില്ല, അവർക്ക് ശക്തമായ ശിക്ഷയുമുണ്ട്. ഒരാൾ, മരുഭൂമിയിൽവെച്ച് തന്റെ പക്കൽ മിച്ചം വന്ന വെള്ളം യാത്രക്കാർക്ക് നൽകാതെ തടഞ്ഞ് വെക്കുന്നവനാണ്. മറ്റൊരാൾ, സായാഹ്ന സമയത്ത് ഒരു വ്യക്തിയിൽ നിന്ന് ഒരു സാധനം വാങ്ങുന്നു. ശേഷം, ഇത്ര തുകയ്ക്ക് പകരമാണ് താൻ അത് വാങ്ങിയതെന്ന് അവൻ അല്ലാഹുവിനെ മുൻനിർത്തി സത്യം ചെയ്യുകയും മറ്റെയാൾ അത് വിശ്വസിക്കുകയും ചെയ്യുന്നു. യഥാർത്ഥത്തിൽ അവൻ ആ തുകയ്ക്കായിരുന്നില്ല വാങ്ങിയിരുന്നത്. മറ്റൊരാൾ, ഒരു ഇമാമുമായി ഐഹിക ആവശ്യത്തിനായി ഉടമ്പടി ചെയ്യുന്നു. ഐഹിക കാര്യങ്ങളിൽ വല്ലതും അവന് നൽകിയാൽ അവൻ അത് പൂർത്തിയാക്കും, നൽകിയില്ലെങ്കിൽ പൂർത്തിയാക്കുകയുമില്ല." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ بَنِي إِسْرَائِيلَ كَانَتْ تَسُوسُهُمْ أَنْبِيَاؤُهُمْ، كُلَّمَا ذَهَبَ نَبِيٌّ خَلَفَهُ نَبِيٌّ، وَأَنَّهُ لَيْسَ كَائِنٌ بَعْدِي نَبِيٌّ فِيكُمْ". قَالُوا: فَمَا يَكُونُ يَا رَسُولَ اللَّهِ؟ قَالَ: "تَكُونُ خُلَفَاءُ فَيَكْثُرُوا". قَالُوا: فَكَيْفَ نَصْنَعُ؟ قَالَ: "أَوْفُوا بِبَيْعَةِ الْأَوَّلِ فَالْأَوَّلِ، أَدُّوا الَّذِي عَلَيْكُمْ، فَسَيَسْأَلُهُمُ اللَّهُ عَزَّ وَجَلَّ عَنِ الَّذِي عَلَيْهِمْ". (ق,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ബനൂഇസ്റാഇൗല്യരെ ഭരിച്ചിരുന്നത് അവരുടെ പ്രവാചകന്മാരായിരുന്നു. ഒരു പ്രവാചകൻ മരിച്ചാൽ മറ്റൊരു പ്രവാചകൻ ശേഷം വരുമായിരുന്നു. നിശ്ചയം എന്റെ ശേഷം നിങ്ങളിൽ ഒരു പ്രവാചകനുണ്ടാവില്ല." അവർ ചോദിച്ചു: പിന്നെ എന്താണുണ്ടാവുക റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "പ്രതിനിധികളുണ്ടാവും. അവർ അധികരിക്കും." അവർ ചോദിച്ചു: അപ്പോൾ ഞങ്ങൾ എന്താണ് ചെയ്യേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "ഉടമ്പടികളെ ക്രമാനുസരണം നിങ്ങൾ പൂർത്തീകരിക്കുക. നിങ്ങളുടെ ഉത്തരവാദിത്തങ്ങളെ നിങ്ങൾ വീട്ടുക. ആ പ്രതിനിധികളോട് അവരുടെ ഉത്തരവാദിത്തങ്ങളെക്കുറിച്ച് അല്ലാഹു ചോദിക്കുന്നതാണ്." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 149, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُنْصَبُ لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ، فَيُقَالُ: هَذِهِ غَدْرَةُ فُلَانٍ". (ق,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "കരാർ ലംഘിക്കുന്ന എല്ലാവർക്കും അന്ത്യനാളിൽ ഒരു കൊടി നാട്ടപ്പെടും. എന്നിട്ട് ഇപ്രകാരം പറയപ്പെടും: ഇത് ഇന്നയാളുടെ കരാർലംഘനമാണ്." (ബു,മു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا إِنَّهُ يُنْصَبُ لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ بِقَدْرِ غَدْرَتِهِ". [ز: في إسناده ضعيف] (جه)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "കരാർ ലംഘിച്ചവർക്കെല്ലാം അവരുടെ കരാർലംഘനത്തിന്റെ തോതനുസരിച്ച് അന്ത്യനാളിൽ ഒരു കൊടി നാട്ടപ്പെടുന്നതാണ്." ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ الْهِرْمَاسِ بْنِ زِيَادٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَدَدْتُ يَدِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا غُلَامٌ لِيُبَايِعَنِي، فَلَمْ يُبَايِعْنِي. (ن)', 'ഹിർമാസുബ്നു സിയാദ്(റ): ഞാൻ കുട്ടിയായിരിക്കെ, നബി(സ) എന്നോട് ഉടമ്പടി ചെയ്യുന്നതിനുവേണ്ടി ഞാൻ എന്റെ കൈ നീട്ടി. എന്നാൽ അവിടുന്നെന്നോട് ഉടമ്പടി ചെയ്തില്ല. (ന)', 'الْهِرْمَاسِ بْنِ زِيَادٍ', 'ഹിർമാസുബ്നു സിയാദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ طَارِقِ بْنِ شِهَابٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ وَضَعَ رِجْلَهُ فِي الْغَرْزِ: أَيُّ الْجِهَادِ أَفْضَلُ؟ قَالَ: "كَلِمَةُ حَقٍّ عِنْدَ سُلْطَانٍ جَائِرٍ". (ن)', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ): ഒരാൾ ജീനിച്ചവിട്ടിൽ കാല് വെച്ചുകൊണ്ട് നബി(സ)യോട് ചോദിച്ചു: ഏത് ധർമ്മസമരമാണ് ഏറ്റവും ഉത്തമമായത്? അവിടുന്ന് പറഞ്ഞു: "ക്രൂരനായ ഭരണാധികാരിയുടെ മുന്നിൽ സത്യവചനം തുറന്നു പറയൽ." (ന)', 'طَارِقِ بْنِ شِهَابٍ', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَرْفَجَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّهُ سَتَكُونُ هَنَاتٌ وَهَنَاتٌ، فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ هَذِهِ الْأُمَّةِ – وَهِيَ جَمِيعٌ – فَاضْرِبُوهُ بِالسَّيْفِ، كَائِنًا مَنْ كَانَ". (م)', 'അർഫജ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം കുറേ കുഴപ്പങ്ങൾ ഉണ്ടാകും. അപ്പോൾ ഈ സമുദായത്തിന്റെ ഏകോപിതമായ കാര്യത്തിൽ ഭിന്നിപ്പുണ്ടാക്കാൻ ആരെങ്കിലും ആഗ്രഹിച്ചാൽ, എന്തുതന്നെ സംഭവിക്കുകയാണെങ്കിലും, നിങ്ങളവനെ വാളുകൊണ്ട് വെട്ടുക." (മു)', 'عَرْفَجَةَ', 'അർഫജ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 150, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَبِي بُرْدَةَ قَالَ: قَالَ أَبُو مُوسَى رَضِيَ اللَّهُ عَنْهُ: أَقْبَلْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعِي رَجُلَانِ مِنَ الْأَشْعَرِيِّينَ، أَحَدُهُمَا عَنْ يَمِينِي وَالْآخَرُ عَنْ يَسَارِي، فَكِلَاهُمَا سَأَلَ الْعَمَلَ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَاكُ، فَقَالَ: "مَا تَقُولُ يَا أَبَا مُوسَى؟ أَوْ: يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ". قَالَ: فَقُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا، وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ، قَالَ: وَكَأَنِّي أَنْظُرُ إِلَى سِوَاكِهِ تَحْتَ شَفَتِهِ وَقَدْ قَلَصَتْ، فَقَالَ: "لَنْ – أَوْ: لَا – نَسْتَعْمِلَ عَلَى عَمَلِنَا مَنْ أَرَادَهُ، وَلَكِنِ اذْهَبْ أَنْتَ يَا أَبَا مُوسَى، أَوْ: يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ". فَبَعَثَهُ عَلَى الْيَمَنِ، ثُمَّ أَتْبَعَهُ مُعَاذَ بْنَ جَبَلٍ، فَلَمَّا قَدِمَ عَلَيْهِ قَالَ: انْزِلْ، وَأَلْقَى لَهُ وِسَادَةً، وَإِذَا رَجُلٌ عِنْدَهُ مُوثَقٌ، قَالَ: مَا هَذَا؟ قَالَ: هَذَا كَانَ يَهُودِيًّا فَأَسْلَمَ، ثُمَّ رَاجَعَ دِينَهُ دِينَ السَّوْءِ فَتَهَوَّدَ، قَالَ: لَا أَجْلِسُ حَتَّى يُقْتَلَ، قَضَاءُ اللَّهِ وَرَسُولِهِ، فَقَالَ: اجْلِسْ، نَعَمْ، قَالَ: لَا أَجْلِسُ حَتَّى يُقْتَلَ، قَضَاءُ اللَّهِ وَرَسُولِهِ. ثَلَاثَ مَرَّاتٍ، فَأَمَرَ بِهِ فَقُتِلَ، ثُمَّ تَذَاكَرَا الْقِيَامَ مِنَ اللَّيْلِ، فَقَالَ أَحَدُهُمَا – مُعَاذٌ – أَمَّا أَنَا فَأَنَامُ وَأَقُومُ، وَأَرْجُو فِي نَوْمَتِي مَا أَرْجُو فِي قَوْمَتِي. (ق)', 'അബൂബുർദ(റ): അബൂമൂസാ(റ) പറഞ്ഞു: അശ്അരി ഗോത്രത്തിൽപെട്ട രണ്ടാളുകളോടൊന്നിച്ച് ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു. അവരിൽ ഒരാൾ എന്റെ വലതു ഭാഗത്തും മറ്റെയാൾ ഇടതു ഭാഗത്തുമായിരുന്നു. അവർ രണ്ടുപേരും ഉദ്യോഗം ആവശ്യപ്പെട്ടു. അന്നേരം നബി(സ) മിസ്വാക് ചെയ്തുകൊണ്ടിരിക്കുകയായിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "അബൂമൂസാ, അല്ലെങ്കിൽ: അബ്ദുല്ലാഹിബ്നു ഖൈസേ, നിനക്കെന്താണ് പറയാനുള്ളത്." അദ്ദേഹം പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെയാണ് സത്യം, അവരുടെ മനസ്സിലുള്ളത് അവരെന്നെ അറിയിച്ചിരുന്നില്ല, അവർ ഉദ്യോഗം ആവശ്യപ്പെട്ടാണ് വരുന്നതെന്ന് ഞാൻ അറിഞ്ഞിരുന്നില്ല. അദ്ദേഹം പറയുന്നു: റസൂൽ(സ)യുടെ ചുണ്ടിനടിയിൽ പറ്റിനിൽക്കുന്ന അവിടുത്തെ മിസ്വാക് ഞാനിപ്പോഴും കാണുന്നതു പോലെയുണ്ട്. അവിടുന്ന് പറഞ്ഞു: "നമ്മുടെ ഉദ്യോഗത്തിൽ അതിനെ ആഗ്രഹിക്കുന്നവരെ നാം നിയമിക്കുകയില്ല. എന്നാൽ അബൂമൂസാ, അല്ലെങ്കിൽ: അബ്ദുല്ലാഹിബ്നു ഖൈസേ, നീ (ഗവർണ്ണറായി) പോവുക." അങ്ങനെ അവിടുന്ന് അദ്ദേഹത്തെ യമനിലെ ഗവർണ്ണറായിട്ട് പറഞ്ഞയച്ചു. ശേഷം മുആദുബ്നു ജബൽ(റ)വിനെ അദ്ദേഹത്തിനു പിറകെ പറഞ്ഞയച്ചു. മുആദ്(റ) അദ്ദേഹത്തിനടുത്ത് എത്തിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: താങ്കൾ ഇറങ്ങുക. അദ്ദേഹത്തിനൊരു തലയിണയും വെച്ചുകൊടുത്തു. അപ്പോൾ ബന്ധിതനായി കിടക്കുന്ന ഒരാളെ അവിടെ കണ്ടു. മുആദ്(റ) ചോദിച്ചു: എന്താണിത്? അബൂമൂസാ(റ) പറഞ്ഞു: ഇവൻ ഒരു ജൂതനായിരുന്നു, ശേഷം മുസ്ലിമായി. വീണ്ടും അവൻ ദുഷിച്ച തന്റെ പഴയ മതം സ്വീകരിക്കുകയും ജൂതനാവുകയും ചെയ്തിരിക്കുന്നു. മുആദ്(റ) പറഞ്ഞു: അവൻ വധിക്കപ്പെടുന്നതു വരെ ഞാൻ ഇരിക്കുകയില്ല. ഇത് അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും വിധിയാണ്. അബൂമൂസാ(റ) പറഞ്ഞു: അതെ, താങ്കൾ ഇരിക്കുക. മുആദ്(റ) പറഞ്ഞു: അവൻ വധിക്കപ്പെടുന്നതുവരെ ഞാൻ ഇരിക്കുകയില്ല, ഇത് അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും വിധിയാണ്. മൂന്നു പ്രാവശ്യം അപ്രകാരം പറഞ്ഞു. അപ്പോൾ അബൂമൂസാ(റ) അവനെ വധിക്കാൻ കൽപിച്ചതു പ്രകാരം അവൻ വധിക്കപ്പെട്ടു. ശേഷം രാത്രിയിലെ നമസ്കാരത്തെ സംബന്ധിച്ച് അവർ രണ്ടുപേരും സംസാരിച്ചു. അപ്പോൾ അവരിലൊരാൾ - മുആദ്(റ) - പറഞ്ഞു: ഞാൻ ഉറങ്ങുകയും നമസ്കരിക്കുകയും ചെയ്യാറുണ്ട്. എന്റെ നമസ്കാരത്തിൽ കിട്ടുന്ന പുണ്യം എന്റെ ഉറക്കിലും കിട്ടുമെന്ന് ഞാൻ പ്രതീക്ഷിക്കുന്നു. (ബു,മു).', 'أَبِي بُرْدَةَ قَالَ', 'അബൂബുർദ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا، وَمَنْ غَشَّنَا فَلَيْسَ مِنَّا". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നമുക്കെതിരിൽ ആയുധമെടുക്കുന്നവൻ നമ്മിൽ പെട്ടവനല്ല, നമ്മെ വഞ്ചിക്കുന്നവൻ നമ്മിൽ പെട്ടവനല്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ يَرْضَى لَكُمْ ثَلَاثًا، وَيَكْرَهُ لَكُمْ ثَلَاثًا: فَيَرْضَى لَكُمْ أَنْ تَعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَأَنْ تَعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا. وَيَكْرَهُ لَكُمْ: قِيلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ، وَإِضَاعَةَ الْمَالِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങൾക്ക് മൂന്നു കാര്യങ്ങൾ തൃപ്തിപ്പെടുകയും മൂന്നു കാര്യങ്ങൾ വെറുക്കുകയും ചെയ്യുന്നു. നിങ്ങൾ അവനെ ആരാധിക്കുക, അവനോട് ഒന്നിനെയും പങ്കു ചേർക്കാതിരിക്കുക, ഭിന്നിക്കാതെ ഒന്നിച്ച് അല്ലാഹുവിന്റെ പാശം മുറുകെപ്പിടിക്കുക എന്നിവയാണ് അവൻ നിങ്ങൾക്ക് തൃപ്തിപ്പെടുന്നത്. കേട്ടുകേൾവി (പ്രചരിപ്പിക്കൽ), അധികമായി ചോദ്യമുന്നയിക്കൽ, മുതൽ ദുർവ്യയം ചെയ്യൽ എന്നിവയാണ് അവൻ നിങ്ങൾക്ക് വെറുക്കുന്നത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ سَعْدِ بْنِ إِبْرَاهِيمَ قَالَ: سَأَلْتُ الْقَاسِمَ بْنَ مُحَمَّدٍ عَنْ رَجُلٍ لَهُ ثَلَاثَةُ مَسَاكِنَ، فَأَوْصَى بِثُلُثِ كُلِّ مَسْكَنٍ مِنْهَا. قَالَ: يُجْمَعُ ذَلِكَ كُلُّهُ فِي مَسْكَنٍ وَاحِدٍ، ثُمَّ قَالَ: أَخْبَرَتْنِي عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ". (م)', 'സഅ്ദുബ്നു ഇബ്റാഹീം(റ): മൂന്ന് പാർപ്പിടങ്ങളുള്ള വ്യക്തി അവയിൽ ഓരോ പാർപ്പിടത്തിന്റെയും മൂന്നിലൊന്ന് വസ്വിയ്യത് ചെയ്തതിനെ സംബന്ധിച്ച് ഞാൻ ഖാസിമുബ്നു മുഹമ്മദ്(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അവ മുഴുവൻ ഒരു പാർപ്പിടത്തിൽ ഒരുമിച്ചു കൂട്ടപ്പെടും (ഒരു പാർപ്പിടത്തെ മൊത്തം പാർപ്പിടങ്ങളുടെ മൂന്നിലൊന്നായി ഗണിക്കപ്പെടും). ശേഷം അദ്ദേഹം പറഞ്ഞു: എനിക്ക് ആഇശ(റ) ഇപ്രകാരം പറഞ്ഞുതന്നു: റസൂൽ(സ) പറഞ്ഞു: "നമ്മുടെ കാര്യത്തിനനുസൃതമല്ലാത്ത ഒരു പ്രവർത്തനം ആരെങ്കിലും പ്രവർത്തിച്ചാൽ അത് തട്ടപ്പെടേണ്ടതാണ്." (മു)', 'سَعْدِ بْنِ إِبْرَاهِيمَ قَالَ', 'സഅ്ദുബ്നു ഇബ്റാഹീം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قِيلَ لَهُ: أَلَا تَدْخُلُ عَلَى عُثْمَانَ فَتُكَلِّمَهُ؟ فَقَالَ: أَتَرَوْنَ أَنِّي لَا أُكَلِّمُهُ إِلَّا أُسْمِعُكُمْ؟ وَاللَّهِ لَقَدْ كَلَّمْتُهُ فِيمَا بَيْنِي وَبَيْنَهُ مَا دُونَ أَنْ أَفْتَتِحَ أَمْرًا لَا أُحِبُّ أَنْ أَكُونَ أَوَّلَ مَنْ فَتَحَهُ، وَلَا أَقُولُ لِأَحَدٍ يَكُونُ عَلَيَّ أَمِيرًا: إِنَّهُ خَيْرُ النَّاسِ، بَعْدَ مَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يُؤْتَى بِالرَّجُلِ يَوْمَ الْقِيَامَةِ فَيُلْقَى فِي النَّارِ، فَتَنْدَلِقُ أَقْتَابُ بَطْنِهِ، فَيَدُورُ بِهَا كَمَا يَدُورُ الْحِمَارُ بِالرَّحَى، فَيَجْتَمِعُ إِلَيْهِ أَهْلُ النَّارِ فَيَقُولُونَ: يَا فُلَانُ مَا لَكَ؟ أَلَمْ تَكُنْ تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ؟ فَيَقُولُ: بَلَى، قَدْ كُنْتُ آمُرُ بِالْمَعْرُوفِ وَلَا آتِيهِ، وَأَنْهَى عَنِ الْمُنْكَرِ وَآتِيهِ". (م)', 'ഉസാമതുബ്നു സൈദ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: താങ്കൾ ഉസ്മാൻ(റ)വിന്റെ അടുത്ത് ചെന്ന് അദ്ദേഹവുമായി സംസാരിക്കുന്നില്ലെയോ? അദ്ദേഹം പറഞ്ഞു: അദ്ദേഹവുമായി സംസാരിക്കുന്നതെല്ലാം ഞാൻ നിങ്ങൾക്ക് കേൾപ്പിക്കുമെന്ന് (നിങ്ങൾക്ക്) അഭിപ്രായമുണ്ടോ? അല്ലാഹുവാണ് സത്യം, ഒരു കാര്യവും പുറത്ത് പറയുകയില്ല എന്ന ഉദ്ദേശത്തോടെ, എന്റെയും അദ്ദേഹത്തിന്റെയും ഇടയിലുള്ള കാര്യത്തെക്കുറിച്ച് ഞാൻ അദ്ദേഹവുമായി സംസാരിച്ചിട്ടുണ്ട്. അത് ആദ്യമായി പുറത്ത് പറയുന്നത് ഞാനാവുന്നത് ഞാൻ ഇഷ്ടപ്പെടുന്നില്ല. എന്റെ നേതാവാകുന്ന ഒരാളെക്കുറിച്ചും അവൻ ജനങ്ങളിൽ ഏറ്റവും ഉത്തമനാണെന്ന് ഞാൻ പറയുകയില്ല. റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് കേട്ടതിനു ശേഷമാണ് ഞാനങ്ങനെ ചെയ്തത്: (റസൂൽ(സ) പറഞ്ഞു:) "അന്ത്യനാളിൽ ഒരാളെ കൊണ്ടുവന്ന് നരകത്തിലിടും. അപ്പോൾ അവന്റെ വയറിന്റെ ഭാഗങ്ങൾ പുറത്തു വരികയും, കഴുത ആസുകല്ലിനെ ചുറ്റുന്നതു പോലെ അവൻ അതുമായി ചുറ്റുകയും ചെയ്യും. അന്നേരം നരക വാസികൾ അവന്റെ അടുത്ത് ഒരുമിച്ചു കൂടുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്യും: ഓ മനുഷ്യാ, നിനക്കെന്തു പറ്റി? നീ നന്മ കൽപിക്കുകയും തിന്മ നിരോധിക്കുകയും ചെയ്തിരുന്നില്ലേ? അവൻ പറയും: അതെ, ഞാൻ നന്മ കൽപിക്കാറുണ്ടായിരുന്നു, എന്നാലത് ചെയ്യാറുണ്ടായിരുന്നില്ല. ഞാൻ തിന്മ നിരോധിക്കാറുണ്ടായിരുന്നു, പക്ഷേ ഞാനത് ചെയ്യുമായിരുന്നു." (മു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 152, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: حَدَّثَتْنِي أُمُّ هَانِئٍ بِنْتُ أَبِي طَالِبٍ: أَنَّهَا أَجَارَتْ رَجُلًا مِنَ الْمُشْرِكِينَ يَوْمَ الْفَتْحِ، فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، فَقَالَ: "قَدْ أَجَرْنَا مَنْ أَجَرْتِ وَأَمَّنَّا مَنْ أَمَّنْتِ". (ق,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉമ്മുഹാനിഅ് ബിൻത് അബീത്വാലിബ്(റ) എന്നോട് പറഞ്ഞു: ഫത്ഹ് ദിവസം മഹതി ബഹുദൈവാരാധകരിൽപ്പെട്ട ഒരു പുരുഷന് അഭയം നൽകി. മഹതി നബി(സ)യുടെ അടുത്ത് പോയി വിവരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ അഭയം നൽകിയവർക്ക് നാം അഭയം നൽകിയിരിക്കുന്നു, നീ സംരക്ഷണം നൽകിയവർക്ക് നാമും സംരക്ഷണം നൽകിയിരിക്കുന്നു." (ബു,മു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنْ كَانَتِ الْمَرْأَةُ لَتُجِيرُ عَلَى الْمُؤْمِنِينَ فَيَجُوزُ. (د)', 'ആഇശ(റ): സത്യവിശ്വാസികൾക്ക് വേണ്ടി സ്ത്രീകൾ അഭയം നൽകുകയും അത് നടപ്പാവുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمَرْأَةَ لَتَأْخُذُ لِلْقَوْمِ" يَعْنِي: تُجِيرُ عَلَى الْمُسْلِمِينَ. حسن. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങൾക്കുവേണ്ടി സ്ത്രീക്ക് കരാർ സ്വീകരിക്കാം." അഥവാ മുസ്ലിംകൾക്കുവേണ്ടി സ്ത്രീ അഭയം നൽകാം. ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللَّهُ عَنْهَا، أَنَّهَا قَالَتْ: أَجَرْتُ رَجُلَيْنِ مِنْ أَحْمَائِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ أَمَّنَّا مَنْ أَمَّنْتِ". (ق,د,ت,ن)', 'ഉമ്മുഹാനിഅ്(റ): എന്റെ ഭർതൃകുടുംബത്തിൽപ്പെട്ട രണ്ടുപേർക്ക് ഞാൻ അഭയം നൽകി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ സംരക്ഷണം നൽകിയവർക്ക് നാമും സംരക്ഷണം നൽകിയിരിക്കുന്നു." (ബു,മു,ദ,തു,ന)', 'أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 154, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
